export const EXAM_FAQS: Record<string, Array<{ question: string; answer: string }>> = {
  'neet': [
    { question: "When will NEET (UG) 2026 be held, and how does the re-exam window affect a candidate's preparation timeline?", answer: "The National Testing Agency has fixed NEET (UG) 2026 for 21st June 2026 (Sunday), with the re-examination scheduled for 9th and 10th September 2026 for affected centres. Aspirants should treat June 21 as their primary milestone and keep September 9–10 blocked as a contingency buffer. Plan a full-length mock on or near each date so your stamina and revision rhythm match the actual testing window. Download the updated syllabus PDF now and map chapter weightage before April so the last 60 days go to revision, not exploration. Source: nta.ac.in" },
    { question: "Where is the official NEET (UG) 2026 syllabus PDF hosted, and what should students download first?", answer: "The updated NEET (UG) 2026 syllabus is hosted on the NTA portal for the academic session 2026-27 and was released on 8th January 2026. Aspirants should pull the latest PDF directly, cross-check it against the NCERT table of contents for Physics, Chemistry, and Biology (Botany + Zoology), and print a chapter-wise checklist. Anything not listed in this PDF is out of scope for 2026-27 admissions. Use the bulletin as your master checklist, not third-party guides, and tick chapters only after completing MCQs from each unit. Source: nta.ac.in" },
    { question: "Which body conducts NEET (UG) 2026, and what is the correct official URL candidates should bookmark?", answer: "NEET (UG) 2026 is conducted by the National Testing Agency (NTA), not by AIIMS, NMC, or any state board. The dedicated examination portal is neet.nta.nic.in, while nta.ac.in hosts the umbrella dashboard, information bulletins, and syllabus downloads. Bookmark only these two domains to avoid phishing clones that surface around registration deadlines. NTA also publishes verified updates through its official WhatsApp channel on the NEET portal, so enable those notifications the day registrations open. Source: neet.nta.nic.in" },
    { question: "What should candidates expect from NTA's official WhatsApp updates for the NEET (UG) 2026 re-examination?", answer: "NTA has activated an official WhatsApp updates channel specifically for NEET (UG) 2026 re-examination news, reachable via the announcement banner on neet.nta.nic.in. The channel pushes admit-card release alerts, centre-shift notices for the 9th–10th September re-exam, and result-day links the moment they go live. Activate it the same day you submit your application and pin the chat so notification banners from cloned numbers can never replace it. Treat WhatsApp as a speed alert, not the final authority; cross-check every message against the PDF bulletin on nta.ac.in. Source: neet.nta.nic.in" },
    { question: "How does the academic session 2026-27 labelling change a candidate's counselling and admission planning?", answer: "NEET (UG) 2026 admissions are processed against the academic session 2026-27, which means the scorecard will feed into MBBS, BDS, AYUSH, and veterinary counselling rounds that begin within weeks of the September re-exam result. Expect the first All India Quota allotment list by MCC (mcc.nic.in) shortly after results are declared, with state rounds following within a 10–14 day window. Keep your document folder — Class 10 & 12 marksheets, category certificate, PwD if applicable — pre-scanned at 200 DPI in PDF format, because MCC verification rejects low-resolution uploads. Source: mcc.nic.in" }
  ],
  'fmge': [
    { question: "What are the eligibility criteria to appear for FMGE 2026, and are there any category-based relaxations?", answer: "Indian citizens holding a primary medical qualification (MBBS or equivalent) from a foreign institution are eligible, provided the degree is recognized by the respective country's medical regulator and the candidate holds permanent or provisional registration from that country. The pass requirement is a minimum of 150 out of 300 marks (50%) for all candidates — FMGE does not prescribe separate qualifying percentages or age relaxations for SC/ST/OBC/PwD categories. Candidates must also ensure their medical college is WHO-recognized and the degree meets MCI/NMC screening norms before applying. Source: natboard.edu.in" },
    { question: "How is the FMGE 2026 question paper structured, and does negative marking apply?", answer: "The FMGE consists of 300 multiple-choice questions administered in two sessions of 150 questions each within a single day. Each correct response earns 1 mark and there is no negative marking — wrong answers carry no penalty, so you should attempt every question. The minimum qualifying score is 150 out of 300 (50%), with no separate sectional cut-off. Because nothing is deducted for an incorrect answer, never leave a question blank; make an educated guess on every item you are unsure of. The computer-based test is held at designated centres across India. Source: natboard.edu.in" },
    { question: "Which subjects carry the highest weightage in the FMGE 2026 syllabus audit?", answer: "The FMGE syllabus is divided into Pre-Clinical (~15%), Para-Clinical (~30%), and Clinical subjects (~50–55%). Clinical subjects dominate: Medicine and Surgery each yield approximately 30–35 questions, while OBG contributes 25–30 and Pediatrics 15–20 questions. Para-Clinical pillars include Pathology, Pharmacology, Microbiology, and Forensic Medicine/Community Medicine. When auditing your syllabus, prioritize these high-yield areas — mastering them effectively covers over half the paper. The exact chapter-wise distribution appears in the official FMGE information bulletin on natboard.edu.in. Source: natboard.edu.in" },
    { question: "What are the expected key dates for the FMGE December 2026 session?", answer: "NBEMS will release the official FMGE December 2026 notification approximately 2–3 months before the exam date. Based on historical patterns, the application window opens around August–September 2026 and remains active for 3–4 weeks. Critical deadlines include registration closure, fee payment cutoff, and the final edit window. Admit cards are typically downloadable 3–4 weeks before the test. Since NBEMS announces session-specific schedules independently, monitor natboard.edu.in and the FMGE information bulletin page every 2–3 weeks for the exact 2026 calendar. Source: natboard.edu.in" },
    { question: "How should candidates structure a syllabus audit and preparation plan for FMGE 2026?", answer: "Begin with a diagnostic self-assessment — take a full-length mock to identify weak subjects, high-weightage chapters, and topics left untouched. Cross-reference your analysis against the NBEMS FMGE syllabus to build a subject-wise completion checklist. Allocate disproportionately more time to Clinical subjects and high-yield Para-Clinical topics. Use standard MBBS textbooks for concept clarity and solve NBEMS-pattern MCQs daily. Schedule mandatory revision cycles every 10–15 days to prevent forgetting. Aspirants with 4–6 months before the exam should target finishing the first pass within 2–3 months, leaving ample time for mocks and targeted revision. Source: natboard.edu.in" }
  ],
  'jeemain': [
    { question: "What are the expected JEE Main 2026 exam session dates and when should I start registration?", answer: "Based on the standard NTA annual cycle, JEE Main 2026 Session 1 likely falls in January (typically last week of January) and Session 2 likely falls in April (typically second week). Registration for Session 1 usually opens in October–November of the preceding year. Aspirants should complete registration at least 2–3 weeks before the deadline to avoid last-minute technical issues. Keep valid email and mobile number active for OTP-based login on the NTA portal. Source: jeemain.nta.nic.in" },
    { question: "What is the application fee structure for JEE Main 2026 and where do I pay it?", answer: "For JEE Main 2026, the application fee is approximately ₹1,000 for male candidates in the general category (₹800 for female candidates) per session, with additional charges for appearing in both Paper 1 and Paper 2. SC/ST/PwD candidates typically pay ₹500. Payment is made online through the official NTA portal using net banking, UPI, or debit/credit card. Do not pay through third-party agents—NTA does not authorize intermediaries for fee collection. Source: nta.ac.in" },
    { question: "What is the age eligibility criterion for JEE Main 2026 and are there any relaxations?", answer: "NTA sets no age limit for JEE Main 2026. You may appear if you passed Class 12 (or equivalent) in 2024 or 2025, or if you are appearing in 2026, regardless of date of birth. Candidates who first passed Class 12 in 2023 or earlier are not eligible for this cycle. Individual institutes (IITs, NITs, and others) may still apply their own age rules at admission — check those prospectuses separately. There is no SC/ST/PwD age relaxation because there is no NTA age cap to relax. Source: jeemain.nta.nic.in" },
    { question: "What is the exam pattern and marking scheme for JEE Main 2026 Paper 1 (B.E./B.Tech)?", answer: "JEE Main 2026 Paper 1 comprises 75 compulsory questions — 25 per subject in Physics, Chemistry, and Mathematics, each subject split into Section A (20 MCQs) and Section B (5 numerical-value questions). Each correct answer awards 4 marks; each incorrect answer deducts 1 mark in both sections (since 2025 the Section B numericals are compulsory and negatively marked). The exam is conducted online (computer-based) for English and Hindi mediums. Total duration is 3 hours (3 hours 20 minutes for PwD candidates). The medium of exam must be selected carefully during registration—this cannot be changed after submission. Source: nta.ac.in" },
    { question: "How should I build a study plan for JEE Main 2026 given the revised syllabus?", answer: "Start by covering high-weightage chapters from Physics, Chemistry, and Mathematics based on the NTA-prescribed syllabus. Allocate 60% of study time to numerical-based chapters (Mechanics, Electrostatics, Organic Chemistry, Calculus) and 40% to theory-heavy chapters. Solve previous 5 years' JEE Main papers under timed conditions every fortnight. Join the official NTA Abhyas app for free practice tests. Do not rely solely on coaching material—supplement with NCERT Class 11–12 for conceptual clarity. Source: jeemain.nta.nic.in" }
  ],
  'jee-barch': [
    { question: 'What is JEE Main Paper 3 (B.Arch) and who is it for?', answer: 'JEE Main Paper 3 (B.Arch) is the architecture entrance exam conducted as part of JEE Main for admission to B.Arch and B.Planning programmes in NITs, SPA, and other Centrally Funded Technical Institutions. While B.E./B.Tech admissions use Paper 1 (PCM), B.Arch admissions require Paper 3 which includes Mathematics, Aptitude Test, and Drawing Test. Candidates interested in architectural design, urban planning, and building design should appear for Paper 3 in addition to or instead of Paper 1. After qualifying JEE Main B.Arch, candidates must also appear for a separate Architecture Aptitude Test (AAT) conducted by IISc Bangalore for IIT admissions. Source: NTA Information Bulletin 2026 (nta.ac.in) for Paper 3; JEE (Advanced) 2026 Information Brochure (jeeadv.ac.in) for the AAT. ' },
    { question: 'What is the JEE Main B.Arch exam pattern?', answer: 'JEE Main B.Arch (Paper 3) consists of three parts: Part I — Mathematics (20 MCQs + 5 Numerical Value questions, 100 marks total), Part II — General Aptitude Test (50 MCQs, 200 marks, covering areas like analytical reasoning, visual reasoning, logical thinking, design awareness), and Part III — Drawing Test (2 questions, 100 marks, testing sketch composition, architectural awareness, and freehand drawing). The exam is conducted offline (pen-and-paper) for Part III (Drawing sheet) and Part I-II on CBT. Total duration is 3 hours. Each correct answer carries 4 marks; 1 mark is deducted for wrong MCQ answers. Source: NTA Information Bulletin 2026 (nta.ac.in), which sets out Mathematics (Part-I) and Aptitude Test (Part-II) in Computer Based Test mode and Drawing Test (Part-III) in Pen and Paper Based mode. ' },
    { question: 'How does B.Arch admission through JEE Main work?', answer: 'After qualifying JEE Main (Paper 3), candidates participate in JoSAA counselling for seat allocation to NITs, SPAs, and other CFTIs offering B.Arch. B.Arch cut-offs move each admission cycle and differ sharply between institutes and programmes, so treat any single rank band circulating on coaching sites as unofficial. Read the opening and closing ranks JoSAA published for the previous cycle, for that specific institute and programme, and use those as your working estimate. The top architecture colleges in India include: SPA Delhi, NIT Hamirpur (Architecture), NIT Tiruchirappalli, School of Planning and Architecture Vijayawada, and CEPT Ahmedabad. For IITs offering B.Arch, candidates must qualify JEE Advanced AAT in addition to JEE Advanced. Source: JoSAA counselling guidelines (josaaa.nic.in) for seat allocation; JEE (Advanced) 2026 Information Brochure (jeeadv.ac.in) for the AAT. ' },
  ],
  'sat': [
    { question: 'What is the SAT and which universities require it?', answer: 'The SAT (Scholastic Assessment Test) is a standardised entrance exam used primarily for undergraduate admissions to universities in the United States and other countries. It is developed and administered by the College Board, a not-for-profit organisation. ETS is a common point of confusion here: ETS administers other tests such as the TOEFL and GRE, but not the SAT. The SAT tests reading, writing, and mathematics skills — the knowledge and skills students are expected to have acquired in high school. Most US universities require SAT or ACT scores as part of the undergraduate application. The SAT is also accepted by universities in Canada, the UK, Australia, Singapore, and other countries as part of international admissions. It is typically taken by students in Classes 10, 11, or 12. Source: College Board SAT Suite (satsuite.collegeboard.org), which states the SAT is run by the College Board, a not-for-profit organisation.' },
    { question: 'What is the SAT exam pattern?', answer: 'The SAT (Digital, 2023 onwards) consists of two sections: Reading and Writing (54 questions, 64 minutes) and Math (44 questions, 70 minutes). Total duration is 2 hours 14 minutes. The Reading and Writing section tests comprehension, vocabulary in context, and grammar. The Math section covers algebra, problem-solving, advanced math, and data analysis — with both calculator-permitted and no-calculator portions. Each section is scored 200–800, for a total score of 400–1600. The SAT is now conducted digitally at designated test centres. The College Board has also introduced the SAT School Day programme — students can take the SAT at their own school during the academic year. Source: College Board, How the SAT is Structured (satsuite.collegeboard.org/sat/whats-on-the-test/structure), which states the 64 minute, 70 minute and 2 hours 14 minute totals. Each section runs as two equal-length modules of escalating difficulty: the first module is shared by every test-taker, while the second is adaptive and depends on performance in the first.' },
    { question: 'What SAT score do I need for top universities?', answer: 'Most US universities publish median SAT scores for admitted students. No body — neither the College Board nor any college — publishes a universal cut-off, so treat any fixed band circulating on coaching sites as unofficial. The figure you can actually check is the middle 50% range that each college publishes for its own admitted class, running from the 25th to the 75th percentile. Compare your score against that range for the specific college and programme, and use the College Board user group percentiles as the national benchmark. Many universities have become test-optional post-2020 — meaning SAT scores are not required but submitting them can strengthen your application. For international students, a strong SAT score (1400+) significantly strengthens your application. Some universities also award merit scholarships based on SAT scores. Source: College Board score research (research.collegeboard.org) for user group percentiles; the middle 50% range is published in each admissions profile by the college itself.' },
  ],
  'act': [
    { question: 'What is the ACT and how does it compare to the SAT?', answer: 'The ACT (American College Testing) is a standardised entrance exam for US university admissions, like the SAT but with some key differences. The ACT scores English, Mathematics and Reading, with Science and Writing both optional. It is accepted by all US universities and many worldwide. While SAT has a stronger emphasis on vocabulary and reading, ACT has a dedicated Science section — making it more suitable for students who excel in science or prefer a more straightforward test format. Both tests are equally accepted by US universities — there is no preference for one over the other. Most Indian students take both and submit the better score.' },
    { question: 'What is the ACT exam pattern?', answer: 'The ACT has three required sections plus two optional add-ons: English (50 questions, 35 minutes — grammar, punctuation, sentence structure), Mathematics (45 questions, 50 minutes — algebra, geometry, trigonometry), and Reading (36 questions, 40 minutes — reading comprehension). The three required sections run 2 hours and 5 minutes in total. Science (40 questions, 40 minutes — data interpretation, scientific investigation, evaluating scientific arguments) is optional and brings the test to 2 hours and 45 minutes; Writing (1 essay, 40 minutes) is a further optional 40 minutes, making 3 hours and 25 minutes. Each section is scored 1–36. Since September 2025 the composite is the average of English, Mathematics and Reading only, so Science no longer affects it; take Science if you want a separate science score and a STEM score. With the optional Writing test, an additional score of 2–12 is reported. This is the enhanced ACT, in use since April 2025 for online national tests and September 2025 for all other administrations; the older four-section format is the legacy ACT. Source: act.org' },
    { question: 'ACT vs SAT — which should I take?', answer: 'Both are equally accepted by universities — choose based on your strengths: Take ACT if you excel in science and prefer direct, fact-based questions; prefer less vocabulary dependence; are strong in time management under pressure. Take SAT if you are a strong reader with good vocabulary; prefer reasoning-based questions over fact-based; do better with the SAT\'s calculator policy (more focused sections). Many Indian students take both — submit the higher score. Both tests are accepted for international admissions to the US. Since September 2025 the ACT composite is an average of English, Mathematics and Reading only, so a weak Science result no longer drags the composite down; take Science only if you want the separate science and STEM scores. Register for both if possible and take the one that goes better.' },
  ],
  'jeeadvanced': [
    { question: "Who qualifies to appear in JEE (Advanced) 2026 as an Indian national, and what is the Class XII marks cutoff?", answer: "An Indian-national candidate qualifies if they are among the top 2,50,000 rankers of JEE (Main) 2026 (B.E./B.Tech. paper), were born on or after 1 October 2006 (a relaxation of five years applies for SC/ST/PwD candidates, no upper limit for PwD), and satisfy the Class XII criterion. You must have passed the Class XII (or equivalent) board exam with at least five subjects in either the 2025 or 2026 session — candidates who first appeared in 2024 or earlier are disqualified. General/EWS candidates need 75% aggregate; SC/ST/PwD need 65%. Source: jeeadv.ac.in" },
    { question: "Are OCI/PIO cardholders eligible for JEE (Advanced) 2026, and which seats can they compete for?", answer: "Yes. OCI/PIO(I) candidates registered with an Indian foreign mission before 04 March 2021 may sit for JEE (Advanced) 2026 through the foreign-national route, but they must first qualify JEE (Main) 2026 and meet the Class XII marks rule (75% aggregate, five subjects). They are eligible only for seats in the Open category across IITs — they cannot claim OBC-NCL, SC, ST, or EWS reservation under the Persons of Indian Origin clause. The Information Brochure flags Clause 11 for the binding OCI/PIO eligibility language. Source: jeeadv.ac.in" },
    { question: "How many attempts does a candidate get at JEE (Advanced), and what is the year-of-passing rule for 2026?", answer: "A candidate may attempt JEE (Advanced) a maximum of two times, in consecutive years. For 2026, the candidate must have first appeared for the Class XII (or equivalent) qualifying examination in 2025 or 2026 — anyone who sat for the qualifying exam for the first time in 2024 or earlier is permanently ineligible. Candidates who cleared Class XII in 2023 and skipped a year must therefore reappear or skip JEE (Advanced) entirely; plan your drop-year decision carefully against this rule. Source: jeeadv.ac.in" },
    { question: "How are JEE (Advanced) 2026 qualifiers allotted to IITs, and when does JoSAA counselling open?", answer: "Seat allocation to the 23 IITs, IIIT-Bhubaneswar, IIIT-Allahabad, IIIT-Vadodara, and other JoSAA-accepting institutes runs centrally through JoSAA's online portal at josaa.nic.in, not on jeeadv.ac.in. Qualifiers must register, fill, and lock choices during the published JoSAA window (June–July 2026, typically five to six rounds including a special spot round). IIT admission requires both your JEE (Advanced) All India Rank and the 75%/65% Class XII criterion; missing the Class XII threshold makes you ineligible even with a top rank. Source: josaa.nic.in" },
    { question: "What is the special eligibility pathway for foreign nationals, and where is it documented?", answer: "Foreign-national candidates apply directly through a dedicated portal instead of routing through JEE (Main). The detailed clauses — SAT/ACT-based ranking, age criteria (born on or after 1 October 2006, with same PwD relaxation), minimum 75% aggregate in Class XII or equivalent with five subjects, and conversion-rules for overseas grade systems — are published at jeeadv.ac.in/foreign.html and carried as Clause 11 of the PDF Information Brochure. Foreign nationals are admitted only to the Open-category seats (no OBC-NCL/SC/ST/EWS quota) and through a separate fee structure, so review Clause 11 before submitting the December 2025–early 2026 application. Source: jeeadv.ac.in" }
  ],
  'upsc': [
    { question: "What is the stage-wise structure of the UPSC Civil Services Examination 2026, and how do the three tiers divide the marks?", answer: "The Civil Services Examination runs through three mandatory tiers: Preliminary (screening, objective-type, qualifying only — marks not counted for ranking), Main (written, merit-counting), and the Interview/Personality Test (275 marks). The Main stage carries 1,750 marks across nine papers (two qualifying language papers — Paper A Indian language, 300 marks, and Paper B English, 300 marks — plus seven counting papers: Essay 250, GS I–IV 250 each, and Optional Paper I & II 250 each). Final ranking is drawn from Main (1,750) + Interview (275) = 2,025 marks. Source: upsc.gov.in" },
    { question: "What are the confirmed 2026 calendar dates for the Civil Services Preliminary Examination, and how tight is the application window?", answer: "Notification No. 04/2026 was issued on 04/02/2026, with the last date to receive applications closing at 6:00 PM on 27/02/2026 — a roughly 23-day application window. The Preliminary examination is held on a single day: 24/05/2026, giving candidates about 86 days between application close and exam day. Aspirants should complete OTR registration, fee payment (₹100 for Gen/OBC; SC/ST/PwBD/Women exempt), and One Time choice of centre before the 27 February deadline. Source: upsc.gov.in" },
    { question: "What is the exact marking scheme and negative-marking penalty candidates must plan around in the Preliminary Examination?", answer: "Each GS Paper I question carries 2 marks, with one-third deduction per wrong answer — meaning four wrong answers cancel one correct one. Paper II (CSAT) is also 200 marks with the same 1/3 penalty but is only qualifying; aspirants need a minimum 33% (66 marks) to be screened in for evaluation of Paper I. Both papers are objective, 2 hours each. Plan your attempted-versus-accuracy ratio: at ~75% accuracy over 90 attempted questions, you score a safe net above the projected cutoff. Source: upsc.gov.in" },
    { question: "Which mandatory procedural change should first-time UPSC 2026 candidates complete before exam day?", answer: "Every candidate appearing at any UPSC venue in 2026 must undergo Face Authentication at the examination hall — this is a non-negotiable identity step added to the existing biometric and photo verification. Candidates must therefore complete OTR (One Time Registration) on upsconline.nic.in with a clear, recent photograph matching their Aadhaar/PAN, carry the same e-Admit Card photo, and reach the venue in time for the facial-recognition queue. Mismatch between registered face and physical appearance can lead to denied entry. Source: upsc.gov.in" },
    { question: "When did UPSC release the Main Examination 2026 timetable, and which papers are scheduled in the first week?", answer: "The Civil Services (Main) Examination 2026 Time Table was published on 10/07/2026 as document TT-CSM-2026-Engl-100726.pdf on the UPSC portal. The Main is conducted over 5–7 days with descriptive papers of 3 hours each, beginning with the compulsory Indian Language paper (Paper A) and English (Paper B) on consecutive days, followed by Essay, GS I, GS II, GS III, and GS IV. Optional Paper I and II close the schedule. Download the PDF the day it appears; mismatched dates have triggered candidate disqualifications in past cycles. Source: upsc.gov.in" }
  ],
  'pcat': [
    { question: 'What is the PCAT and which Philippine universities accept it?', answer: 'The PCAT (Philippine College Admissions Test) is a standardized entrance examination used by a number of colleges and universities in the Philippines for admission to undergraduate programmes. While not all Philippine universities require the PCAT, many use it as part of their holistic admissions process alongside students\' high school grades and interview performance. The exam tests verbal ability, quantitative skills, reading comprehension, and scientific reasoning. Students should check their target university\'s admission requirements directly as policies vary across institutions.' },
    { question: 'What is the NMAT Philippines and how does it differ from PCAT?', answer: 'The NMAT Philippines (National Medical Admission Test) is specifically for students seeking admission to medical schools in the Philippines — it is NOT the same as the PCAT. NMAT measures academic aptitude for medical studies specifically, covering Physics, Chemistry, Biology, and Mental Ability. PCAT is broader and used for general university admissions. If you are targeting medical school in the Philippines, you need the NMAT, not the PCAT. NMAT scores are also used for merit-based scholarships at some institutions.' },
  ],
  'uaeu-cat': [
    { question: 'What is the UAEU CAT and how does it work?', answer: 'The UAE Universities Common Admission Test (UAEU CAT) is an entrance examination conducted by the United Arab Emirates University (UAEU) for admission to its undergraduate programmes. UAEU is the oldest and most prestigious federal university in the UAE. The exam assesses candidates in English proficiency, mathematics, and reasoning abilities. It is primarily for students who have completed their secondary education (Grade 12) and are seeking admission to UAEU\'s degree programmes in fields including engineering, business, humanities, and science.' },
    { question: 'What is the exam pattern for UAEU CAT?', answer: 'The UAEU CAT typically consists of multiple-choice questions in three sections: English Language (grammar, vocabulary, reading comprehension), Mathematics (algebra, geometry, arithmetic), and Logical Reasoning/Analytical Skills. The exam is conducted online at designated test centres in the UAE. Candidates are given approximately 2–3 hours to complete the test. Some programmes may have additional subject-specific sections. Candidates should check the specific requirements for their intended programme on the UAEU admissions portal.' },
  ],
  'utbk': [
    { question: 'What is UTBK and how does it work?', answer: 'UTBK (Ujian Tulis Berbasis Komputer) is Indonesia\'s national computer-based university entrance exam, conducted by the National Testing Center (Pusat Penilaian Pendidikan) under the SNPMB system. It is mandatory for students seeking admission to most public universities through the SNBT (Seleksi Nasional Berdasarkan Tes) pathway. UTBK consists of the Academic Potential Test (TPA) covering verbal, numerical, and figural reasoning, plus subject-specific tests. The score is valid for one admission cycle only.' },
    { question: 'What is the UTBK exam pattern?', answer: 'UTBK consists of 195 questions to be answered in 195 minutes (3 hours 15 minutes). The test has two components: TPS (Tes Potensi Skolastik) — measuring academic potential through verbal reasoning, quantitative reasoning, and figural reasoning; and subject-specific tests (Matematika, Fisika, Kimia, Biologi, Sosiologi, Ekonomi, Sejarah, and/or Geografi depending on the study programme chosen). All questions are multiple-choice. The exam is computer-based at designated testing centres across Indonesia.' },
    { question: 'How is the UTBK score used for university admission?', answer: 'UTBK scores are used for two pathways: SNBP (Seleksi Nasional Berdasarkan Prestasi) — for high school rank-based admission without needing UTBK; and SNBT — the test-based selection requiring a UTBK score. The minimum score requirement varies by university and programme. Most competitive programmes at top universities (UI, UGM, ITB, IPB) require high UTBK scores (above 650–700 depending on subject combination). The score is combined with other criteria in the final admission decision.' },
  ],
  'qimiyah': [
    { question: "What is the Qimiyah 2026 examination, and which Saudi authority administers it?", answer: "The Qimiyah (قياس) is a standardized national test used for higher-education admission across Saudi Arabia. It is developed and administered by the National Center for Assessment (Qiyas), which operates as an independent body under the supervision of the Ministry of Education. The 2026 cycle follows the same structure used since 2024, with separate test administrations for high-school graduates and university applicants. Registration, scheduling, and score reporting are all handled through the Qiyas portal linked from the Ministry's higher-education section, and MoE approves the annual list of approved administrations and their validity periods. Source: moe.gov.sa" },
    { question: "Who is eligible to register for the Qimiyah 2026 cycle, and what ID is required?", answer: "Eligibility for the 2026 Qimiyah cycle is open to Saudi and resident male and female candidates who hold a valid national identity document — Saudi applicants use the national ID, while residents use Iqama. The Ministry of Education specifies that candidates must have completed upper-secondary education or be in their final year, and there is no upper age limit published in the admission guidelines. Each candidate may register only once per administration window, and the same ID cannot be used to book multiple seats. Source: moe.gov.sa" },
    { question: "What is the syllabus structure and subject distribution for the Qimiyah 2026 test?", answer: "The 2026 Qimiyah test specifications divide content into two main sections: Verbal (Arabic reading comprehension, vocabulary, and analogy) and Quantitative (arithmetic, algebra, geometry, statistics, and reasoning). MoE-cited specifications confirm roughly a 50/50 split between the two domains; confirm the exact item counts in the current Qiyas test blueprint before planning. The published blueprint lists the number of items per sub-skill, which candidates should map to a 6–8 week study plan. Source: moe.gov.sa" },
    { question: "What is the Qimiyah 2026 exam pattern, marking scheme, and duration?", answer: "The 2026 paper follows a computer-based multiple-choice format delivered in two language tracks — Arabic and English — as documented in the Ministry of Education higher-education admission guidelines. The total testing time is approximately 2.5 hours, split into the Verbal and Quantitative sections, with each correct answer carrying equal weight and no published negative marking in the 2026 specifications. Raw scores are converted to a standardized scaled score, and results are released on the Qiyas portal typically within 2–3 weeks of the test date. Source: moe.gov.sa" },
    { question: "What are the key 2026 dates, fees, and preparation resources for Qimiyah aspirants?", answer: "Registration for the 2026 Qimiyah administrations opens in rolling windows on the Qiyas portal, with the first major 2026 sitting typically scheduled in the first quarter and additional sittings spaced throughout the year. The non-refundable registration fee published on the official ETEC/Qiyas fee schedule is SAR 100 for the paper-based sitting and SAR 150 for the computerized sitting, payable online at booking. Free official preparation resources include the sample questions, the test blueprint, and the vocabulary list published under the Knowledge and Research section of moe.gov.sa, which aspirants should download before building a weekly study plan. Source: moe.gov.sa" }
  ],
  'cat': [
    { question: "When does CAT 2026 registration open, and what is the exact fee for each category?", answer: "CAT 2026 registration typically opens in the first week of August (notification expected by July 2025). The application fee is Rs 2,000 for General and EWS candidates, while SC, ST, and PwD applicants pay Rs 1,000. The fee is non-refundable and must be paid online via net banking, credit/debit cards, or UPI. Candidates appearing for the exam in multiple slots may attract additional charges. Register before the last date (usually mid-September) to avoid the late fee window. Keep your 10th, 12th, and bachelor's mark sheets ready for upload during form submission. Source: iimcat.ac.in" },
    { question: "How many questions appear in each section of CAT 2026, and what is the total exam duration?", answer: "CAT 2026 consists of three sections: Verbal Ability and Reading Comprehension (VARC) with 24 questions, Data Interpretation and Logical Reasoning (DILR) with 20 questions, and Quantitative Aptitude (QA) with 22 questions—totalling 66 questions and 198 marks. Each section is allotted exactly 40 minutes, making the entire computer-based test 120 minutes. Candidates cannot switch between sections freely; the interface enforces section-wise time limits. Negative marking applies (–1 for incorrect MCQs, no penalty for TITA questions). Source: iimcat.ac.in" },
    { question: "What is the minimum educational qualification required to appear for CAT 2026?", answer: "Candidates must hold a bachelor's degree in any discipline with a minimum of 50% marks (or an equivalent CGPA) from a recognized university or institute. Students in their final year of graduation are also eligible to apply, provided they complete all academic requirements before the admission process. There is no age limit for CAT 2026, and candidates from multiple academic backgrounds—including Engineering, Commerce, Arts, and Science—are equally eligible. Ensure your degree college is UGC-approved; foreign universities require an equivalence certificate from the competent authority. Source: iimcat.ac.in" },
    { question: "Which specific topics carry the highest weightage in the Quantitative Aptitude section for CAT 2026?", answer: "Based on the CAT 2026 syllabus, QA focuses on Arithmetic (percentages, profit-loss, time-work, Pipes and Cisterns), Algebra (quadratic equations, progressions, functions), Geometry and Mensuration, Number Systems, and Modern Math (permutations, probability, logarithms). Arithmetic alone accounts for roughly 7–8 questions in most years, making it the highest-weightage area. Geometry contributes 3–4 questions, while Modern Math typically has 2–3 questions. Focus your topic-wise quiz practice on Arithmetic first, then move to Geometry and Algebra. Source: iimcat.ac.in" },
    { question: "How should I use topic-wise quizzes to maximise my CAT 2026 preparation score?", answer: "Solve topic-wise quizzes daily under timed conditions—allocate 1.5 minutes per question for QA and DILR, and 1.8 minutes per VARC RC question. Start with weak areas first; track your accuracy per topic using a spreadsheet. Aim for 80%+ accuracy in Arithmetic and Geometry before moving to advanced modules. For DILR, practise at least two sets of 4-question DI and 4-question LR puzzles weekly. After each quiz, spend 10 minutes reviewing mistakes and noting the concept or reasoning gap. Repeat the same quiz after 7 days to test retention. Source: iimcat.ac.in" }
  ],
  'ioe-ent': [
    { question: 'What is IOE Entrance and how does Nepal engineering admission work?', answer: 'IOE Entrance (Institute of Engineering Entrance Examination) is Nepal\'s national-level engineering entrance exam, conducted by the Institute of Engineering at Tribhuvan University. It is the gateway for admission to Nepal\'s premier engineering programmes at Pulchowk Campus (the top engineering college in Nepal), Thapathali Campus, and other constituent engineering campuses across Nepal. IOE is highly competitive — over 30,000 students appear each year for approximately 1,500 seats in undergraduate engineering programmes. The exam is conducted annually, typically in June/July. The main programmes offered are B.E. (Bachelor of Engineering) in Civil, Computer, Electrical, Electronics, Mechanical, and other disciplines.' },
    { question: 'What is the IOE Entrance exam pattern?', answer: 'IOE Entrance is one paper carrying 150 multiple-choice questions, completed within 3 hours. The distribution is: Mathematics (60 questions), Physics (30 questions), and Chemistry (30 questions). Additionally, there is an English test (30 questions) covering grammar, vocabulary, and reading comprehension. A correct answer earns 1 mark, whereas an incorrect one deducts 0.25 marks. The exam is conducted offline (pen-and-paper) at designated centres in Nepal. The difficulty level is comparable to the Nepal Class 12 Board exam (Science faculty). The questions are based on the NEB (National Examination Board) Class 11-12 curriculum.' },
    { question: 'What rank do I need for IOE admission to top campuses?', answer: 'The IOE merit list is national-level and highly competitive. For admission to Pulchowk Campus (the most prestigious — Civil, Computer, Electrical, Electronics Engineering), a rank within the top 200 is typically required. For Thapathali Campus (Mechanical, Civil, Computer), a rank within the top 1,000 is needed. For other constituent campuses (Paschimanchal, Nepal Engineering College, etc.), a rank within the top 3,000–5,000 is competitive. The IOE counselling process allocates seats based on rank and student preferences across campuses and disciplines. IOE scores are also accepted by some private engineering colleges in Nepal as part of their admission process.' },
  ],
  'cs-exec': [
    { question: 'What is CS Executive and how does it work?', answer: 'CS Executive (Company Secretary Executive) is the second level of the Company Secretary qualification conducted by ICSI (Institute of Company Secretaries of India). The three levels are: Foundation → Executive → Professional. Students who have cleared CS Executive or graduates in any discipline can directly appear for CS Executive. The CS Executive programme covers corporate law, company accounts, tax law, and management accounting. After passing CS Executive, students must complete 15 months of practical training (articleship) before appearing for CS Professional. A Company Secretary is a legal compliance professional for companies — distinct from Chartered Accountants.' },
    { question: 'What is the CS Executive exam pattern?', answer: 'CS Executive has two modules, each with 4 papers (8 papers total): Module 1 — Company Accounts & Auditing Practices, Tax &Labour Laws, Capital Markets & Corporate Laws; Module 2 — Corporate & Management Accounting, Securities Laws & Capital Markets, Economic & Commercial Laws. Exams are held twice a year (June and December). Each paper is of 100 marks (70 marks written + 30 marks practical/case study). Students must score 40% in each paper and 50% aggregate in each module to pass. Negative marking applies (0.25 per wrong answer for objective parts).' },
    { question: 'How should I prepare for CS Executive exams?', answer: 'CS Executive has a low pass rate — typically 5–15% in each paper — making it one of the tougher professional exams. The key is focusing on the Company Accounts and Tax papers, which are the highest-scoring. ICSI study material (both Module-wise and Practice Manuals) is essential. MCQs and case studies carry significant weight, so practice previous year question papers thoroughly. Join a test series 2 months before exams to build speed. Many students take multiple attempts — the exam tests depth of legal knowledge rather than just memory.' },
  ],
  'cma': [
    { question: 'What is CMA and how does it work?', answer: 'CMA (Certified Management Accountant) in India is conducted by ICMAI (Institute of Cost Accountants of India) — formerly known as ICWAI. There are three levels: CMA Foundation → CMA Intermediate → CMA Final. After passing all three levels and completing 3 years of practical experience, you become a Cost and Management Accountant. CMAs work in cost accounting, financial management, management accounting, and corporate finance roles — distinct from Chartered Accountants who focus more on audit and taxation. The CMA qualification is globally recognised (USA\'s IMA also awards CMA) and is valued in manufacturing, banking, and consulting sectors.' },
    { question: 'What is the CMA exam pattern?', answer: 'The CMA Intermediate runs two groups of four papers under the ICMAI Syllabus 2022 framework. Group I: Paper 5 Business Laws and Ethics (BLE), Paper 6 Financial Accounting (FA), Paper 7 Direct and Indirect Taxation (DITX) — direct and indirect tax sit in one combined paper, not two separate ones — and Paper 8 Cost Accounting (CA). Group II: Paper 9 Operations Management and Strategic Management (OMSM), Paper 10 Corporate Accounting and Auditing (CAA), Paper 11 Financial Management and Business Data Analytics (FMDA), and Paper 12 Management Accounting (MA). Each paper carries 100 marks split 70 descriptive and 30 objective, and the ICMAI examination guidelines budget roughly 160 of the 180 minutes for answering. CMA Foundation is a separate four-paper objective course. CMA Final has 4 descriptive papers. Intermediate and Final exams run twice a year, in the June and December terms. To pass you need 40% in each paper and 50% aggregate per group. Negative marking is the one figure not to take on trust here: recent term notifications are widely reported to carry none on the objective section, so confirm it against the notification for the term you actually sit rather than assuming a penalty. Source: icmai.in' },
    { question: 'How does CMA compare to CA and which should I choose?', answer: 'CMA and CA (Chartered Accountant) both lead to finance/accounting careers but differ in focus: CA emphasises auditing, taxation, and compliance; CMA emphasises cost management, financial strategy, and corporate finance. CMA is generally considered slightly easier to qualify than CA (pass rates are higher), and CMAs are in strong demand in manufacturing, FMCG, and consulting firms for cost control and financial analysis roles. If you want to work in audit/taxation, choose CA; if you want corporate finance/cost management, CMA is the better fit. Many professionals hold both qualifications.' },
  ],
  'comedk': [
    { question: 'What is COMED-K and who is it for?', answer: 'COMED-K (Consortium of Medical, Engineering and Dental Colleges of Karnataka) is the entrance exam for admission to undergraduate professional programmes in private colleges across Karnataka. It is specifically for students who have completed their Class 12 (2nd PUC) from any recognised board in India — unlike KCET which is primarily for Karnataka domicile students, COMED-K is open to students from all Indian states. COMED-K covers B.Tech (Engineering), B.Arch, B.Pharm, and other professional courses in approximately 150+ private unaided colleges in Karnataka. It is the largest private engineering admission exam in Karnataka and is conducted annually by the Consortium.' },
    { question: 'What is the COMED-K exam pattern?', answer: 'COMED-K consists of 180 multiple-choice questions to be answered in 3 hours. For B.Tech admission: Physics (60 questions), Chemistry (60 questions), and Mathematics (60 questions). Each correct answer carries 1 mark; there is no negative marking. The test is run in Computer Based Test (CBT) mode at designated centres across Karnataka and other cities. The difficulty level is moderate — roughly equivalent to the Karnataka Board Class 12 standard. COMED-K covers engineering (B.E/B.Tech) admissions only — medical and dental seats in Karnataka come through KCET or NEET, not through a COMED-K paper. Source: comedk.org' },
    { question: 'What rank do I need for COMED-K admission?', answer: 'COMED-K does not release official cutoffs but publishes rank ranges. No single rank number predicts an outcome, because the closing rank for a seat moves with the branch, the college, the applicant pool and the reservation category every cycle — and COMED-K itself does not publish cutoffs. What it does publish is a common rank list, which is then used in the single-window centralised counselling run by the Karnataka Professional Colleges Foundation. Source: comedk.org The COMED-K management quota is separate from the government merit quota and has higher fees. For NRI candidates, separate seats are available with higher fees. Key advantage over KCET: COMED-K is open to students from all states, making it the best option for non-Karnataka students seeking engineering admission in Karnataka.' },
  ],
  'ca-found': [
    { question: "How is the CA Foundation syllabus distributed across the four papers, and which subjects carry the most scoring weight?", answer: "CA Foundation has four papers of 100 marks each, totalling 400 marks: Paper 1 — Accounting, Paper 2 — Business Laws, Paper 3 — Quantitative Aptitude (Business Mathematics, Logical Reasoning and Statistics), and Paper 4 — Business Economics. Each paper is assessed independently — there is no combined-paper arrangement. Papers 1 and 2 are descriptive while Papers 3 and 4 are objective, so split your prep budget roughly evenly between the written-answer papers and the MCQ papers. Source: icai.org" },
    { question: "What is the exact pass-mark rule and negative-marking structure a CA Foundation candidate must clear in one sitting?", answer: "Candidates must score a minimum of 40% in each of the four papers and an aggregate of 50% (200 out of 400) at one sitting; failing even one paper below 40% means the entire sitting is treated as not cleared. Papers 3 and 4 are objective MCQ papers that carry negative marking of 0.25 mark per wrong answer, while the descriptive Papers 1 and 2 have no deduction for wrong attempts. Plan revision cycles assuming you need 40 marks per paper as the floor, and attempt Papers 3 and 4 accuracy-first because of the penalty. Source: icai.org" },
    { question: "When are the CA Foundation registration and exam dates, and what is the late-fee penalty for missed deadlines?", answer: "ICAI conducts CA Foundation three times a year — in the January, May/June and September windows — and registration for each attempt must be completed by the cut-off notified on the ICAI examination portal, typically about three months before the exam. Aspirants who miss the primary form deadline pay a late fee of ₹600 (domestic centres) in addition to the base exam fee of ₹1,500 for Indian centres, and $325 for overseas Kathmandu/Colombo/Bangkok/Dubai/Abu Dhabi centres. Track announcements under the Exam-Related Announcements category. Source: icaiexam.icai.org" },
    { question: "Which CA Foundation January 2026 candidates are eligible for the Exemption and Combination Scheme, and how does it affect their syllabus workload?", answer: "Candidates who have already qualified or appeared for CS Executive / CMA Intermediate can claim paper-wise exemptions under the Combination Scheme notified by ICAI, allowing them to appear only in remaining Foundation papers. The Exemption Scheme is also available to graduates and post-graduates from recognised universities with the required marks, and registered students of the erstwhile CPT can transition into Foundation. Always verify eligibility clause 40A/40B of the Chartered Accountants Regulations, 1988, on the ICAI site before submitting your form. Source: icai.org" },
    { question: "What exam-day logistics should a CA Foundation aspirant prepare for, including question-paper pattern and mock-test access?", answer: "CA Foundation is a pen-and-paper exam conducted at ICAI-designated centres — it is not taken online from home. Papers 1 and 2 are descriptive papers of 3 hours each, while Papers 3 and 4 are objective MCQ papers of 2 hours each with 0.25 negative marking per wrong answer. Candidates must carry their admit card plus a government photo ID. Begin with the 12-month study plan on the Foundation route page, then attempt at least 20 mock test series on the ICAI learning portal before your attempt. Source: icaiexam.icai.org" }
  ],
  'mat': [
    { question: "How is the MAT 2026 syllabus divided across sections, and how should an aspirant weight their weekly study plan around the five-paper structure?", answer: "The revised AIMA MAT paper carries 150 MCQs split equally into five sections of 30 questions: Language Comprehension, Mathematical Skills, Data Analysis & Sufficiency, Intelligence & Critical Reasoning, and Indian & Global Environment. With 120 minutes total, you effectively get 24 minutes per section, so allocate two full-length mock cycles weekly, dedicating extra revision slots to Mathematical Skills and Data Analysis, which are calculation-heavy. Treat Indian & Global Environment as a daily 20-minute current-affairs habit rather than a cramming subject. Build a 10-week calendar ending two weeks before your chosen February/May/September/December 2026 test date. Source: aima.in" },
    { question: "What is the exact marking scheme and section-wise scoring rule an aspirant must internalise before attempting MAT 2026 mocks?", answer: "MAT carries negative marking: every correct answer fetches one mark and 0.25 mark is deducted for each wrong answer, across 150 questions (30 per section). Because guessing is penalised, your mock strategy should favour accuracy-led attempts in the 120-minute window rather than blind coverage. Sectional scores are reported separately on the scorecard, and very low sectional scores can hurt shortlisting at the 600+ AICTE-approved B-schools accepting MAT (note: IIMs do not accept MAT — they admit through CAT), so balance attempts across all five sections. Source: aima.in" },
    { question: "What are the MAT 2026 registration fee slabs, and which mode combination gives the best value for a first-attempt candidate?", answer: "AIMA charges Rs. 2,300 for a single test mode (CBT, PBT, or IBT), with a combined slab of Rs. 4,000 (Rs. 1,700 extra) for taking two modes in the same session — verify the live slab on aima.in before paying, as AIMA revises fees between sessions. For a first-attempt aspirant, a single well-prepared CBT attempt is usually enough; add a second mode only if you want an in-session retake option. The fee is non-refundable and must be paid online during the AIMA registration window. Source: aima.in" },
    { question: "What is the MAT 2026 eligibility criterion, and can final-year graduation students apply provisionally for the upcoming session?", answer: "AIMA requires a bachelor's degree (10+2+3 pattern) from a recognised Indian university, or an equivalent qualification recognised by the Association of Indian Universities, with no minimum percentage bar. Final-year students awaiting results are eligible to apply provisionally for MAT 2026, but admission confirmation at a participating MBA college is contingent on producing degree proof within the institute's deadline. There is no upper age limit. Keep scanned degree-provisional certificate, Aadhaar, and a recent passport-size photograph ready before filling the AIMA form to avoid last-minute rejection. Source: aima.in" },
    { question: "How many times is MAT 2026 conducted in a calendar year, and which session should a working professional target to balance prep time and score validity?", answer: "AIMA conducts MAT four times a year — typically February, May, September, and December — with each session's score remaining valid for one academic admission cycle. Working professionals juggling full-time jobs should target the May 2026 session, because it follows a five-month post-February window for serious prep, aligns with the largest MBA admission intake, and keeps the September retake as a backup if the first score is below the 500+ composite benchmark preferred by tier-1 accepting institutes. Choose CBT plus IBT mode for scheduling flexibility. Source: aima.in" }
  ],
  'nmat': [
    { question: 'What is the Philippines NMAT and who conducts it for 2026 admissions?', answer: 'The National Medical Admission Test (NMAT) is the Philippines standardised exam required for entry to medical schools. It is administered by the Center for Educational Measurement (CEM) for the Association of Philippine Medical Colleges (APMC). It is not the GMAC NMAT used by Indian B-schools. Candidates usually sit it in the final year of a bachelor\'s degree or after graduation. Confirm the current testing calendar, fees, and registration steps only on the CEM notice. Source: cem-inc.org.ph' },
    { question: 'How is the Philippines NMAT paper structured?', answer: 'Part I measures mental abilities: verbal work (analogies and reading), inductive reasoning, quantitative problem solving, and perceptual acuity. Part II covers undergraduate sciences: Physics, Chemistry, Biology, and Social Sciences. Each subtest is a large item set (typically 200–250 items per subtest in CEM descriptions). The exam is computer-based at designated Philippine centres. Scores are reported as percentiles, not a raw MBA-style 360 scale. Source: cem-inc.org.ph' },
    { question: 'Who can take NMAT Philippines, and how long does a score last?', answer: 'You need a bachelor\'s degree (any field) plus the usual pre-medical science prerequisites — Biology, Physics, General Chemistry, Organic Chemistry, and Biochemistry. Many schools post a minimum NMAT percentile around 40–50; competitive campuses such as UP Manila, Ateneo, and De La Salle commonly look for 80–90+. A score is typically valid for two years. Always re-check the school\'s latest prospectus; StudyRoadmap does not set cut-offs. Source: cem-inc.org.ph' },
    { question: 'How should I plan NMAT Philippines preparation for 2026?', answer: 'Build two tracks. Track A is Part I speed and accuracy — analogies, reading, quantitative, and inductive sets under timed conditions. Track B is Part II content review of undergraduate Physics, Chemistry, Biology, and Social Sciences, then mixed-subject blocks that match CEM\'s computer-based format. Keep an error log by subtest, not by random topic lists. Do not treat unofficial Facebook cut-offs as the live APMC or school rule. Source: cem-inc.org.ph' },
    { question: 'Where do I verify 2026 NMAT Philippines dates and fees?', answer: 'For the 2026 NMAT Philippines cycle, CEM controls registration, test windows and fees, so verify those details only in its current official bulletin and portal. Open the CEM resource linked from the StudyRoadmap exam hub, locate the notice for your intended centre, and check the registration deadline, payment deadline and applicable charges before paying. If a coaching webpage gives different dates or amounts, treat the CEM notice as controlling. Download and retain the bulletin, use the same login to complete each application step, and confirm the email acknowledgement. Before submission, compare the percentile required by your target medical school with the score information stated in that school’s own admissions document. Source: cem-inc.org.ph' },
  ],
  'ipmat': [
    { question: 'What is IPMAT and which IIM offers it?', answer: 'IPMAT (Integrated Programme in Management Aptitude Test) is conducted by IIM Indore for admission to its 5-year Integrated Programme in Management (IPM). This is a unique programme that combines an undergraduate degree (BBA) with an MBA — students spend the first 3 years on the BBA portion at IIM Indore\'s campus, followed by 2 years of MBA. After completing the 5-year programme, graduates receive an MBA degree from IIM Indore. It is one of the most competitive undergraduate management programmes in India — only around 150 seats are available, and over 50,000 students apply each year. After IPMAT Indore, IIM Ranchi also started an IPM programme.' },
    { question: 'What is the IPMAT exam pattern?', answer: 'IPMAT Indore consists of two sections: Quantitative Ability (QA) and Verbal Ability (VA). Both sections have both MCQ and Short Answer (SA) question types. The QA section has 30 MCQs + 10 SA; VA has 30 MCQs + 10 SA. Each MCQ carries 4 marks with -1 for wrong answers; each SA carries 4 marks with no negative marking. Total duration is 2 hours 30 minutes. The exam is conducted online (CBT) at designated centres. There is no General Awareness section — a key difference from IPMAT Ranchi.' },
    { question: 'What score do I need for IIM Indore IPM?', answer: 'A normalised score of 320+ out of 400 is generally competitive for IIM Indore IPM. The sectional cutoffs are typically around 70-80 marks in QA and 70-80 marks in VA. Since only the top 250-300 candidates are called for WAT-PI (Written Ability Test and Personal Interview), a high score in both sections is important. After WAT-PI, the final admission offer is based on: IPMAT score (40%), WAT-PI (30%), Class 10 and 12 marks (15% each).Candidates with strong academic backgrounds and communication skills have an advantage at the WAT-PI stage.' },
  ],
  'gat': [
    { question: "What is GAT Pakistan and which body conducts it?", answer: "The Graduate Assessment Test (GAT) is Pakistan's standardized postgraduate admission test, conducted by the National Testing Service (NTS) for admission to MS and MPhil programmes at universities recognised by the Higher Education Commission (HEC). It is a general aptitude paper rather than a subject exam: it measures the analytical reasoning, quantitative reasoning and English language skills that postgraduate coursework assumes you already have. Because one national score is used across institutions, GAT acts as a unified screening step in place of the separate university-level entrance tests that departments used to run individually. Source: nts.org.pk" },
    { question: "What is the GAT General paper pattern and how long do you get?", answer: "GAT General is 100 multiple-choice questions to be completed in 120 minutes (2 hours), which works out at roughly 72 seconds per question - so time management matters as much as accuracy. The paper is organised into sections covering Verbal Reasoning, Quantitative Reasoning and Analytical Reasoning, with the exact weightage of each section set by the paper category (GAT-A, GAT-B, GAT-C, GAT-D) as notified by NTS for the sitting. GAT is conducted in paper-based format at designated centres across Pakistan. Because you cannot bank unused time from one section against another, settle the questions you can answer quickly first, mark the rest, and return to them with whatever is left on the clock. Source: nts.org.pk" },
    { question: "Who is eligible to appear for GAT, and is there a single passing score?", answer: "You need a recognised Bachelor's degree - a minimum of sixteen years of formal education - from an institution recognised by the Higher Education Commission of Pakistan. What catches first-time candidates out is that NTS does not impose a single centralised cut-off: individual universities and scholarship programmes set their own admission thresholds in their own bulletins, so a score that qualifies you for one programme may not qualify you for another. Treat your target institution's published requirement as the number you are actually working towards, and check it before you register rather than after your result card arrives. Source: hec.gov.pk" },
    { question: "How long is a GAT score valid, and can one sitting cover more than one admission cycle?", answer: "A GAT result remains valid for two years from the date of the test for admission purposes, so a single sitting can support applications across more than one admission cycle. That makes your test date a scheduling decision rather than a once-a-year deadline: sit it early enough in your final year of study to have a usable card in hand, and if you do reappear later, check which attempt the university's bulletin actually asks for before submitting the older score card. Source: nts.org.pk" },
    { question: "How should I prepare for GAT given that it is an aptitude test rather than a syllabus test?", answer: "There is no syllabus to memorise, so revision should target three things: speed on the quantitative and verbal sections, structured practice on analytical reasoning items, and accuracy at the 72-seconds-per-question pace. Start with a full-length paper under exam conditions to establish a baseline, then attack the section where you lose the most time rather than the one where you know the least. Because the paper categories weight the sections differently, use a dated study roadmap to front-load your weakest section into the weeks you have the most time available, and re-test under timed conditions rather than improving on untimed practice. Source: nts.org.pk" },
  ],
  'mdcat': [
    { question: "What is the MDCAT 2026 registration timeline and how do I apply?", answer: "PMC typically opens the MDCAT 2026 registration window in May–June, with applications submitted exclusively through pmc.gov.pk. The registration period usually lasts 3–4 weeks. Candidates must complete the online form, upload their SSC and HSSC marksheets, a recent photograph, and CNIC or B-Form. The application fee for 2026 is Rs. 6,000 (verify the exact amount on the official notice). Applications submitted after the deadline or with missing documents are automatically rejected — no extensions are granted. Keep a printout of the confirmation receipt and your roll number slip, which you will need on exam day. Source: pmc.gov.pk" },
    { question: "Who is eligible to appear for MDCAT 2026?", answer: "According to PMC, candidates must have passed HSSC (Pre-Medical group) or equivalent with a minimum 60% aggregate to be eligible for MDCAT 2026. Those appearing in their HSSC-II annual examination may register provisionally but must produce their final result before counseling. Pakistani nationals holding foreign qualifications must obtain an Equivalence Certificate from IBCC before applying. Candidates already enrolled in an MBBS/BDS program in Pakistan are not permitted to reappear. Age relaxations do not apply for MDCAT — eligibility depends solely on academic credentials. Source: pmc.gov.pk" },
    { question: "What is the MDCAT 2026 exam pattern, total marks, and duration?", answer: "MDCAT is a paper-based test of 180 multiple-choice questions sat in 3 hours. The PM&DC uniform curriculum sets the section split: Biology 81 questions (45%), Chemistry 45 (25%), Physics 36 (20%), English 9 (5%) and Logical Reasoning 9 (5%), totalling 180. Minimum pass marks are 55% for medical college admission and 50% for dental, and there is no negative marking, so unanswered questions cost you nothing beyond the mark — attempt the whole paper. For MDCAT-2026 the PM&DC rescheduled the test to 20 September 2026 and confirmed the 2025 curriculum applies. Source: pmdc.pk" },
    { question: "How does ETEA manage the MDCAT 2026 for Khyber Pakhtunkhwa candidates?", answer: "ETEA (Engineering, Technology, and Emerging Sciences Application Organization) conducts MDCAT 2026 in Khyber Pakhtunkhwa under PMC's authorization. KP-domiciled candidates must register through etea.edu.pk rather than the general PMC portal. ETEA releases the provincial exam schedule, fee structure, and center list separately — these may differ from other provinces. KP candidates applying through ETEA are assessed under the provincial merit quota during medical college admissions. It is mandatory to upload a valid KP Domicile Certificate during ETEA registration. Discrepancies between ETEA and PMC notices should be resolved by contacting ETEA directly. Source: etea.edu.pk" },
    { question: "How long are MDCAT 2026 scores valid for admission, and how is the aggregate calculated?", answer: "MDCAT 2026 scores are valid for one admission cycle only — if you do not secure a seat in the 2026 cycle, you must reappear in the next MDCAT. PMC calculates the final aggregate for merit ranking as: 50% MDCAT score + 40% HSSC marks + 10% SSC marks. A minimum 50% in MDCAT is mandatory to be considered for any public or private medical college. Private medical colleges may set their own merit thresholds above the PMC minimum. Keep your original MDCAT scorecard — it is required during the centralized counseling process conducted by PMC. Source: pmc.gov.pk" }
  ],
  'fpsc-cce': [
    { question: 'What is FPSC-CSS and how does it work?', answer: 'FPSC-CSS, the Federal Public Service Commission Central Superior Services examination, is the recruitment route for Group A and Group B federal posts, including the Pakistan Administrative Service, the Police Service of Pakistan, the Commerce and Trade Group, the Income Tax Group and secretariat services. It runs in two stages: a written examination, then a psychological test and interview. Successful candidates are typically appointed at Assistant Commissioner or Deputy Secretary level and can rise to Secretary. There is no limit on the number of attempts. Source: fpsc.gov.pk' },
    { question: 'What is the FPSC-CSS exam pattern?', answer: 'The written stage is 12 papers — six compulsory and six optional — each worth 100 marks and each of 3 hours, for a total of 1200 written marks. The compulsory block covers English (Essay, Précis and Composition), Urdu (Precise Writing and Translation), Islamic Studies or Pakistan Studies, Current Affairs, General Science and Computer Proficiency, and Pakistan Affairs and Islamic History. You then choose your six optional papers from the FPSC\'s list of subject groups, which spans History, Geography, Political Science, Economics, Sociology, Physics, Chemistry, Mathematics and the other advertised groups. That optional choice is what makes the syllabus enormous and also what lets you exploit a single strong subject, so decide your six groups from the live notice rather than from a previous year\'s list. The written stage is followed by a psychological test and an interview. Source: fpsc.gov.pk' },
    { question: 'How many optional papers can I choose in FPSC-CSS, and from which groups?', answer: 'Six optional papers, not two. Each is 100 marks, so the optional block carries 600 of the 1200 written marks — exactly the weight of the entire compulsory block. The papers come from a list of 27 subject groups maintained by FPSC, including Political Science, International Relations, Economics, Commerce, Sociology, History, Geography, Mathematics, Physics, Chemistry, Botany and Zoology among others. Because each optional paper is long and heavily weighted, four genuinely strong groups will usually beat six average ones. Confirm the exact group list for your cycle on the official CSS exam notice before locking your study plan, because the advertised groups change from year to year. Source: fpsc.gov.pk' },
    { question: 'What is the FPSC-CSS age limit and eligibility?', answer: 'You need to be a Pakistani national with a bachelor\'s degree at second division or above from a university recognised by the Higher Education Commission, and the standard age band is 21 to 30. Which ceiling applies to you depends on your category. Serving Grade 16 and 17 civil servants may sit up to 35 years, and the notice carries separate provisions for candidates from tribal areas and other notified groups — read your row rather than assuming a blanket extension. Women and applicants from Azad Jammu and Kashmir or Gilgit-Baltistan sit on identical terms. Attempts are unlimited, and character plus a clean criminal record are both assessed. Confirm your category in the current notice before you apply. Source: fpsc.gov.pk' },
    { question: 'What score do I need to pass FPSC-CSS?', answer: 'FPSC publishes the qualifying marks for each CSS cycle in its own exam notice, and that notice is the only figure worth planning against — qualifying marks, the number of posts advertised and the recommended-officer merit list are all decided per cycle, and none is fixed across years. We deliberately quote no numeric cutoff here. The widely circulated "50% in each paper and 40% in the aggregate" rule, and the "550 to 600 out of 1200" recommended-officer range, are not published by FPSC as a standing rule, and planning against them would mean aiming at a number that does not exist. Read the qualifying marks in the current notice on fpsc.gov.pk, then aim well above them, because the 1200 written marks are only one input to the final list — the psychological test and the Viva Voce feed selection as well, and a strong written performance does not survive a weak interview. Source: fpsc.gov.pk' },
  ],
  'du-ad': [
    { question: 'What is DU Admission Test (Bangladesh) and how does it work?', answer: 'DU Admission (Bangladesh) refers to the University of Dhaka\'s undergraduate admission test — the most competitive university entrance exam in Bangladesh. Dhaka University admits undergraduates through its own admission test, which is taken after the H.S.C. (Class 12) exam. The test is divided into four units: Unit A (Science background), Unit B (Commerce background), Unit C (Humanities background), and Unit D (Institute of Fine Arts). Each unit has separate eligibility based on H.S.C. subject combination. The DU admission test is highly competitive, and the cut-offs move every year, so treat any rank figure quoted in a coaching hand-out or an older answer key as a historical reference rather than a target.' },
    { question: 'What is the DU Admission test pattern?', answer: 'The DU admission test consists of written examinations for most units. Unit A (Science): 100 marks written test covering Physics, Chemistry, Mathematics/Biology (based on H.S.C. background), plus a separate English test. Unit B (Commerce): written test on Accounting, Business Organisation, Economics and English. Unit C (Humanities): written test on multiple subjects from Humanities group. Unit D (Fine Arts): practical exam and viva. Each unit test is typically 100 marks. The questions are a mix of multiple-choice (MCQ) and written/descriptive answers. DU does not publish one flat merit percentage to memorise: the final merit score is built from the admission-test result together with your combined S.S.C./H.S.C. GPA and marks for extra-curricular activities, and the exact weighting for your unit and quota is set in the admission circular published for each cycle. Check the current circular on admission.eis.du.ac.bd before planning around any number.' },
    { question: 'How does DU admission ranking and merit calculation work?', answer: 'DU admission ranks candidates on a combined merit score rather than on the admission-test mark alone, and that score already folds in the combined S.S.C. and H.S.C. GPA point and extra-curricular marks described above, with the weighting for your unit and quota set in the admission circular published for each cycle. The total weighted score determines the merit ranking. For oversubscribed subjects the merit position you need can shift by a large margin between cycles, so set your target from the previous cycle\'s published merit list for that specific department instead of from a single remembered cut-off number. After the written test, selected candidates go through a viva voce. The final selection is based on combined performance in written test and viva. Seat numbers are revised cycle to cycle and published unit-wise by the Central Admission Office, so read the figure for your own unit rather than assuming one university-wide total.' },
  ],
  'ecat': [
    { question: 'What is the eligibility for ECAT?', answer: 'For the 2026 ECAT intake, eligibility centres on F.Sc. Pre-Engineering or an equivalent qualification containing Physics, Chemistry and Mathematics. The stated minimum is 60% marks in HSSC or the equivalent, and candidates appearing in their final HSSC examination may also sit ECAT. The test is mandatory for admission to all engineering universities in Punjab, Pakistan under the stated system. Before submitting an application, verify that your mathematics and science subjects match the UET instruction sheet and upload a clear equivalence or result document if you studied another board or qualification. Check the current eligibility section on the official ECAT site, retain proof of the 60% requirement, and compare any programme-specific conditions set by the receiving universities. Source: ecat.uet.edu.pk' },
    { question: 'What is the ECAT exam pattern?', answer: 'For 2026 planning, the stated ECAT pattern is a 100-question MCQ test within 100 minutes. Chemistry contains 30 questions, Physics 30, Mathematics 30, and English or General Knowledge 10. Each correct response earns 4 marks, and the test has no negative marking. It is delivered as a computer-based test at designated centres across Pakistan. Build a revision plan that mirrors these section totals, but first check the current UET test booklet for the exact syllabus, language, instructions and centre allotment. During practice, answer only the listed sections, track the four-mark credit for every question, and avoid assuming that an unmarked incorrect response changes the score. Check the current list of documents that must be carried on test day. Source: ecat.uet.edu.pk' },
    { question: 'How is the ECAT merit calculated?', answer: 'Merit is calculated by combining the ECAT score with the HSSC/F.Sc. aggregate, and the weightage given to each part is set by the admitting university rather than fixed across Pakistan. UET Lahore publishes its merit score calculation formula on the admissions portal and states that admission policies may change between cycles, so check the formula published by the university you are applying to before calculating an expected merit. The aggregate percentage is calculated on the basis of marks obtained in Physics, Chemistry, and Mathematics. Source: admission.uet.edu.pk' },
  ],
  'ecat-eng': [
    { question: "What subjects and question distribution does the ECAT-ENG 2026 syllabus cover, and how are the 400 marks divided?", answer: "The ECAT-ENG 2026 test comprises 100 MCQs across four compulsory sections: Mathematics (30 MCQs), Physics (30 MCQs), Chemistry (30 MCQs), and English (10 MCQs). Each correct answer carries 4 marks, taking the maximum to 400. There is no negative marking in ECAT, and no passing threshold for any programme, so nothing is deducted for a wrong or unattempted response. Aspirants should weight their preparation accordingly — roughly 48% of marks come from Maths+Physics combined, so daily problem-solving in calculus, mechanics, and electrostatics yields the highest return. Source: ecat.uet.edu.pk" },
    { question: "When is ECAT-ENG 2026 likely to be held, and what is the registration fee structure for Punjab engineering aspirants?", answer: "UET Lahore typically conducts ECAT in the last week of June or first week of July; the 2026 test is tentatively scheduled for July 2026, with online registration opening on the UET admission portal around April 2026. The application fee is Rs. 3,500 for a single test attempt, payable via designated bank challan or 1Bill/JS Bank channels. Candidates must upload Matric, Inter, and domicile documents before the deadline. Check the portal weekly from April onward to avoid late-fee penalties. Source: admission.uet.edu.pk" },
    { question: "What is the minimum eligibility for appearing in ECAT-ENG 2026, and how are FSc Pre-Engineering and Pre-Medical candidates treated?", answer: "An applicant must have passed the Intermediate (FSc/ICS) or an equivalent examination (e.g., DAEBTE) with at least 60% unadjusted marks in aggregate, securing pass marks in Mathematics, Physics, Chemistry, and English at the FSc level. FSc Pre-Medical candidates are eligible for Biomedical Engineering seats only and must appear in ECAT to be ranked. Domicile of Punjab is mandatory. Those awaiting 2026 results may apply provisionally but must produce the certificate at the time of interview. Source: ecat.uet.edu.pk" },
    { question: "Which official textbooks and topic list form the basis of the ECAT-ENG 2026 Mathematics and Physics sections?", answer: "The Mathematics section is drawn from Punjab Textbook Board FSc Part-I & II books — covering Functions, Limits, Differentiation, Integration, Vectors, Matrices, Determinants, and Analytical Geometry. Physics is based on Punjab Textbook Board books: Mechanics, Waves and Optics, Heat and Thermodynamics, Electricity and Magnetism, and Modern Physics. Chemistry follows the PTB syllabus for Inorganic, Organic, and Physical branches. English tests grammar, vocabulary, and comprehension at intermediate level. Practice from HEC-recommended reference books like Kangay & Khan for numericals. Source: uet.edu.pk" },
    { question: "How does the merit formula for ECAT-ENG 2026 combine test score with FSc marks, and what is the expected closing aggregate for top public engineering universities?", answer: "The merit for admission to UET Lahore and other public sector engineering universities combines the ECAT test score with HSSC/equivalent marks, but the exact weightage is set by each university and published in the admission rules of that institution rather than as one national constant. UET Lahore states that its merit score calculation formula is available on the admissions portal and that admission policies may change between cycles, so treat any circulating closing-aggregate figures for Computer Science, Electrical or Mechanical programmes as unofficial estimates rather than published cut-offs, and compute an expected aggregate from the formula published for the current admission cycle. Source: admission.uet.edu.pk" }
  ],
  'nat-i': [
    { question: 'What is NAT-I and how does it work?', answer: 'For a 2026 application, NAT-I, or National Aptitude Test-I, is an NTS multiple-choice aptitude examination used for undergraduate admissions at participating Pakistani universities. It assesses Verbal Reasoning, Analytical Reasoning, Quantitative Reasoning and Subject Knowledge. Unlike a university-specific ECAT process, NAT-I can form part of the admission criteria at multiple universities, but each institution may combine its score with its own subject, aggregate or interview requirements. Download the NTS test guide and current university prospectus, list the papers mapped to your target programme, and practise the reasoning and subject sections named in those documents. Do not treat NAT-I acceptance as an admission offer; check eligibility and programme-specific conditions before you register or pay. Source: nts.org.pk' },
    { question: 'What is the NAT-I exam pattern?', answer: 'NAT-I is a 100-question objective paper with a 2-hour (120-minute) duration, scored on a 100-point scale. The four sections split 20 / 20 / 20 / 40: Verbal Reasoning carries 20 questions, Analytical Reasoning 20, Quantitative Reasoning 20, and Subject Knowledge 40. The Subject section is drawn from the F.Sc. or intermediate stream you are sitting, so its shape changes between science and non-science candidates. Those section totals are the revision budget: three equal reasoning blocks of 20 plus one double-weight subject block of 40. At 100 questions in 120 minutes you are working to roughly 1.2 minutes per question, so a timed full-length paper is the only honest test of that pace. Source: nts.org.pk' },
    { question: 'What is the NAT-I syllabus?', answer: 'NAT-I has no single published topic list beyond its four scored sections, so the syllabus is best read section by section. Verbal Reasoning is vocabulary and language judgement: synonyms, antonyms, sentence completion, one-word substitution, idioms and phrases, spelling, reading comprehension, verbal analogies, odd-one-out on words, jumbled sentences, subject-verb agreement, critical reading, inference and conclusion, and contextual vocabulary. Analytical Reasoning is logical and non-verbal handling: blood relations, direction sense, coding-decoding, number and letter series, classification, seating arrangement, linear and circular puzzles, syllogisms, statement-and-assumption, statement-and-argument, cause and effect, ranking and ordering, Venn diagrams, and cube and dice problems. Quantitative Reasoning is school mathematics: number system, fractions and decimals, percentages, profit and loss, ratio and proportion, time-speed-distance and work, simple and compound interest, algebraic expressions, linear and quadratic equations, lines, angles and triangles, circles and mensuration, data interpretation from charts and tables, probability and permutations, and averages and statistics. Subject Knowledge is the one section you cannot revise generically, because it follows your own stream — for F.Sc. it spans Physics (mechanics, electricity and magnetism), Chemistry (physical and organic), Biology (cell biology and genetics, human physiology) and Mathematics (algebra and calculus, geometry and trigonometry), alongside computer science fundamentals and programming basics. Source: nts.org.pk' },
    { question: 'Who is eligible for NAT-I?', answer: 'The qualification floor is set by the programme you are applying to rather than by NAT-I itself. For undergraduate admission the baseline is HSSC or an equivalent intermediate qualification; for postgraduate admission it is a bachelor\'s degree, which in Pakistan is 16 years of schooling. Beyond that floor, each participating university sets its own subject requirements and may add an interview, a separate subject test or an aggregate calculation on top of the NAT-I score. That is why one NAT-I number can be competitive at one institution and irrelevant at another, and why the figure worth checking is the one published by your target university. Confirm both the eligibility rule and which NAT version is accepted on the NTS bulletin and on the university portal before you register or pay a test fee. Source: nts.org.pk' },
    { question: 'How is NAT-I used in university admissions?', answer: 'NAT-I scores are submitted directly to universities during the application process, and each university sets its own minimum score for each programme. There is no single national NAT-I cutoff that applies across institutions, so treat any fixed number you meet in a coaching advertisement — including the widely quoted "above 70 out of 100" — as unverified until the university you are actually applying to publishes it in its current prospectus or admission notice. Some universities weigh NAT-I alongside your F.Sc. or HSSC marks to build a merit aggregate, and some attach a subject test or interview, so the weight the test actually carries in your merit list is the first figure to check. Rank programmes by the published requirement rather than by the highest-sounding score, and download the NTS test guide alongside the specific university prospectus so you revise against the sections that institution will weigh. Source: nts.org.pk' },
  ],
  'kuccps': [
    { question: 'What is KUCCPS and how does university admission work in Kenya?', answer: 'KUCCPS (Kenya Universities and Colleges Central Placement Service) is the government body responsible for placing students into Kenyan universities and TVET institutions after the KCSE (Kenya Certificate of Secondary Education) exam. Unlike countries where you take a separate entrance exam, Kenyan university admission is based primarily on your KCSE grade — students apply to KUCCPS after receiving their KCSE results, and KUCCPS places them based on their grades, chosen programmes, and available capacity. KUCCPS handles placement for all public universities in Kenya including the University of Nairobi, Kenyatta University, Egerton University, and others.' },
    { question: 'How is the KUCCPS placement score calculated?', answer: 'KUCCPS calculates placement using the Mean Points Score (MPS) from KCSE results. The KCSE is graded on a scale of 12 points (A to D-). The aggregate cluster points are calculated based on the required subjects for your chosen programme — for example, Engineering programmes require the STEM cluster (Mathematics, Physics, Chemistry, and either Geography or Computer Studies). Each programme at each university has a cutoff cluster points requirement. Students with a mean points score above the cutoff for their programme are eligible for placement. The higher your KCSE grade, the more placement options available.' },
    { question: 'What are the alternatives if I don\'t get placed by KUCCPS?', answer: 'If you don\'t get placed by KUCCPS to your preferred university or programme, you have several options: (1) Join a TVET (Technical and Vocational Education and Training) institution — KUCCPS also places students into TVET courses, which can lead to diploma or certificate programmes; (2) Apply directly to private universities — private universities like United States International University Africa (USIU-Africa), Strathmore University, and others have their own application processes and do not use KUCCPS; (3) Wait for the second round of placement when additional slots may open; (4) Consider improving your KCSE score by retaking the exam the following year. Remember that KUCCPS placement is free — avoid intermediaries who charge for placement services.' },
  ],
  'lat': [
    { question: "What is the official eligibility criteria and Supreme Court mandate for the Pakistan LAT 2026 examination?", answer: "The Law Admission Test (LAT) is mandatory under Supreme Court of Pakistan rulings for any candidate seeking admission into a 5-year public or private LLB degree program. Candidates who have passed Higher Secondary School Certificate (HSSC Part-II) with at least 50% marks, or who have appeared in final HSSC examinations and are awaiting results, are eligible to apply on the Education Testing Council portal. There is no upper age limit prescribed by HEC for taking the test, though individual universities may enforce institutional age policies. Always upload verified CNIC or B-Form details during registration. Source: etc.hec.gov.pk" },
    { question: "What is the structural breakdown, paper timing, and section-wise weightage for LAT 2026?", answer: "LAT carries 100 total marks across two distinct components completed in a composite 2-hour duration. The objective component has 75 multiple-choice questions: English vocabulary, grammar, and comprehension (20 MCQs); General Knowledge (20 MCQs); Pakistan Studies (10 MCQs); Islamic Studies or Ethics for non-Muslims (10 MCQs); Urdu vocabulary and grammar (10 MCQs); and Elementary Mathematics (5 MCQs). The subjective component carries 25 marks: an Essay of roughly 200 words in English or Urdu (15 marks), and a Personal Statement of roughly 200 words (10 marks). Plan 75 minutes for MCQs and 45 minutes for writing. Source: etc.hec.gov.pk" },
    { question: "What is the passing cutoff score in LAT 2026 and does incorrect guessing incur negative marking?", answer: "The qualifying benchmark for LAT is strictly 50% (50 marks out of 100). The test carries zero negative marking for incorrect MCQ responses, making it advantageous to attempt all 75 objective questions. Marks scored in both the MCQ section and the descriptive section are aggregated directly. Results remain valid for two calendar years from the date of declaration. While 50 marks clears statutory HEC eligibility, premier institutions like Punjab University Law College or Quaid-i-Azam University often close open merit lists between 72 and 80 aggregate marks. Source: etc.hec.gov.pk" },
    { question: "How much is the LAT 2026 registration fee and what payment steps must candidates complete?", answer: "The test registration fee for LAT 2026 is PKR 1,500, payable online exclusively via 1Link 1Bill using consumer numbers generated on the ETC profile dashboard. Candidates must create an account at etc.hec.gov.pk, fill in educational particulars, select preferred examination cities, and generate the 1Bill fee invoice. Payment can be cleared via mobile banking apps, ATMs, or internet banking using the 1Link biller code. Keep the digital transaction receipt and roll number slip downloaded from the portal for entry into the examination hall alongside your original CNIC. Source: etc.hec.gov.pk" },
    { question: "How should an aspirant structure preparation across the descriptive and MCQ sections of LAT 2026?", answer: "Divide your 6-week preparation into two concurrent tracks. Spend 90 minutes daily reviewing Class 9–12 textbooks for Pakistan Studies, Islamic Studies, and basic grammar concepts, while tracking contemporary national affairs for General Knowledge. For the descriptive track, practice writing one 200-word essay and one personal statement every three days, focusing on clear topic sentences, logical transitions, and grammatical precision. Avoid exceeding the word count window by more than 10%, as examiners penalise unfocused writing. Timed rehearsals using past papers ensure seamless pacing between objective items and descriptive essays. Source: etc.hec.gov.pk" }
  ],
  'neco': [
    { question: "What are the registration deadlines, examination schedules, and fees for NECO SSCE 2026?", answer: "The NECO Senior School Certificate Examination (SSCE Internal) for school-based candidates runs between June and July 2026, with online candidate bio-data uploads concluding in May on neco.gov.ng. The registration fee is approximately ₦24,500 per school candidate, while the External private candidate series (November/December) requires ₦35,000 paid through the NECO e-Verify and registration portal via REMITA. External registration requires mandatory National Identification Number (NIN) verification. Candidates should ensure all subject registrations are finalised before biometric capture to avoid late registration surcharges. Source: neco.gov.ng" },
    { question: "What is the paper structure and grading standard for NECO SSCE 2026 subjects?", answer: "Each core academic subject in NECO consists of three compulsory papers: Paper 1 (Objective testing, 50–60 MCQs in 60–75 minutes), Paper 2 (Essay and structured theory questions, 100 marks in 2 to 2.5 hours), and Paper 3 (Laboratory practical or alternative-to-practical test for science and technical streams). Results are graded on a 9-point scale: A1 (Distinction, 75–100%), B2 (Very Good, 70–74%), B3 (Good, 65–69%), C4–C6 (Credit, 50–64%), D7–E8 (Pass, 40–49%), and F9 (Fail, 0–39%). Continuous Assessment scores submitted by schools contribute 30% to final internal grades. Source: neco.gov.ng" },
    { question: "How many credit passes in NECO 2026 are compulsory for Nigerian tertiary admissions under JAMB?", answer: "Federal and state universities, polytechnics, and colleges of education across Nigeria require a minimum of five credit passes (grades A1 to C6) in relevant subjects, including English Language and General Mathematics, obtained in not more than two sittings. Science disciplines demand credits in Physics, Chemistry, and Biology, while Arts and Social Science faculties require Literature in English, Government, or Economics. Candidates awaiting NECO results can register for JAMB UTME, provided their verified NECO grades are uploaded to their JAMB CAPS profile before admission screening lists close. Source: neco.gov.ng" },
    { question: "Can NECO results be combined with WAEC for university admission clearance, and how does verification work?", answer: "Yes, the Joint Admissions and Matriculation Board and Nigerian tertiary institutions officially permit the combination of two sittings across NECO SSCE and WAEC WASSCE results (e.g. WAEC May/June with NECO June/July). However, certain highly competitive professional programmes, such as Medicine and Surgery at the University of Ibadan or Law at the University of Lagos, may occasionally require all five credits in a single sitting. Candidates must verify their combined statements of results using the NECO e-Verify platform and upload matching pin slips to JAMB CAPS. Source: neco.gov.ng" },
    { question: "What strategic revision schedule should candidates follow to clear five NECO credits in one sitting?", answer: "Effective NECO preparation requires systematic alignment with the published NECO syllabus and mastery of past examination questions from 2020 to 2025. Allocate 3 hours daily across English grammar and comprehension, Mathematics problem-solving, and your three core faculty electives. Focus heavily on Paper 2 theory presentation: write clear, step-by-step mathematical working and concise, well-paragraphed essay responses rather than rushed points. Practice science practical setups weekly if taking Physics, Chemistry, or Biology, because Paper 3 marks directly safeguard borderline scores from falling into D7 or E8. Source: neco.gov.ng" }
  ],
  'nabteb': [
    { question: "What credentials does NABTEB award in 2026 and which institutions recognize them?", answer: "The National Business and Technical Examinations Board conducts examinations leading to the National Technical Certificate (NTC) for engineering/trades, National Business Certificate (NBC) for commercial studies, and Advanced ANTC/ANBC qualifications. Under Federal Ministry of Education circulars, NABTEB NBC and NTC certifications are legally equivalent to WAEC and NECO SSCE. They are recognized by JAMB for direct university, polytechnic, and monotechnic admissions into STEM, business administration, and vocational degree courses, as well as by civil service and private technical employers. Source: nabteb.gov.ng" },
    { question: "What is the examination structure and practical testing component of NABTEB 2026?", answer: "NABTEB modular exams comprise general education subjects alongside specialized technical or trade modules. Candidates sit three distinct components per trade subject: Paper I (Theory and Objective), Paper II (Practical Examination conducted in workshops or laboratories), and Continuous Assessment. Trade practicals carry between 40% and 50% of the overall subject mark, testing hands-on technical execution, safety procedures, and blueprint interpretation in trades such as Electrical Installation, Motor Vehicle Mechanics, Fabrication, and Computer Craft. General subjects follow standard SSCE objective and essay formats. Source: nabteb.gov.ng" },
    { question: "What are the registration guidelines and 2026 exam windows for NABTEB NBC/NTC?", answer: "NABTEB conducts two primary examination series annually: the May/June National Business and Technical Certificate examination for in-school candidates, and the November/December modular examination for private and external candidates. Registration is handled online at registration.nabteb.gov.ng. The standard registration fee for external candidates is approximately ₦25,500, payable via REMITA with mandatory National Identification Number (NIN) linkage. Candidates must register for a minimum of five subjects, including English Language, Mathematics, and one trade practical, ensuring full compliance with national tertiary entry benchmarks. Source: nabteb.gov.ng" },
    { question: "Can NABTEB certificates be used for university admission into non-engineering courses?", answer: "NABTEB NBC certificates are accepted for non-engineering courses such as Accounting, Business Administration, Marketing, Banking & Finance, and Economics, provided candidates possess credit passes in English Language, Mathematics, Economics, and relevant commercial subjects. However, for humanities and classical arts faculties (such as Law or Mass Communication), some conventional universities specifically prescribe WAEC or NECO sittings. Candidates aiming for non-technical fields should check the official JAMB Brochure course requirements before choosing NABTEB as their sole entry credential. Source: nabteb.gov.ng" },
    { question: "How should technical college candidates prepare for the NABTEB practical and theory papers?", answer: "Preparation must balance theoretical recall with hands-on workshop proficiency. Dedicate 60% of preparation time during the 8 weeks preceding the examination to solving past theory papers and memorizing technical terminologies, engineering formulas, and business principles. Reserve remaining time for workshop tool handling, electrical wiring diagrams, or machine setups matching previous practical examination prompts. Review examiner reports published on the board portal to identify recurring candidate pitfalls in technical drawing and practical calculations, ensuring comprehensive mastery across both theory and practical criteria. Source: nabteb.gov.ng" }
  ],
  'ncee': [
    { question: "Who is eligible to sit the NCEE 2026 and which schools does it serve?", answer: "The National Common Entrance Examination (NCEE) is administered by the National Examinations Council (NECO) for final-year Primary 6 pupils seeking admission into JSS 1 (Junior Secondary School) across Nigeria's 110 Federal Government Colleges (Unity Colleges). Candidates must not be younger than 10 years old or older than 13 years old by September of the admission year. Both public and private primary school pupils nationwide are eligible to apply through accredited primary schools or directly by parents on the NECO common entrance portal. Source: neco.gov.ng" },
    { question: "What is the examination layout, timing, and question split for NCEE 2026?", answer: "The NCEE is an objective paper-pencil test split into two main papers administered on a single Saturday morning. Paper 1 consists of Part A (Mathematics and Basic Science & Technology, 65 multiple-choice questions in 75 minutes) and Part B (English Studies and National Values Education, 65 questions in 75 minutes). Paper 2 tests Aptitude: Part A (Quantitative and Vocational Aptitude, 40 questions in 45 minutes) and Part B (Verbal Aptitude, 40 questions in 45 minutes). The entire examination carries a composite maximum score of 200 marks with zero negative marking. Source: neco.gov.ng" },
    { question: "How are cut-off marks determined and admission quotas allocated for Federal Unity Colleges?", answer: "Admission into Federal Unity Colleges uses a three-tier quota system prescribed by the Federal Ministry of Education: National Merit (60% of available vacancies based strictly on top composite scores across the country), Equality of States (30% divided equally among the 36 states and FCT), and Environmental/Host Community Quota (10% reserved for residents of the local government where the college is situated). Because of the state quota, cut-off marks vary significantly by state of origin, ranging from very high scores for competitive southern states to lower statutory thresholds for educationally less developed states. Source: neco.gov.ng" },
    { question: "What is the NCEE 2026 registration fee and step-by-step application workflow?", answer: "The registration fee for NCEE 2026 is ₦4,500 per candidate, payable online via REMITA on the official NECO registration portal (neco.gov.ng). Parents or primary school heads register by creating an account, entering candidate biodata, selecting state of origin and local government, choosing three preferred Federal Unity Colleges in order of priority, and selecting an accessible examination center. After payment verification, the system generates a photo card containing the candidate's registration number and exam venue, which must be stamped by the primary school head and presented on exam day. Source: neco.gov.ng" },
    { question: "What study techniques help young pupils excel in the quantitative and verbal reasoning sections of NCEE?", answer: "Young learners preparing for NCEE should focus on building systematic pattern recognition and timed mental arithmetic. Parents and tutors should guide pupils through daily 30-minute practice drills covering standard quantitative puzzle formats (number series, coding-decoding, analogical matrices) and verbal aptitude drills (synonyms, antonyms, sentence completion). Emphasize careful shading technique on optical mark recognition (OMR) sheets, as stray marks or incomplete ovals invalidate correct answers. Taking at least five full-length timed mock tests under quiet examination conditions prevents test-day fatigue. Source: neco.gov.ng" }
  ],
  'ican': [
    { question: "What are the entry paths, exemptions, and tier stages for the ICAN 2026 syllabus?", answer: "The ICAN examination structure operates across three professional tiers comprising 15 papers: Foundation (5 papers: Business Law, Financial Accounting, Management Information, Business & Finance, and Taxation), Skills (6 papers: Financial Reporting, Audit & Assurance, Performance Management, Public Sector Accounting, Corporate Strategic Management, and Taxation), and Professional (4 papers: Strategic Financial Management, Advanced Taxation, Advanced Audit & Assurance, and Case Study). Holders of recognized university degrees or HNDs in Accounting receive direct exemption from the Foundation level, entering straight into the Skills stage upon payment of assessed exemption fees. Source: icanig.org" },
    { question: "What is the ICAN 2026 exam diet calendar, registration fees, and venue network?", answer: "ICAN conducts two examination diets annually: the May Diet (held in the third week of May) and the November Diet (held in the third week of November) across more than 50 designated examination centres in Nigeria, Cameroon, and the United Kingdom. Registration opens approximately three months before each diet on icanig.org. Fees include an initial student registration fee of ₦10,000, annual student subscription of ₦5,000, and per-paper examination fees ranging from ₦12,500 to ₦22,000 depending on the level, alongside a composite centre charge. All fee payments must be settled via the ICAN web portal before entry closing dates. Source: icanig.org" },
    { question: "What is the passing standard and credit retention rule across ICAN examination papers?", answer: "The pass mark for every ICAN examination paper is strictly 50%. ICAN operates a single-paper credit retention policy: when a candidate passes any subject in a tier, that credit is permanently retained, requiring them to re-sit only the remaining failed subjects in subsequent diets. However, in the final Professional level Case Study paper, candidates must demonstrate comprehensive analytical, ethical, and strategic competence across a multi-scenario business challenge. Passing all 15 papers qualifies a student to complete the Practical Experience Requirement (PER) before formal induction as an Associate Chartered Accountant (ACA). Source: icanig.org" },
    { question: "How does the ICAN ACA qualification compare to international credentials like ACCA in Nigeria?", answer: "While ACCA provides global mobility with emphasis on International Financial Reporting Standards (IFRS) under UK regulatory frameworks, ICAN is the premier statutory accounting body in Nigeria established by Act of Parliament in 1965. In the Nigerian public sector, banking industry, and local taxation audits, ICAN certification is given primary statutory standing. However, ICAN and ACCA maintain mutual recognition agreements and reciprocal exemption arrangements, enabling qualified ACAs to obtain ACCA membership with minimal additional papers. Many corporate finance professionals in Nigeria pursue both credentials for career versatility. Source: icanig.org" },
    { question: "What preparation methodology is required to pass ICAN Skills and Professional papers on first attempt?", answer: "Passing ICAN papers demands rigorous engagement with the official ICAN study packs and past pathfinder question-and-answer booklets available on icanig.org. Devote at least 15 hours weekly per registered paper across a 4-month preparation cycle. Prioritize practical computations alongside statutory references for Nigerian tax laws (CITA, PITA, VAT Act) and public sector accounting standards (IPSAS). For the Case Study paper, practice drafting professional executive summaries and financial ratio appendices under a strict 4-hour mock timer, ensuring every calculation connects directly to justified strategic recommendations. Source: icanig.org" }
  ],
  'ijmb': [
    { question: "What is the IJMB 2026 programme structure and how does it secure university direct entry?", answer: "The Interim Joint Matriculation Board (IJMB) is an advanced-level educational programme moderated by Ahmadu Bello University (ABU), Zaria. It runs as an intensive 9-to-10-month curriculum where candidates study three advanced-level subjects matching their intended university degree. Upon successful completion and release of results in August, candidates purchase the JAMB Direct Entry form, which grants admission directly into the 200-level (second year) of undergraduate degree programmes across federal, state, and private universities in Nigeria, completely bypassing 100-level and UTME examination requirements. Source: abu.edu.ng" },
    { question: "What is the grading point scale and minimum score required for competitive IJMB courses?", answer: "IJMB subjects are graded on an A to F point scale: Grade A (5 points, 70–100%), Grade B (4 points, 60–69%), Grade C (3 points, 50–59%), Grade D (2 points, 40–49%), Grade E (1 point, 35–39%), and Grade F (0 points, 0–34%). Candidates who pass all three registered subjects without an F receive 1 automatic bonus point, making 16 points the maximum possible composite score. For competitive courses like Medicine and Surgery, universities typically require 12 to 15 points; Engineering and Law demand 10 to 13 points; while general sciences and humanities accept 6 to 9 points. Source: abu.edu.ng" },
    { question: "What are the eligibility requirements and registration procedures for the 2026 IJMB session?", answer: "To qualify for IJMB enrollment, applicants must possess a minimum of five O-Level credit passes in WAEC, NECO, or NABTEB in relevant subjects, including English Language and Mathematics, obtained in not more than two sittings. Awaiting results candidates are also accepted provisionally. Registration is conducted through accredited IJMB study centres affiliated with Ahmadu Bello University. Total programme costs, covering application form, tuition, laboratory fees, and national examination registration, typically range between ₦150,000 and ₦250,000 depending on the centre and subject stream. Source: abu.edu.ng" },
    { question: "How does IJMB compare to JUPEB and how long does an IJMB certificate remain valid?", answer: "Both IJMB and JUPEB are government-approved 9-month Advanced Level programmes qualifying holders for 200-level Direct Entry admission. IJMB is moderated by Ahmadu Bello University, Zaria, and has historically broader acceptance and lower tuition fees in northern and central Nigerian universities. JUPEB is moderated by the University of Lagos and is dominant in south-western and south-eastern universities. A critical advantage of the IJMB certificate is its multi-year validity: an IJMB result remains valid for university admission for up to seven years, whereas standard UTME scores expire after a single admission cycle. Source: abu.edu.ng" },
    { question: "What daily study regimen is recommended to secure 12+ points in the IJMB final examination?", answer: "Achieving 12 or more points in IJMB requires treating the accelerated syllabus as full A-Level academic coursework. Attend all daily lectures and laboratory sessions, dedicating at least 4 hours each evening to personal review and problem-solving across your three chosen subjects. Work through past IJMB examination questions spanning the last ten years, noting how marks are distributed across definitions, derivation steps, and graphical interpretations. In science subjects, give equal priority to practical laboratory journals, as practical examination scores provide a decisive cushion for attaining A and B grades. Source: abu.edu.ng" }
  ],
  'hat-ug': [
    { question: "What is the HAT-UG 2026 test purpose, managing authority, and participating institutions?", answer: "The Higher Education Aptitude Test for Undergraduates (HAT-UG) is administered by the Education Testing Council (ETC) of the Higher Education Commission, Pakistan. It is designed to evaluate academic readiness for undergraduate admissions and competitive scholarship schemes across HEC-recognized public and private universities. Major programmes utilizing HAT-UG include HEC indigenous scholarships, overseas undergraduate funding schemes, and admissions at federally chartered degree-awarding institutes. The test provides an objective, standardized metric that universities use alongside Intermediate board percentages during merit calculation. Source: etc.hec.gov.pk" },
    { question: "What are the test categories, paper duration, and question distribution for HAT-UG 2026?", answer: "HAT-UG is divided into specialized subject categories based on the candidate's intermediate academic background: HAT-UG-E (Pre-Engineering), HAT-UG-M (Pre-Medical), HAT-UG-A (Arts and Humanities), HAT-UG-CS (Computer Science), HAT-UG-GS (General Science), and HAT-UG-COM (Commerce). The test consists of 100 multiple-choice questions administered over a 120-minute duration. The curriculum splits across English Verbal Reasoning (30 questions covering vocabulary, sentence completion, and critical reading), Analytical Reasoning (30 questions covering logical deduction and scenario puzzles), and Quantitative Reasoning or Subject Knowledge (40 questions). Source: etc.hec.gov.pk" },
    { question: "What is the passing criterion in HAT-UG 2026 and how long does the scorecard remain valid?", answer: "The minimum qualifying benchmark for HAT-UG is 50 marks out of 100. There is no negative marking for incorrect answers on the optical mark reader (OMR) response sheet. The official result scorecard is issued digitally on the candidate's ETC portal profile within two to three weeks of test administration. A verified HAT-UG score remains valid for exactly two calendar years from the date of result announcement, allowing students to use a single high-scoring test result across multiple university admission cycles and scholarship application intakes. Source: etc.hec.gov.pk" },
    { question: "What is the fee schedule and online application procedure for HAT-UG 2026?", answer: "The test registration fee for HAT-UG 2026 is PKR 2,000, payable via 1Link 1Bill invoice through mobile banking apps, internet banking, or ATMs. Applicants must register at etc.hec.gov.pk, complete their candidate profile with accurate CNIC or B-Form data, upload intermediate academic transcripts, select their specific HAT-UG category matching their intermediate group, and choose their preferred test centre. Once payment is confirmed, the ETC system issues a downloadable roll number slip detailing the examination venue and session reporting time, which must be brought to the venue. Source: etc.hec.gov.pk" },
    { question: "How should candidates allocate preparation time between verbal, analytical, and quantitative sections?", answer: "A balanced 6-week preparation strategy should allocate 40% of study time to Analytical Reasoning, 30% to Quantitative Reasoning, and 30% to Verbal English. Analytical reasoning requires practicing logic grids, grouping problems, and conditional sequencing questions from standard aptitude preparation manuals. For Quantitative Reasoning, thoroughly review Class 9 and 10 arithmetic, algebra, geometry, and basic percentage calculations. Enhance Verbal Reasoning by practicing passage comprehension under a 1-minute-per-question timer. Taking three full-length timed diagnostic tests helps develop the cognitive endurance required for 100 questions in 120 minutes. Source: etc.hec.gov.pk" }
  ],
  'jamb': [
    { question: "When does the JAMB 2026 UTME registration open, and what is the exam schedule?", answer: "Registration for the 2026 UTME opens in February, with the Computer-Based Test (CBT) scheduled between March and April each year. Candidates must pay a non-refundable fee of Three Thousand Five Hundred Naira (₦3,500) through the JAMB portal before proceeding with biometric capturing at designated centres. The UTME is scored on a maximum scale of 400 points, and candidates who miss their scheduled date may request a re-print of their examination notification slip, though late registration is rarely permitted. Monitor jamb.gov.ng for the exact official start date announced annually. Source: jamb.gov.ng" },
    { question: "What are the subject combinations required for the JAMB 2026 UTME?", answer: "The UTME consists of 180 questions covering four subjects selected based on your intended university course. English Language is compulsory for all candidates, while the remaining three subjects depend on your field of study—for example, Physics and Chemistry are required for engineering programmes, and Biology is essential for medical courses. JAMB provides an official syllabus on jamb.gov.ng for each subject, detailing specific topics and recommended texts. Candidates must choose their subject combination during registration, as changes after submission may not be allowed. Always verify your combination against your target university's requirements before registering. Source: jamb.gov.ng" },
    { question: "What are the minimum eligibility requirements to sit the JAMB 2026 UTME?", answer: "Candidates must be at least 16 years old at the time of the examination to qualify for first-degree programmes. Additionally, you must obtain a minimum of five credits in your SSCE or equivalent, including English Language and Mathematics, for most tertiary institutions. Credit in English is mandatory across all courses, while Mathematics requirements vary by programme. JAMB may grant exemptions or relaxations for certain categories, such as candidates with disabilities or those from specific regions, but documentation must be submitted during registration. Check the latest eligibility guidelines on jamb.gov.ng before beginning your registration process. Source: jamb.gov.ng" },
    { question: "How is the JAMB 2026 UTME marked, and what marking scheme is used?", answer: "The UTME uses a Computer-Based Test format where 180 questions are drawn adaptively from a question bank per subject. Each correct answer earns one mark, with no negative marking for incorrect responses. The total score is aggregated out of 400 points, with English Language contributing significantly to the composite score for all candidates. Universities then apply their individual admission cut-off marks, which JAMB releases annually before each admission cycle. Competitive courses like Medicine typically require scores above 250–280, so aspirants should target well above the institutional minimum. Your UTME result remains valid for one admission year only. Source: jamb.gov.ng" },
    { question: "What study resources and strategy are recommended for JAMB 2026 UTME preparation?", answer: "Effective preparation for the UTME requires using JAMB's official syllabus, available on jamb.gov.ng, which lists examinable topics for each subject. Combine this with past UTME questions to familiarise yourself with the CBT interface and adaptive questioning patterns. Allocate at least 6–8 weeks of focused study, dedicating daily sessions to English Language (compulsory) and your three selected subjects. Mock tests under timed conditions are essential to build stamina and identify weak areas. Enrol in a reputable CBT practice centre if you lack a computer, and avoid relying solely on summarised notes—deep understanding of concepts ensures higher scores in the 400-point scale. Source: jamb.gov.ng" }
  ],
  'waec': [
    { question: "What are the official registration periods, fees, and examination diets for WAEC WASSCE 2026?", answer: "The West African Examinations Council administers three WASSCE examination diets annually: WASSCE for School Candidates (May/June series), WASSCE for Private Candidates First Series (January/February, Computer-Based Testing), and WASSCE for Private Candidates Second Series (August/September). For school candidates, registration closes in March with fees set around ₦27,000 per student. Private candidates register online at waeconline.org.ng with a registration pin costing ₦27,000, payable via authorized banks or online cards with mandatory National Identification Number (NIN) authentication. Early registration prevents late entry surcharges. Source: waecnigeria.org" },
    { question: "What is the structure of papers, timing, and grading scale across WAEC WASSCE subjects?", answer: "Each academic subject in WASSCE comprises three component papers: Paper 1 (Objective Multiple Choice, typically 50 questions in 60 minutes for 50 marks), Paper 2 (Theory, Essay, and Structured questions, marked out of 100 in 2 to 2.5 hours), and Paper 3 (Laboratory Practical or Alternative to Practical test for Science, Technical, and Vocational disciplines). Final composite marks are converted into WAEC's 9-point grading scale: A1 (Excellent, 75–100%), B2 (Very Good, 70–74%), B3 (Good, 65–69%), C4–C6 (Credit, 50–64%), D7–E8 (Pass, 40–49%), and F9 (Fail, 0–39%). Source: waecnigeria.org" },
    { question: "Which WAEC credit passes are compulsory for university, polytechnic, and nursing admissions in Nigeria?", answer: "For admission into any Nigerian university or polytechnic, candidates must present a minimum of five credit passes (grades A1 to C6) in subjects relevant to their chosen field of study, achieved in not more than two sittings. Credit in English Language is mandatory across every discipline nationwide, while Mathematics is compulsory for all STEM, business, and social science faculties. Highly competitive professional courses, such as Medicine, Pharmacy, Nursing, and Law, often require that all five required credits be achieved in a single examination sitting for admission clearance. Source: waecnigeria.org" },
    { question: "How can candidates verify, retrieve, or share digital WAEC certificates in 2026?", answer: "WAEC operates the WAEC Digital Certificate Platform (waec.org), which allows candidates to instantly access, share, and verify original digital certificates on desktop or mobile devices. Individuals can generate official shareable digital credentials for domestic university admissions, international credential evaluators (such as WES), or prospective employers without visiting WAEC physical branch offices. Physical paper certificates for school candidates are delivered directly to secondary schools within six months of result release, while private candidates collect them from designated WAEC state zonal offices. Source: waecnigeria.org" },
    { question: "What preparation approach is proven to secure distinction and credit grades across core WAEC subjects?", answer: "Securing credit and distinction grades in WASSCE requires diligent study of the published WAEC syllabus and systematic review of at least five years of past question papers. Focus extensively on Paper 2 presentation skills: in Mathematics, write out every formula and arithmetic step rather than just final values; in English, practice essay structure with clean paragraphing, varied sentence patterns, and correct punctuation. Science candidates should thoroughly master laboratory reporting conventions, error analysis, and accurate diagram labeling for Paper 3, which directly protects composite marks from falling below the 50% credit threshold. Source: waecnigeria.org" }
  ],
  'clat': [
    { question: "When should I start preparing for CLAT and what is the expected exam timeline?", answer: "The Consortium typically releases the CLAT notification in July–August, with registration open through October and the exam held in the first week of December — CLAT 2027 is expected in December 2026 on the same rhythm. Start serious preparation 10–12 months before your exam date. With 120 questions across 5 sections, building familiarity with the paper pattern early helps. Register well before the late-October deadline to avoid last-minute technical issues. The registration fee is Rs. 4,000 (General/OBC) or Rs. 3,500 (SC/ST/BPL/PwD). Source: consortiumofnlus.ac.in" },
    { question: "Which sections in CLAT UG 2026 require the most preparation time and why?", answer: "Current Affairs (including General Knowledge) and Legal Reasoning demand the heaviest time investment. Current Affairs tests knowledge of events from the past year—reading monthly digests from reputable sources gives you an edge. Legal Reasoning tests comprehension of legal principles applied to passages, not prior legal knowledge. Logical Reasoning follows, as puzzles and deduction take practice to speed up. English and Quantitative Techniques are relatively more manageable if your basics are solid. The exam has 120 MCQs, 1 mark each, with a 0.25 negative marking—so strategic section ordering matters. Source: consortiumofnlus.ac.in" },
    { question: "What are the best study resources for cracking CLAT 2026?", answer: "Use the official CLAT 2026 syllabus as your primary guide, available on consortiumofnlus.ac.in. For Legal Reasoning, focus on understanding principles through practice questions rather than memorizing case laws. Subscribe to any two reputable monthly current affairs compilations (online or print). For Quantitative Techniques, strengthen Class 10-level math fundamentals—percentages, ratios, averages appear regularly. For Logical Reasoning, practice from standard CLAT preparation books and previous-year papers (available from 2008 onwards). Do not rely on unverified online quizzes; stick to sources that match the Consortium's stated pattern. Source: consortiumofnlus.ac.in" },
    { question: "How many mock tests should I attempt before CLAT 2026 and how should I analyze them?", answer: "Attempt a minimum of 25–30 full-length mock tests in the final 3 months leading to the December exam. Start with 1–2 mocks per week in September–October, then increase to 3–4 per week by November. After each test, spend equal time analyzing errors—categorize mistakes by section and type (misread, concept gap, time pressure). Track your score trend; if it plateaus below 100/120, revisit foundational concepts for the weakest sections. Simulate exam conditions strictly: 2-hour duration, no breaks mid-test. High-scoring aspirants consistently report that mock analysis—not just quantity—is the real differentiator. Source: consortiumofnlus.ac.in" },
    { question: "What does a realistic weekly study plan for CLAT 2026 look like?", answer: "Dedicate 6–7 hours daily, broken into focused blocks. Morning (2 hours): Current Affairs reading + note-making. Mid-day (2 hours): Legal Reasoning or Logical Reasoning practice. Evening (2 hours): English comprehension or Quantitative Techniques. Reserve one full day weekly for a full mock test and analysis. Alternate between strong and weak sections to prevent burnout on difficult topics. In the last two months before the December exam, shift to test-focused revision with timed section quizzes. Maintain this schedule consistently—sporadic intense sessions are less effective than steady daily progress for an exam testing breadth across 5 distinct areas. Source: consortiumofnlus.ac.in" }
  ],
  'cuet': [
    { question: "How is the CUET 2026 CBT quiz structured across its three sections for a topic-wise practice test?", answer: "The CBT quiz mirrors the actual CUET 2026 format with three distinct sections. Section IA offers 13 language papers (Hindi, English, Tamil, Telugu, etc.) with 50 questions each. Section IB provides 27 domain-specific papers (Physics, Chemistry, Mathematics, History, Economics, etc.), each containing 50 questions from the relevant subject. Section II is a single General Test with 60 questions covering General Awareness, Current Affairs, Mental Ability, and Numerical Ability. Each section is timed independently in the actual exam, so topic quizzes should be timed at 45 minutes per section to build CBT stamina. Source: cuet.nta.nic.in" },
    { question: "What is the CUET 2026 marking scheme that a topic-quiz preparer must factor into every practice attempt?", answer: "Every CUET 2026 question carries +4 for a correct answer and -1 for an incorrect attempt, with no penalty for unattempted questions. Since each section (Language, Domain, General Test) contains 50 questions in Section IA/IB and 60 in Section II, a perfect score per language/domain paper is 200, and the General Test ceiling is 240. When practicing topic quizzes, count every wrong answer as a -1 drain — skipping a question you are unsure about is statistically better than guessing blindly, especially in Section II where General Awareness questions carry equal weight with no extra time. Source: nta.ac.in" },
    { question: "Can I select specific topics within a domain for a practice quiz, and how does CUET 2026 define the full syllabus scope?", answer: "Yes — most topic-quiz platforms let you isolate individual chapters within a domain subject (e.g., \"Electrostatics\" within the Physics paper), mirroring the flexibility CUET offers for choosing which domain papers to attempt. CUET 2026 publishes domain-specific syllabi on its portal covering Class 12 NCERT content for most subjects. For instance, the Mathematics domain tests Calculus, Algebra, Coordinate Geometry, and Statistics — but you can build quizzes around just one sub-topic for targeted revision. Attempting chapter-wise quizzes rather than full-length papers is recommended 8–10 weeks before the exam to plug specific knowledge gaps. Source: cuet.samarth.ac.in" },
    { question: "How does the CBT shift system in CUET 2026 affect how I should schedule my topic-quiz practice sessions?", answer: "CUET 2026 is conducted across multiple CBT shifts (typically 3–4 per day) during the exam window, and your actual shift assignment is random. Topic-quiz practice should therefore be timed to mirror shift conditions: take morning quizzes between 9:00 AM – 12:00 PM and afternoon ones between 3:00 PM – 6:00 PM. This trains your brain to peak during both windows. Since the exam is held in designated cities, also ensure your mock environment is distraction-free with no internet access — mimicking the isolated CBT interface. Practice at least 6–8 full mock quizzes in shifted conditions before the exam date. Source: cuet.nta.nic.in" },
    { question: "How should I interpret my topic-quiz scores to gauge readiness for CUET 2026 and decide which universities to target?", answer: "Use your quiz scores to build a three-tier readiness map. Score above 75% consistently in a domain paper — target central universities like Delhi University or BHU that weight domain scores heavily in their rank lists. Scores between 55–75% indicate borderline selection; focus extra quiz time on weak chapters and retake in 10 days. Below 55% signals a high-risk area requiring a complete syllabus re-revision before the May–June 2026 exam window. Since CUET 2026 scores are normalized across shifts using percentile conversion, your raw quiz scores should be calibrated by comparing percentile rankings in peer cohorts rather than raw marks alone. Source: nta.ac.in" },
    { question: 'What is the expected CUET 2026 exam date and registration timeline?', answer: 'NTA is expected to conduct CUET UG 2026 online in May–June 2026, while the registration window is expected in March–April 2026. These are planning estimates, not a confirmed schedule. Use cuet.samarth.ac.in to watch for the official notification, registration dates, payment deadline and test-city list. The exam uses computer-based testing across multiple sessions, so candidates should also check subject-wise dates once released. Save the notice, verify the timezone and required documents, and complete registration early rather than waiting for the last date. Confirm every revision directly with NTA because session planning depends on the final calendar. Source: cuet.samarth.ac.in' },
    { question: 'What is the subject combination required for CUET 2026?', answer: 'For CUET 2026, plan one Language test because it is compulsory, then select the Domain Subject papers linked to the undergraduate programme you choose. Some programmes also require the General Test. For illustration, a B.Sc. Physics Honours applicant could choose English, Physics and the General Test. Programme restrictions differ across universities, so check the subject list in the official CUET 2026 information brochure before choosing combinations or paying the application fee. Keep a record of each selected paper in your preparation plan and recheck it when an NTA correction or revised notification appears. Source: nta.ac.in' },
    { question: 'How is CUET scores used for university admission in 2026?', answer: 'CUET scores support undergraduate admissions at central universities such as DU, JNU and BHU, as well as at many state and private institutions that accept CUET results. For participating institutions, the CUET-UG portal uses the percentile score for ranking and seat allocation rather than the raw score. A percentile above the 80th is generally competitive for highly sought university programmes, but the accepted score, programme-specific conditions and available seats still govern the actual offer. Before applying, open each university\'s 2026 admission page, confirm its combination of subjects, check the published cutoff, and keep both the scorecard and programme preference details ready for portal verification. Final admission remains subject to institutional rules and seat availability. Source: nta.ac.in' },
  ],
  'cucet-pg': [
    { question: "What is CUET-PG and which universities accept it?", answer: "CUET-PG (Common University Entrance Test, Postgraduate) is the entrance exam run by the National Testing Agency (NTA) for admission to postgraduate programmes at participating universities across India. NTA is an autonomous organisation under the Department of Higher Education, Ministry of Education, Government of India. The official participating-university list is published in four separate categories: Central Universities, State Universities, Government Institutions / Fully Funded, and Deemed / Private Universities. The list is revised each cycle, so check the current published list for the year you are applying to instead of relying on a fixed total. NTA also publishes the syllabus and the full list of paper codes for the exam. Source: exams.nta.nic.in/cuet-pg" },
    { question: "What is the CUET-PG exam pattern?", answer: "CUET (PG) is conducted entirely in Computer Based Test (CBT) mode. Each question paper comprises 75 questions to be attempted in 90 minutes. The marking scheme is +4 marks for every correct response, -1 mark deducted for every incorrect response, and 0 marks for a question left unanswered or marked for review. That makes the maximum raw score 300 for a paper, and it means random guessing actively costs marks. A candidate may choose up to four question paper codes, selecting the paper that matches the postgraduate programme offered by the university where admission is sought. Question papers are bilingual in English and Hindi, except M.Tech / Higher Sciences papers which are English only and Acharya papers which are in Sanskrit; language papers are set in the language of the subject. The exam runs across multiple sessions, so raw scores are normalised before results are declared. Paper codes are grouped into six official domains: Science, M.Tech, Language, Humanities, Common and Acharya. The 2026 cycle published 157 paper codes across those domains. Source: exams.nta.nic.in/cuet-pg (NTA CUET(PG) Information Bulletin)" },
    { question: "What score do I need for CUET-PG admission?", answer: "There is no single CUET-PG cutoff. Each participating university sets its own minimum requirement for each programme, so the score you need depends entirely on where you are applying. NTA publishes a raw score for each paper plus a percentile score within the session, and then a normalised NTA score, because raw scores are not comparable across different sessions or different question papers. Compare the normalised NTA score, not the raw marks, and check the individual university published cutoff for the specific programme. The CUET (PG) 2026 examination was held in March 2026 across multiple sessions, with the result declared on the NTA website. Source: exams.nta.nic.in/cuet-pg" },
  ],
  'cmat': [
    { question: "How many sections does CMAT 2026 have, and what is the total question count plus marking weight used by NTA?", answer: "CMAT 2026 will be held in Computer Based Test (CBT) mode with five mandatory sections: Quantitative Techniques & Data Interpretation, Logical Reasoning, Language Comprehension, General Awareness, and Innovation & Entrepreneurship. Each section typically carries 20 questions, taking the paper to 100 questions for 400 marks. The standard marking scheme used by NTA awards +4 marks for every correct answer and deducts 1 mark for every wrong response; only unattempted questions carry no penalty. Attempt decisions should therefore be accuracy-led — random guessing statistically loses marks. Source: cmat.nta.nic.in" },
    { question: "When is CMAT 2026 expected to be announced, and what registration fee should General, OBC-NCL, and SC/ST candidates budget?", answer: "NTA usually activates the CMAT 2026 information bulletin on cmat.nta.nic.in between March and April, with the application window open for roughly three to four weeks and the CBT held in May. The General (Unreserved) and OBC-NCL male fee has been ₹2,000 in recent cycles, while female candidates of all categories and SC/ST/PwD/Transgender candidates pay ₹1,000 — keep a debit card, net-banking login, and a scanned photograph and signature ready before the window opens to avoid last-minute server rush. Source: cmat.nta.nic.in" },
    { question: "What is the official eligibility condition for CMAT 2026, and are final-year graduation students allowed to apply?", answer: "A candidate must hold a bachelor's degree of minimum three years' duration from a recognised university, or be in the final year of such a programme, with at least 50% marks for the General category and 45% for SC/ST/PwD candidates. There is no upper age limit prescribed by NTA, and Indian citizenship is not a written bar; foreign nationals are eligible on a No-Objection Certificate basis. Confirm category-wise relaxation details from the live information bulletin before submitting the form. Source: nta.ac.in" },
    { question: "How should an aspirant distribute the CMAT 2026 syllabus across a realistic 90-day study plan?", answer: "A practical 90-day split allocates six weeks to Quantitative Techniques (arithmetic, algebra, geometry, data interpretation) and Logical Reasoning (series, coding, arrangements, analytical reasoning), with a daily Reading Comprehension plus vocabulary block for Language Comprehension. Weeks seven and eight should cover the static General Awareness syllabus — economics, polity, current affairs, business GK — using monthly magazines. Reserve the final two weeks for the Innovation & Entrepreneurship section (startup terminology, business plans, IPR basics) and six full-length CBT mock tests with sectional timing. Source: cmat.nta.nic.in" },
    { question: "Does NTA release official CMAT 2026 mock tests or previous-year papers, and where should candidates download them from?", answer: "Yes, NTA publishes a computer-based mock test on cmat.nta.nic.in roughly seven to ten days before the exam window, simulating the actual 180-minute, five-section interface. Candidates should also download the official Information Bulletin PDF and refer to AICTE-recognised MBA/PGDM institute cutoffs from previous cycles for percentile benchmarking, because NTA does not declare a qualifying cutoff. Treat any third-party \"expected cutoff\" page as unofficial — your percentile depends on the slot you appear for. Source: nta.ac.in" }
  ],
  'llb-ent': [
    { question: 'What is LLB-ENT and what options exist for law admission?', answer: 'LLB-ENT on this page is the route into a four-year LLB degree at a South African university, including the University of Cape Town, the University of the Witwatersrand, Stellenbosch and the University of Pretoria. There is no single national South African law entrance paper to sit. Entry is decided on your National Senior Certificate (NSC) subject results, expressed as an Admission Points Score (APS), together with the specific subject levels the university asks for. Most law faculties run three streams: a four-year programme entered straight from school, a three-year LLB for graduates who already hold a bachelor degree, and a two-year LLB for graduates who completed a BA(Law) or BCom(Law). This page does not cover India: if you are looking for CLAT, AILET or CUET PG Law, use the CLAT and AILET pages instead, because those are separate exams with separate syllabi. Source: wits.ac.za publishes the full stream structure and entry requirements for its LLB.' },
    { question: 'What is the difference between the four-year, three-year and two-year LLB routes?', answer: 'Four-year: for school-leavers, who apply straight after writing the NSC and are assessed on their NSC results. At Wits the four-year LLB, programme code LFA14, asks for an APS of 46 or higher with English Home Language or First Additional Language at Level 6, and Mathematics at Level 5 or Mathematical Literacy at Level 6; an APS of 40 to 45 with the same subject levels may be wait-listed depending on places available. Three-year: for graduates, entered after a bachelor degree taken without any law courses, where selection is set by the law school rather than by a school-leaver APS; at Wits the published requirement is an average of at least 65 percent in that degree. Two-year: for graduates who already completed a BA(Law) or BCom(Law) at the same university, because those law credits carry over and only the remaining LLB years are left to study. Because each university sets its own thresholds, read the entry requirements on the law faculty page of the university you are actually targeting rather than assuming another university numbers apply to you. Source: wits.ac.za LLB course page for the stream codes, subject levels and the 65 percent degree average.' },
    { question: 'How is South African LLB admission decided, and do I need an entrance test?', answer: 'Mostly on your school results, not on a written entrance test. The decision rests on your NSC subject performance and the APS derived from it, plus whatever additional selection requirements the particular university publishes. Two things catch first-time applicants out. First, language: law degrees are taught and assessed in English, so English at a stated level is normally required, as at Wits where English Home Language or First Additional Language must reach Level 6. Second, mathematics: a law degree is not a science, yet Wits still requires Mathematics at Level 5 or Mathematical Literacy at Level 6 for its four-year LLB, so treat a mathematics mark as part of the entry requirement rather than an optional subject. A place is also capped rather than assured, because universities hold a fixed number of first-year places approved by the Department of Higher Education and Training, and every university states plainly that meeting the minimum requirements does not guarantee admission. Applicants holding foreign qualifications need matriculation exemption from the South African Matriculation Board on top of the NSC route. Source: wits.ac.za undergraduate entry requirements for the APS basis, the places caution and the matriculation exemption rule for international qualifications.' },
  ],
  'ailet': [
    { question: "What is the official AILET 2026 exam date and when does registration open?", answer: "AILET 2026 (BA LLB and LLM) was held on 14 December 2025 — NLU Delhi moved it from the originally announced 7 December date to avoid a clash with CLAT 2026, with registration having run from 7 August to 10 November 2025. For the AILET 2027 cycle, expect the notification around August 2026 with the exam in December 2026 on the same calendar rhythm. BA LLB candidates pay ₹3,000 (₹1,000 for SC/ST/PwD; SC/ST and BPL candidates may be exempt). Keep signature and photo scans ready and apply early to avoid last-hour portal crashes. Source: nationallawuniversitydelhi.in" },
    { question: "What does the AILET BA LLB syllabus cover across its three sections?", answer: "The official AILET 2027 UG paper has three sections covering 150 MCQs for 150 marks: Section A English Language (50 Qs, 50 marks), Section B Current Affairs & General Knowledge (30 Qs, 30 marks) and Section C Logical Reasoning (70 Qs, 70 marks). Legal principles may appear in the Logical Reasoning section to test logical aptitude, but no legal knowledge is required, and there is no separate Legal Aptitude or Quantitative Techniques paper. English covers comprehension, vocabulary and grammar. Reasoning mixes logical sequences, analogies, syllogisms and blood-relations. Download the section-wise topic list released with the official brochure for the cycle you are appearing for and tick each sub-topic off as you finish. Source: nationallawuniversitydelhi.in" },
    { question: "How is the AILET 2026 paper scored, and what is the minimum qualifying mark?", answer: "AILET 2026 carries 150 marks; each correct answer awards 1 mark, and 0.25 marks are deducted for every wrong response. Duration is 120 minutes (2 hours) — practice strict time-blocking of 48 seconds per question. The qualifying percentage is 40% for General, 35% for SC/ST and 40% for PwD candidates. Clearing the cutoff only makes you eligible; final seats at NLU Delhi are allotted on merit rank, not on qualifying marks. Source: nationallawuniversitydelhi.in" },
    { question: "What is the eligibility criteria and age limit for AILET 2026 BA LLB?", answer: "Candidates must have passed Class 12 (or equivalent) with at least 45% aggregate (42% for OBC-NCL and 40% for SC/ST/PwD). There is no upper age limit prescribed in the 2026 brochure — NLU Delhi dropped the earlier 20-year cap. Students appearing for the Class 12 board exam in 2026 are provisionally eligible provided they produce the passing certificate by the date of admission. Foreign nationals and OCI cardholders can also apply under the foreign-national supernumerary category. Source: nationallawuniversitydelhi.in" },
    { question: "What seat intake and reservation matrix applies to AILET 2026 BA LLB?", answer: "NLU Delhi offers 123 BA LLB seats (including 11 supernumerary seats for foreign nationals) and 50 LLM seats. Reservation follows Government of India norms: 15% SC, 7.5% ST, 27% OBC-NCL (creamy-layer excluded), 5% PwD and the EWS 10% category introduced in 2024. There is no separate All-India Quota — every seat is filled through AILET merit. For LLM, 20 seats sit in the Constitutional Law & Governance stream and the remaining are generic. Confirm category certificates and EWS declarations during upload; mismatches lead to category rejection at counselling. Source: nationallawuniversitydelhi.in" }
  ],
  'al-exam': [
    { question: 'What is the Sri Lanka A/L Examination and who is it for?', answer: 'The Sri Lanka GCE Advanced Level (A/L) Examination is conducted by the Department of Examinations, Sri Lanka, for students who have completed their secondary education (O/L). It is the primary university entrance examination in Sri Lanka — equivalent to A-Levels or the Indian Class 12 board exams. Students choose one of three streams: Science, Commerce, or Arts — and appear for the A/L in their chosen stream. The A/L result (grades A–E) is the key determinant for university admission in Sri Lanka, where admission to public universities is highly competitive and placement is managed through the University Grants Commission (UGC) system. Source: doenets.lk' },
    { question: 'What are the Sri Lanka A/L streams and how do they work?', answer: 'Sri Lanka A/L has three streams: (1) Science Stream — subjects include Physics, Chemistry, Biology, Combined Mathematics, and ICT; (2) Commerce Stream — subjects include Economics, Business Studies, Accounting, and Information Technology; (3) Arts Stream — subjects include Sri Lankan History, Buddhism, Christianity/Islam/Hinduism, Geography, Political Science, and Logic. Students study 3 main subjects (each with theory + practical papers) plus a Common General Test (CGT) covering general knowledge and quantitative skills. Grades are awarded A (Distinction) through E (Fail) for each subject. Source: doenets.lk' },
    { question: 'How are Sri Lanka A/L results used for university admission?', answer: 'Sri Lanka A/L results are processed through the Z-score system — a normalised score that accounts for that year\'s paper difficulty, calculated from the candidate\'s raw marks, the mean of that subject\'s results in that sitting, and its standard deviation for the year. The Z-score determines the merit rank for university admission to public universities. The top Z-scores across all three streams compete for limited seats in popular courses like Medicine, Engineering, and Law. University admission is handled by the UGC Sri Lanka — students submit preferences after A/L results are released (typically in August). The Z-score, stream, and subject combination determine which course a student gets into — arts stream students compete for arts/humanities seats; science stream for STEM seats. Source: ugc.ac.lk' },
  ],
  'lsat': [
    { question: 'What was LSAT—India and why is it no longer conducted?', answer: 'LSAT-India was the Indian variant of the Law School Admission Test, run by the Law School Admission Council (LSAC) with Pearson VUE for Indian law school admissions. LSAC announced in late 2024 that it would discontinue the test from the 2025 admission cycle, and it is no longer offered to candidates in India. Indian applicants now sit the international LSAT, the same test used by US and Canadian law schools. The private and deemed universities that previously admitted through LSAT-India now run their own processes, and each publishes its current criteria on its own admissions page, so verify with the specific college instead of relying on a list that was accurate only while the test existed.' },
    { question: 'What pattern did LSAT—India follow while it was conducted?', answer: 'LSAT—India consisted of four multiple-choice sections of roughly 22–24 questions each, with 35 minutes per section: Reading Comprehension, Analytical Reasoning (logic games), Logical Reasoning I, and Logical Reasoning II — 2 hours 20 minutes in total, online (CBT) at designated centres, with no negative marking. Scores were reported on a 420–780 scale with a median around 580. This is retained for reference only; the skills it tested (reading, logic, legal-style reasoning) overlap heavily with CLAT, so past LSAT prep material still has revision value.' },
    { question: 'What should aspirants who were targeting LSAT—India prepare for instead?', answer: 'Since LSAT—India is discontinued, aspirants targeting NLUs should prepare for CLAT (consortiumofnlus.ac.in), and those targeting NLU Delhi for AILET. Private law schools that formerly accepted LSAT—India admit through their own processes — most publish current criteria on their admissions pages, so verify directly with each college. If you are going the international route instead, it is worth knowing what that test actually is now, because this page no longer describes it for you: LSAC scores the standard LSAT on a 120–180 scale, 120 being the lowest possible score and 180 the highest, and the raw score behind it is simply the number of questions you answered correctly, with no deduction for incorrect answers. It is a four-section multiple-choice test plus a separate LSAT Argumentative Writing sample, so a student moving over from LSAT—India still has a writing component to plan for. The underlying skills (comprehension, logical reasoning) transfer well to CLAT, whose passage-based format tests the same abilities. Source: lsac.org' },
  ],
  'ini-cet': [
    { question: "How many questions does INI-CET 2026 carry per subject, and which subjects have the highest weightage in the CBT syllabus?", answer: "INI-CET 2026 comprises 200 MCQs in a single CBT paper of 3 hours (180 minutes). The question distribution draws from the NMC-prescribed MBBS curriculum: Medicine (including Dermatology), Surgery (including Orthopaedics), Obstetrics & Gynecology, Pediatrics, Pharmacology, Pathology, Microbiology, and Biochemistry each contribute distinct sections. Clinical subjects like Medicine and Surgery collectively account for roughly 35–40% of the paper. Your syllabus audit should prioritize these high-yield areas first, then allocate remaining study time to pre-clinical and para-clinical subjects based on recent topic trends. Source: aiimsexams.ac.in" },
    { question: "What is the exact negative marking scheme in INI-CET 2026, and how should aspirants strategize to avoid score deduction?", answer: "The INI-CET 2026 marking scheme awards +1 mark per correct answer and deducts 1/3 mark (approximately 0.33) for each incorrect response. With 200 questions, the maximum raw score is 200, but unattempted questions cost nothing. To maximize your net score, attempt only questions where your confidence exceeds 70%; leave borderline guesses blank. During your syllabus audit, identify high-frequency, low-ambiguity topics where you can achieve this confidence level, and mark those sections as \"attempt\" zones in your study plan. Source: aiimsexams.ac.in" },
    { question: "Can a candidate with a pending internship in July 2026 appear for INI-CET 2026, and what is the eligibility deadline?", answer: "AIIMS New Delhi requires all candidates to have completed their mandatory rotating internship on or before the prescribed date as published in the official INI-CET 2026 notification. Candidates whose internship completion date falls after the examination date are ineligible to apply. During your syllabus audit, cross-reference your internship completion date with the expected INI-CET 2026 exam date (typically May/June) — if your internship ends in July or later, you must wait for the next cycle rather than allocate full preparation resources to the current attempt. Source: aiimsexams.ac.in" },
    { question: "Which books and resources are recommended for INI-CET 2026 syllabus audit, and how should you prioritize them?", answer: "The INI-CET 2026 syllabus is anchored to the NMC MBBS curriculum, so standard clinical textbooks (Harrison's Principles of Internal Medicine, Bailey & Love for Surgery, DC Dutta for Obstetrics) form the foundation. Supplement with previous year question banks from AIIMS to identify recurring topics. For your syllabus audit, compile a topic-wise checklist from past INI-CET papers — topics appearing in 3+ recent years should be marked \"high priority,\" while one-time appearances can be marked \"moderate.\" Allocate 60% of your revision time to high-priority topics. Source: aiimsexams.ac.in" },
    { question: "What is the qualifying percentile for INI-CET 2026, and does the syllabus audit scope differ for UR vs. reserved category candidates?", answer: "INI-CET 2026 does not publish a fixed qualifying percentage — selection is based purely on rank and seat allocation across participating INIs (AIIMS, JIPMER, NIMHANS, PGIMER, etc.). However, category-wise reservation applies during counseling and seat allocation. For your syllabus audit, understand that all candidates — regardless of category — appear for the same CBT paper of 200 MCQs covering identical NMC topics; no separate syllabus exists for reserved categories. Prepare uniformly, but during counseling, verify which INIs offer reserved quota seats relevant to your category. Source: aiimsexams.ac.in" }
  ],
  'jipmer': [
    { question: "Has JIPMER Puducherry released its 2026 MBBS syllabus PDF, and which subjects carry the highest weightage in the NEET-UG paper that now governs JIPMER admissions?", answer: "For 2026, JIPMER MBBS admissions continue through NEET-UG conducted by NTA, not a separate institute-level test. The NEET-UG 2026 syllabus notified by NTA covers Physics (Class 11+12), Chemistry (Class 11+12), and Biology — Botany & Zoology (Class 11+12), totalling 200 MCQs worth 720 marks. Biology carries the heaviest weight at 360 marks (90 questions × 4), split equally between Botany and Zoology, followed by Chemistry at 180 marks, then Physics at 180 marks. Aspirants should download the NCERT-aligned PDF from the NTA Examinations section rather than the JIPMER site, which now only publishes counselling and seat-allocation notices. Source: jipmer.edu.in" },
    { question: "How do candidates get into JIPMER MD/MS programmes, and what is the exam pattern they must prepare for?", answer: "JIPMER does not conduct its own MD/MS entrance exam — postgraduate admission at JIPMER is through INI-CET (Institutes of National Importance Combined Entrance Test), conducted by AIIMS New Delhi twice a year for the January and July sessions. INI-CET is a computer-based test of 200 MCQs in 3 hours covering the full MBBS curriculum, with +1 for each correct answer and one-third mark deducted for each wrong answer. Applications are filed on aiimsexams.ac.in — track the INI-CET notification there, not the JIPMER announcements page, which only carries counselling and institute notices. Source: aiimsexams.ac.in" },
    { question: "How many MBBS seats do JIPMER Puducherry and Karaikal offer, and through which counselling authority are they allotted?", answer: "JIPMER offers roughly 249 MBBS seats per the MCC seat matrix — about 187 at the Puducherry campus and 62 at the Karaikal campus, including a small NRI/OCI component. Since 2020, all seats are filled through MCC-conducted All India Quota counselling on the basis of NEET-UG merit, with registration typically beginning in July at mcc.nic.in. Puducherry-domicile candidates are not given separate rank lists; domicile operates as a reservation category within the matrix. Candidates must register on both the NTA and MCC portals, and should verify the exact seat matrix in the current MCC counselling bulletin as it shifts slightly each cycle. Source: mcc.nic.in" },
    { question: "What minimum NEET-UG 2026 percentile is required to be eligible for JIPMER MBBS counselling, and are there any category-wise cut-off relaxations?", answer: "The NEET-UG qualifying percentile remains unchanged: 50th percentile for General/EWS, 40th percentile for SC/ST/OBC, and 40th percentile for PwD (with the additional 5% PwD rank relaxation). For 2025 admissions, the closing rank for Unreserved at JIPMER Puducherry was roughly 600–800, and Karaikal closed near rank 5,000 — aspirants should target 700+ for a realistic Puducherry shot. The percentile cutoff is released category-wise by NTA in the result bulletin, and MCC publishes the institute-specific closing rank after Round 2. Anything below the 40th percentile disqualifies the candidate from the JIPMER seat matrix entirely. Source: nta.ac.in" },
    { question: "Has JIPMER announced any changes to its PG entrance process, and how should candidates revise?", answer: "There are no institute-level JIPMER PG exam changes to track — because JIPMER conducts no institute-level PG exam. PG aspirants should follow INI-CET, conducted by AIIMS New Delhi, which has retained its 200-question, 3-hour CBT format with one-third negative marking across recent sessions. Revise the last three years of INI-CET papers for the closest pattern match, prioritise clinical vignettes over rote recall, and track session dates on aiimsexams.ac.in. Source: aiimsexams.ac.in" }
  ],
  'gate': [
    { question: "When will the GATE 2026 official syllabus be released and how should I verify authenticity?", answer: "The GATE 2026 syllabus for all 27 papers is published exclusively at gate.iitb.ac.in and gate.iisc.ac.in at least 3 months before the February 2026 exam window. The official PDF includes a \"Last Updated\" date and version number—compare this against any third-party aggregators before trusting their version. The IISc Bangalore portal (conducting authority for GATE 2026) hosts the authoritative version control log; if you notice a discrepancy between dates, the official portal takes precedence. Download the PDF directly and avoid sites that republish without version attribution. Source: gate.iisc.ac.in" },
    { question: "How much weight does General Aptitude carry across GATE 2026 papers, and which topics must I cover?", answer: "General Aptitude (GA) accounts for 15 marks out of 100 in every GATE 2026 paper—making it a guaranteed 15% contribution regardless of your technical discipline. The section contains 5 one-mark MCQs and 5 two-mark MCQs (10 questions total). Core topics include verbal ability (English grammar, sentence completion), numerical ability (data interpretation, elementary statistics), and logical reasoning (syllogisms, blood relations). Since this component is identical across all 27 subject papers, mastering GA during November–December 2025 provides a stable score floor before diving into technical sections in January 2026. Source: gate.iitb.ac.in" },
    { question: "Can a final-year B.Tech student register for GATE 2026, and what documents are required at counselling?", answer: "Candidates appearing in the final semester/year of their bachelor's degree in engineering/technology (4-year duration) or bachelor's degree in science (3-year) are eligible for GATE 2026—no age limit applies. At the time of counselling (CCMT/CSAB for IITs/NITs, MOS with IISc), you must produce a provisional certificate or a letter from your college principal confirming expected completion by July/August 2026. Failing to submit this documentary proof disqualifies your admission even if you score above the qualifying cutoff. Start collecting this letter from your examination cell now to avoid last-minute delays during the February exam. Source: gate.iitb.ac.in" },
    { question: "What is the negative marking scheme for MCQ, MSQ, and NAT questions in GATE 2026?", answer: "GATE 2026 applies differential negative marking to MCQ questions only: 1/3 mark is deducted for a wrong 1-mark MCQ and 2/3 mark for a wrong 2-mark MCQ. MSQ (multiple select questions, where you must select all correct options) and NAT (numerical answer type, where you type a number) carry zero negative marking—so attempting them is always neutral in penalty terms. This pattern incentivizes skipping high-uncertainty MCQs, particularly 2-mark ones where a wrong answer costs twice the marks of a correct skip. Strategic elimination (narrowing to two options) before guessing can reduce expected score loss by roughly 0.5–1 mark per question. Source: gate.iisc.ac.in" },
    { question: "What qualifying cutoff should I target in GATE 2026 for admission to M.Tech programmes at IITs?", answer: "The GATE 2026 qualifying cutoff is paper-specific and determined after statistical normalization across all test sessions. General category (GE) candidates typically require 25–30 marks out of 100, while OBC-NCL receives a 10% relaxation and SC/ST-PwD receives a 25% relaxation on the cutoff. However, admission to top IITs (IIT Bombay, IIT Delhi, IISc) often requires scores in the 70–90+ range for competitive streams like Computer Science, Electronics, or Mechanical. Merely clearing the qualifying cutoff does not guarantee a seat—check the previous year (2025) opening and closing ranks on the JOSAA/CCMT portal for your target paper code to set a realistic January 2026 score target. Source: gate.iitb.ac.in" }
  ],
  'ugc-net': [
    { question: 'What is UGC NET and what does it qualify you for?', answer: 'UGC NET (University Grants Commission National Eligibility Test) is conducted by NTA for candidates seeking admission to Assistant Professor positions or wanting to pursue a PhD in Indian universities. Clearing UGC NET with a valid score makes you eligible to apply for lecturer and assistant professor posts across universities and colleges in India. The exam is conducted twice a year (June and December cycles) in over 80 subjects. Source: ugcnetonline.in' },
    { question: 'What is the UGC NET exam pattern?', answer: 'UGC NET consists of three papers conducted in a single session of 3 hours and 20 minutes. Paper I (50 questions, 100 marks) tests General Aptitude: teaching and research methodology, reasoning, reading comprehension and divergent thinking. Paper II (50 questions, 100 marks) covers the subject chosen by the candidate. Paper III (75 questions, 150 marks) tests analytical ability in that same subject. That is 175 questions and 350 marks in total. All three papers are objective MCQs. There is no negative marking. The exam is conducted online (CBT) at designated test centres. Source: ugcnetonline.in' },
    { question: 'What is the qualifying criteria for UGC NET?', answer: 'To qualify, a candidate must score at least 40% of the aggregate marks across all three papers for the General and EWS categories, and 35% for OBC-NCL, SC, ST and PwD candidates. Because the exam carries 350 marks in total, that works out to 140 marks for General and EWS and about 123 marks for the reserved categories. There is no separate paper-wise cutoff; the percentage is computed on the aggregate. Qualifying makes a candidate eligible for the NET certificate and for the JRF, but actual recruitment cut-offs are set by individual universities and colleges. Source: ugc.gov.in' },
  ],
  'gre': [
    { question: "What three measured skills does the 2026 GRE General Test actually evaluate, and how is its section order decided on test day?", answer: "The GRE General Test measures Verbal Reasoning, Quantitative Reasoning, and Analytical Writing. On test day you sit five sections: the Analytical Writing section is always first, and the remaining Verbal and Quantitative sections may appear in any order. Two Verbal Reasoning and two Quantitative Reasoning sections are scored, plus an unscored research section that can pop up anywhere. Plan your first 30 minutes around the always-first Analytical Writing task, then stay flexible for whichever Verbal or Quantitative block arrives next. Source: ets.org" },
    { question: "How many GRE Subject Tests are currently offered, and what total testing time should candidates budget for each one?", answer: "ETS offers three GRE Subject Tests: Mathematics, Physics, and Psychology. The Mathematics Test runs 2 hours 50 minutes total, while both the Physics and Psychology Tests run 2 hours total. None of these subject exams has separately timed sections, so the clock runs continuously once you begin. Decide based on your target program: Mathematics for quantitative graduate majors, Physics for physics-heavy departments, Psychology for psychology and neuroscience doctoral tracks. Source: ets.org" },
    { question: "When are the 2026–27 GRE testing-year policies in effect, and what should a fall 2026 applicant verify before booking a seat?", answer: "The 2026–27 GRE publications are in effect from July 1, 2026, to June 30, 2027. Any bulletin, fee schedule, or policy notice you download outside that window is technically last year's edition. Before paying the test fee, confirm three things on your ETS account: your intended test date falls inside the 2026–27 cycle, your score-send recipients are selected, and the at-home or test-center rules you are following are the July 2026 version. Source: ets.org" },
    { question: "Does the GRE General Test include an unscored section, and how should you prepare for it without burning study hours?", answer: "Yes, an unscored research section may appear in any position after Analytical Writing, but it does not count toward your score. Treat every Verbal and Quantitative section as scored, since you will never know which one is the experimental block. Allocate your prep time across both question types equally, avoid the temptation to skip \"weird\" question sets, and use official PowerPrep practice tests to rehearse the unknown-position scenario under timed conditions. Source: ets.org" },
    { question: "Which programs actually accept the GRE General Test, and why does that matter when you decide between the General Test and a Subject Test?", answer: "The GRE General Test is accepted by thousands of graduate, business, and law schools worldwide, making it the default score most programs request. A GRE Subject Test is optional and program-specific: mathematics-heavy PhD programs, top physics departments, and psychology doctoral admissions often recommend or require the matching subject exam to demonstrate depth beyond the General Test's generalist Quantitative section. Check each target program's admission page before registering, because paying for an unrequired Subject Test wastes both the $150 fee and three hours. Source: ets.org" }
  ],
// GMAT FAQ set, 2026-10-18. The four content answers below previously taught
// the retired five-section exam (AWA essay 30 min, IR 12 questions, Quant and
// Verbal 36 questions in 62 minutes each, "3 hours 7 minutes", AWA scored 0-6,
// IR scored 1-8) while the page body at src/data/exams/ghana/gmat.ts correctly
// described GMAT Focus. A 2026 candidate reading the FAQ would have planned the
// wrong number of sections, the wrong clock, and two subscores that no longer
// exist. Rewritten against mba.com exam structure, GMAT score scale and exam
// payment pages; section/time split, 205-805 in 10-point intervals, equal
// weighting, and the US$275 / US$300 fee split all come from those pages.
  'gmat': [
    { question: "Which sections make up the GMAT exam and how is time distributed across them?", answer: "The GMAT in 2026 is the Focus Edition: three computer-adaptive sections totalling 64 questions in 2 hours 15 minutes, with no writing task at all. Quantitative Reasoning is 21 questions in 45 minutes, Verbal Reasoning is 23 questions in 45 minutes, and Data Insights is 20 questions in 45 minutes. Data Insights draws on data sufficiency, multi-source reasoning, table analysis, graphics interpretation and two-part analysis, and it comes with an on-screen calculator. Treat each section as a sealed 45-minute block because no unused time rolls forward. The five-section exam that added an Analytical Writing essay and a separate Integrated Reasoning section was retired and will not return, so skip any coaching material still teaching it. Source: mba.com" },
    { question: "What is the scoring range for the GMAT and what score do top business schools expect?", answer: "The GMAT total score runs from 205 to 805 and is reported in 10-point increments, with each individual section score falling between 60 and 90. The three sections are weighted equally, which is the detail most candidates get wrong: Data Insights moves the total exactly as much as Quantitative Reasoning, so it cannot be treated as a filler block. M7 and top-20 programmes publish medians in the 650–710 band, and roughly 655 sits near the 85th percentile globally. You see unofficial Quant and Verbal scores as soon as the exam ends and decide inside the cancellation window whether to keep or void the attempt. The old 0–6 writing subscore and the 1–8 reasoning subscore are gone from this exam. Source: mba.com" },
    { question: "What is the registration fee for the GMAT in 2026 and what additional costs should candidates budget for?", answer: "The GMAT costs US$275 for a test-centre sitting and US$300 for the online proctored exam, and regional pricing differs, so the amount actually charged outside the United States is often higher. Book early: centre slots fill first during peak application season, and the online option is the one that stays available when a city runs out of seats. Rescheduling inside the 1–60 day window before your appointment carries a further fee that scales with how late you change the date, and a cancellation inside that window is non-refundable entirely. Score reports for schools beyond those chosen at booking are billed per school afterwards. Candidates registering from India should budget for 18% GST applied at checkout. Source: mba.com" },
    { question: "How does the computer-adaptive format affect question selection and scoring on the GMAT?", answer: "The Focus Edition adapts inside Quant and Verbal: the engine chooses your next item from your performance on the one before, so a correct answer raises the difficulty and a wrong one lowers it. Both sections open at the same moderate level, which makes an early slip immediately visible in the questions that follow. Data Insights is no longer folded into Quantitative Reasoning — it is a standalone 45-minute block of 20 fixed questions that does not adapt at all. You cannot skip an item and return to it later, and anything left unanswered when time expires is scored as incorrect rather than omitted. Pace the first ten questions deliberately; adaptation rewards accuracy, not speed. Source: mba.com" },
    { question: "How frequently can a candidate retake the GMAT, and how long are scores valid for applications?", answer: "GMAT scores remain valid for five years from the test date, after which they expire and cannot be reported to schools. Regarding retake policy, candidates may schedule another attempt once every 16 calendar days. Within any rolling 12-month window, up to five attempts are permitted. The total lifetime ceiling is eight attempts. A candidate who cancels a score immediately after viewing it can retake without serving a waiting period if they cancel within the 72-hour window—but a cancelled score remains visible to admissions committees unless a candidate submits a separate appeal to GMAC for removal. Source: mba.com" }
  ],
  'toefl': [
    { question: 'What is TOEFL and which universities require it?', answer: 'TOEFL (Test of English as a Foreign Language) is the world\'s most widely accepted English language proficiency test for academic admissions. It is accepted by over 12,000 universities and institutions in more than 160 countries — including virtually all universities in the USA, UK, Canada, Australia, and Europe for undergraduate and postgraduate admissions. Unlike IELTS, TOEFL is exclusively managed by ETS (Educational Testing Service). For international students whose first language is not English, a TOEFL score is often a mandatory part of the university application alongside SAT/ACT (undergraduate) or GRE/GMAT (postgraduate).' },
    { question: 'What is the TOEFL iBT exam pattern?', answer: 'TOEFL iBT (internet-based test) consists of 4 sections: Reading (35 minutes, 2 academic passages with 20 questions), Listening (36 minutes, 3–4 academic lectures and conversations), Speaking (16 minutes, 4 tasks — 1 independent + 3 integrated tasks), and Writing (29 minutes, 2 tasks — 1 integrated reading/listening/writing + 1 independent essay). Total duration is approximately 2 hours. The exam is conducted online at designated test centres. TOEFL MyBest Scores allows you to combine your best section scores from all TOEFL test attempts in the past 2 years — accepted by most universities. There is no penalty for wrong answers.' },
    { question: 'What TOEFL score do I need for university admission?', answer: 'No university minimum TOEFL score is set by ETS — ETS states plainly that there are no passing or failing scores in the TOEFL Program, and that each institution sets its own requirement. Treat any fixed total quoted on a coaching page as that one institution rule, not as a TOEFL rule. What is universal is the reporting, and it changed recently. Since 21 January 2026 a TOEFL iBT score report gives four section scores (Reading, Listening, Speaking, Writing) and an overall score on a 1–6 scale in half-point increments, aligned to the CEFR, with the overall computed as the average of the four sections rounded to the nearest half band. For a two-year transition after that date you also receive a comparable overall on the old 0–120 scale, so a single report can carry both numbers. When you check a university or visa page, expect either the 1–6 band or the 0–120 equivalent depending on how old that requirement text is, and check separately whether the institution sets per-section minimums, because clearing the overall does not clear those. Source: ets.org for the 1–6 scale, the half-point increments, the section-average overall and the two-year 0–120 transition; the admission requirement itself must be read on the admissions page of the body asking for the score.' },
  ],
  'pte': [
    { question: 'What is PTE Academic and why is it popular?', answer: 'PTE Academic (Pearson Test of English Academic) is a computer-based English language proficiency test accepted by universities, governments, and immigration authorities worldwide. It is particularly popular in Australia and New Zealand for both university admissions and student visa applications — Pearson lists Australia and New Zealand among the immigration authorities that accept PTE, and the minimum score each of them requires depends on the specific visa rather than on the test. PTE is also accepted by most UK universities (including Russell Group), many US universities, and European institutions. The test is fully automated — from speaking to scoring — removing human bias and delivering results within 48 hours.' },
    { question: 'What is the PTE exam pattern?', answer: 'PTE Academic consists of 3 parts taken in 2 hours: Part 1 — Speaking & Writing (77–93 minutes): Read aloud, repeat sentence, describe image, re-tell lecture, short answer questions, essay writing (20 minutes, 200–300 words). Part 2 — Reading (32–41 minutes): Multiple-choice questions (single and multiple answer), reorder paragraphs, fill in the blanks. Part 3 — Listening (45–57 minutes): Summarise spoken text, multiple-choice questions, fill in the blanks, highlight correct summary. All responses are AI-scored by Pearson\'s automated system. Questions are integrated — testing multiple skills simultaneously.' },
    { question: 'What PTE score do I need and how does it compare to IELTS?', answer: 'No universal PTE cut-off exists. Pearson states that institutions set their own minimum scores and that you must always check the specific institution, and that for visa purposes the minimum depends on which visa you are applying for — so any fixed number quoted as the PTE requirement belongs to one university or one immigration authority, not to the test. What is universal is the scoring: PTE Academic reports an overall score from 10 to 90, plus a separate score for each of the four communicative skills, on the Global Scale of English. The overall is not an average of the four skill scores — Pearson says so explicitly in the score guide — so do not try to reconstruct it from the section figures. Two variants matter when you check a requirement: PTE Academic UKVI is the version accepted for UK work visas and study below degree level, while PTE Academic taken in test centre is the version used for Australian and New Zealand visa and immigration purposes. On the IELTS comparison, both are band scales but they run on different ranges, PTE 10–90 against IELTS 0–9, so a PTE figure cannot be read against an IELTS band without Pearson’s published concordance. Source: pearsonpte.com for the 10–90 scale, the separate skill scores, the non-averaged overall, and the UKVI versus Australia/New Zealand visa split.' },
  ],
  'ielts': [
    { question: 'What is IELTS and which countries accept it?', answer: 'IELTS (International English Language Testing System) is the world\'s most popular English language proficiency test — accepted by over 11,000 organisations in 140+ countries for study, work, and migration. It is particularly the standard requirement for universities and immigration in the UK, Australia, New Zealand, Canada, and Ireland. IELTS is jointly managed by the British Council, IDP Education, and Cambridge Assessment. There are two versions: IELTS Academic (for university admissions) and IELTS General Training (for work visas and migration). For university admissions, always take IELTS Academic. Source: ielts.org and takeielts.britishcouncil.org, the official sites of the three test owners.' },
    { question: 'What is the IELTS exam pattern?', answer: 'IELTS Academic consists of 4 sections taken in 2 hours 45 minutes: Listening (30 minutes, 40 questions — 4 recordings of conversations and monologues), Reading (60 minutes, 40 questions — 3 academic texts, academic reading passages), Speaking (11–14 minutes — face-to-face interview with an examiner covering introduction, long turn, and discussion), and Writing (60 minutes — Task 1: describe a graph/table/chart in 150 words; Task 2: essay in 250 words). Both Listening and Speaking are the same for Academic and General Training. Results are reported on a 9-band scale (1 = non-user, 9 = expert). Source: ielts.org and takeielts.britishcouncil.org official test format pages.' },
    { question: 'What IELTS score do I need and how is it scored?', answer: 'No body sets one universal IELTS cut-off. Each university, immigration department and employer publishes its own requirement, so treat any fixed band quoted on a coaching site as that one institution rule rather than as an IELTS rule. What is universal is the scoring itself: every report gives an overall band plus a separate band for each of the four skills, on a 0–9 scale, and the overall is the average of the four skill scores reported to the nearest half band. When you check a specific university or visa subclass, look for two separate numbers — an overall minimum, a per-skill minimum, or both. They are different constraints, and clearing one does not clear the other. Source: ielts.org for the 0–9 band scale and per-skill reporting; the requirement itself must be read on the admissions or immigration page of the body that is asking you for the score.' },
  ],
  'ctet': [
    { question: 'What is CTET and is it mandatory for teaching jobs?', answer: 'CTET (Central Teacher Eligibility Test) is conducted by CBSE (Central Board of Secondary Education) for candidates aspiring to become teachers in government schools (KVs, NVs, CBSE-affiliated private schools) in India. It is not mandatory for all teaching jobs — private schools may or may not require it. However, for government teaching positions, clearing CTET is a mandatory eligibility requirement under the CBSE guidelines. The test is conducted twice a year (typically July and December). Certificate validity is not a fixed number to plan around: NCTE revised the TET validity rule in June 2021, so confirm the period your certificate carries in the current CTET notification on ctet.nic.in. Source: ctet.nic.in' },
    { question: 'What is the CTET exam pattern?', answer: 'CTET has two papers — Paper 1 (for teachers of Class 1–5) and Paper 2 (for teachers of Class 6–8). Paper 1 covers Child Development & Pedagogy (30 questions), Language I (30 questions), Language II (30 questions), Mathematics (30 questions), and Environmental Studies (30 questions) — 150 questions in 150 minutes. Paper 2 covers Child Development & Pedagogy (30 questions), Language I (30 questions), Language II (30 questions), Mathematics & Science (60 questions) OR Social Studies (60 questions) — 150 questions in 150 minutes. There is no negative marking. Source: ctet.nic.in' },
    { question: 'What is a good CTET score for teacher recruitment?', answer: 'To qualify CTET you need 60% aggregate marks, which is 90 out of 150, in the General category, and 55%, which is 82 out of 150, for every reserved category: OBC, SC, ST and PwD alike. One 55% floor covers all reserved categories, so there is no separate SC or ST threshold to plan around. Clearing CTET does not by itself secure a teaching post; it makes you eligible, and states then shortlist on your score alongside your academic qualifications and interview. The CTET certificate is valid for life, so a single sitting covers every recruitment cycle for the rest of your career. Check the live CTET notification before your attempt, because the paper is set centrally and the figures can be revised. Source: ctet.nic.in' },
  ],
  'uptet': [
    { question: 'What is UPTET and how does it differ from CTET?', answer: 'UPTET (Uttar Pradesh Teacher Eligibility Test) is run by the Uttar Pradesh government for candidates aspiring to teach in Uttar Pradesh government schools — from Class 1 to Class 8. The official portal is updeled.gov.in, operated by the U.P. Directorate of Elementary Education (U.P. Pariksha Niyamak Pradhikari, Prayagraj), and results and certificates are published on upessc.up.gov.in. Plenty of older material still names the UP Basic Education Board (UPBEB) as the conducting body; that is out of date. While CTET is a national-level certification accepted across India, UPTET is specifically for Uttar Pradesh state government teaching posts. However, qualifying UPTET also makes a candidate eligible for teaching jobs in some other state boards that recognise it. UPTET is conducted in both Hindi and English — the question paper is available in both languages. Passing UPTET is mandatory for applying to teacher vacancies in UP government schools. Source: updeled.gov.in' },
    { question: 'What is the UPTET exam pattern?', answer: 'UPTET has two papers: Paper 1 (for teachers of Class 1–5) and Paper 2 (for teachers of Class 6–8). Paper 1 covers Child Development & Pedagogy (30 questions), Language I — Hindi (30 questions), Language II — English/Urdu/Sanskrit (30 questions), Mathematics (30 questions), and Environmental Studies (30 questions) — 150 questions in 150 minutes. Paper 2 covers Child Development & Pedagogy (30 questions), Language I — Hindi (30 questions), Language II — English/Urdu/Sanskrit (30 questions), Mathematics & Science (60 questions) OR Social Studies (60 questions) — 150 questions in 150 minutes. There is no negative marking. Each correct answer carries 1 mark. Source: updeled.gov.in' },
    { question: 'What is the UPTET qualifying criteria and validity?', answer: 'To qualify UPTET, candidates need 60% aggregate marks (90 out of 150) in the General category, with a lower cut-off for reserved categories as set out in the notification for that cycle. The UPTET certificate is valid for life. In June 2021 the NCTE replaced its earlier seven-year TET validity rule with one that keeps qualifying certificates valid for life unless the state government notifies otherwise, so UPTET and CTET certificates now follow the same rule. After qualifying, candidates can apply for teacher vacancies in UP government schools under the UP Basic Shiksha service. Some private schools in UP also require UPTET as a minimum qualification. UPTET is distinct from UP TET — some coaching centres incorrectly use these terms interchangeably.' },
  ],
  'du-adm': [
    { question: 'What is DU-ADM and how does it work?', answer: 'DU-ADM on this page is the Dhaka University Unit B admission test, the Science Unit entrance examination run by the University of Dhaka for its Faculty of Science, Faculty of Engineering and Technology, and Faculty of Agriculture. Dhaka University splits undergraduate admission into units, so you sit the paper for the unit that matches your HSC background rather than one shared test for every programme. Shortlisted Engineering and Technology applicants face a viva, and the final merit combines the test result with HSC performance. This has nothing to do with Delhi University, whose undergraduate admissions run through CUET (UG); if you are looking for BBE, BFE or SRCC, you are on the wrong page. Source: du.ac.bd.' },
    { question: 'Which faculties does DU Unit B admission cover, and what subjects decide your eligibility?', answer: 'Unit B is the Science Unit, and it feeds three faculties rather than three named degrees. The Faculty of Science takes programmes built on Physics, Chemistry and either Mathematics or Biology. The Faculty of Engineering and Technology draws candidates from the same unit but treats Mathematics as compulsory, so a strong paper cannot rescue a weak Mathematics score there. The Faculty of Agriculture is admitted from the same unit. You need a science background at HSC level and must meet the exact subject combination printed in your year\'s circular, because that combination, not your overall result, decides which faculties you are eligible to apply to. Source: du.ac.bd.' },
    { question: 'How do I prepare for the DU Unit B admission test?', answer: 'Check the circular before you plan. Dhaka University republishes the paper structure with each admission cycle, and the balance between the objective and written sections has moved between years, so a coaching summary of an earlier sitting is not a usable syllabus. The university\'s notice board at du.ac.bd carries the current circular, and applications, merit lists and results run through admission.eis.du.ac.bd, which was serving a scheduled maintenance notice when this page was checked in October 2026. Time your practice to the duration the circular gives you, and keep an error log by topic rather than by question number. Source: du.ac.bd.' },
  ],
  'ege': [
    { question: 'What is EGE and who is it for?', answer: 'EGE (Единый государственный экзамен, Unified State Examination) is Russia\'s standardised school-leaving exam — the equivalent of A-Levels or the WASSCE. It is the mandatory exam for completing Russian secondary education (Grade 11) and is the primary basis for university admission in Russia. Every student completing secondary school in Russia must take EGE to receive their school certificate and qualify for university admission. For international students, EGE results are used for admission to Russian universities, particularly for government scholarship programmes (quota spots) under the Russian Government Scholarship programme for foreign nationals.' },
    { question: 'What is the EGE exam structure?', answer: 'EGE consists of compulsory exams and elective exams. Compulsory: Russian Language (written, 3 hours) and Mathematics (Base level or Profitable level). Electives for university admission typically include: Physics, Chemistry, Biology, History, Social Science, Computer Science, Geography, and Foreign Languages. Each exam has two parts: a written test and an oral interview (for Russian Language). Exams are scored on a 100-point scale; university admission cutoffs are set by individual universities each year. The exam season runs May–June for school graduates; international students can take EGE at designated centres abroad or in Russia.' },
    { question: 'How do international students use EGE for Russian university admission?', answer: 'International students can gain admission to Russian universities through EGE results, particularly for government quota scholarships (currently about 15,000 scholarship slots per year for foreign nationals). The application process: (1) Take EGE in required subjects — most popular for international students: Mathematics, Physics, Chemistry, Biology (for medicine), or History/Social Science. (2) Apply through the Russian Government Scholarship portal (Russia.StudyinRussia.ru) typically Jan–Mar for the following academic year. (3) Submit EGE certificates to your chosen universities. Minimum passing score is 24/100 for most subjects; competitive programmes (medicine, engineering at top universities like Moscow State University, Sechenov Medical University) typically require 70–85+. English-taught programmes in Russia also require an English proficiency test.' },
  ],
  'gaokao': [
    { question: 'What is GAOKAO and why is it important?', answer: 'GAOKAO (高考, Hanyu Pinyin: Gāokǎo, literally "High School Exam") is China\'s national university entrance examination — one of the most important and pressurised exams in the world. Taken by roughly 12.9 million registered candidates in 2026, down from 13.35 million in 2025, it is the sole determinant of admission to Chinese universities for undergraduate programmes. The exam is administered by the Ministry of Education and is taken over 2–3 days in June every year. A student\'s GAOKAO score (combined with their high school record) determines which universities and programmes they can apply to. It is famously intense — Chinese universities are ranked primarily by admission cutoffs, and scoring well in GAOKAO is seen as life-defining. Source: chinadaily.com.cn' },
    { question: 'What is the GAOKAO exam structure?', answer: 'GAOKAO uses the 3+1+2 model. The "3" is three compulsory papers — Chinese (150 marks, 150 minutes), Mathematics (150 marks, 120 minutes), and Foreign Language (English, Japanese, Russian or German — 150 marks, 120 minutes). The "1" is one stream-defining paper: Physics for the Science stream (lǐkē) or History for the Arts stream (wénkē). The "2" is two further papers chosen from Chemistry, Biology, Politics and Geography — so a Science student sits Physics, Chemistry and Biology, and an Arts student sits History, Politics and Geography. Total is 750 marks, held over 2–3 days in June. Most provinces now run this reformed model; Shanghai and Beijing still use the older 3+3 model (three compulsory plus three chosen from 20 options). Source: chinadaily.com.cn' },
    { question: 'How do international students use GAOKAO for Chinese university admission?', answer: 'International students do not sit the gaokao — that exam is reserved for Chinese citizens, and foreign applicants face no centralised placement round. You apply directly to each university’s international admissions office with transcripts, a study plan, a language certificate (HSK for Chinese-taught programmes, IELTS or TOEFL for English-taught ones) and sometimes an interview. The standardised test for international undergraduates is the China Scholastic Competency Assessment (CSCA), introduced for the September 2026 intake: it is compulsory for Chinese government scholarship holders, required by roughly 306 participating universities, and set to become mandatory for all international undergraduate applicants by 2028. Mathematics is compulsory for every applicant, while English-taught programmes skip the professional Chinese paper. Sitting dates for the September 2026 admission round were 21 December 2025 and 25 January 2026. Guidance claiming foreign applicants qualify on gaokao scores at “typically 70% of the maximum”, or that the CSC scholarship requires a gaokao score, repeats an unsourced rule — plan on CSCA and direct application instead. Source: china-embassy.gov.cn and gdufs.edu.cn' },
    { question: 'How many subjects does a candidate sit in GAOKAO 2026, and which are compulsory?', answer: 'Six papers in total under the 3+1+2 model the Ministry of Education sets for reformed provinces. Three are national unified papers — Chinese, Mathematics and one foreign language — and three are selective papers the candidate chooses: exactly one from Physics or History as the first-choice subject, then two from Politics, Geography, Chemistry and Biology. The Ministry of Education states it as: the "3" is Chinese, Mathematics and Foreign Language; the "1" is one subject chosen from Physics or History; the "2" is two chosen from Politics, Geography, Chemistry or Biology, out of 750 marks. Chemistry and Biology are full examination papers and are the pair most often missed, because candidates assume the only options are History, Politics and Geography. Settle the first-choice subject before the second pair, since universities publish their required subject combinations against it and a later switch can cost a year. Source: moe.gov.cn' },
    { question: 'When is GAOKAO 2026 held, and what happens on each day?', answer: 'Reformed provinces sit the 2026 examination across 7 to 9 June, and each provincial authority publishes its own timetable rather than a single national one. Henan\'s 2026 notice sets 7 June for Chinese and Mathematics, 8 June for the first-choice paper of Physics or History together with the foreign language, and 9 June for the second-choice papers of Chemistry, Geography, Politics and Biology. The foreign language paper is split into a written and a listening component. The marks add to 750: Chinese, Mathematics and the foreign language are worth 150 each and count at raw score, while each of the three selective papers is worth 100. The first-choice subject is counted at raw score; the two second-choice subjects are converted to graded scores before being added, so a strong paper in those two can be compressed by the conversion. Confirm your own province\'s dates before fixing travel or a study timetable. Source: Xinhua, reporting the Henan education department\'s 2026 admissions notice' },
  ],
  'rbi-grad-b': [
    { question: "How is the RBI Grade B 2026 Phase I syllabus structured, and what is the marking scheme for each subject?", answer: "The Phase I Preliminary exam for RBI Grade B 2026 is a single online objective test comprising 200 multiple-choice questions carrying 200 marks. Reasoning covers puzzles, seating arrangement, and analytical reasoning. English Language tests comprehension, grammar, and vocabulary. Quantitative Aptitude includes data interpretation, simplification, and number series. General Awareness focuses on current affairs, banking awareness, and static GI. A negative marking of 0.25 marks applies to every wrong answer in Phase I. Candidates must clear the Phase I cutoff to advance to Phase II. Source: rbi.org.in" },
    { question: "What specific topics under Quantitative Aptitude appear in the RBI Grade B 2026 Phase I syllabus?", answer: "The RBI Grade B 2026 Phase I Quantitative Aptitude section tests data interpretation (tables, bar graphs, pie charts, line charts), approximation and simplification, number series (find the wrong term), quadratic equations, ratio and proportion, percentage, profit and loss, average, time and work, and partnership. Speed and accuracy are critical because the section is time-intensive. DI alone can account for 15–20 questions. Focus on practicing Caselet DI and missing number series from RBI's past papers (2015–2023 pattern). Source: rbi.org.in" },
    { question: "What are the minimum qualifying marks required to pass each Phase II paper in RBI Grade B 2026?", answer: "RBI sets category-wise minimum qualifying marks for each Phase II paper separately. General category candidates typically need 30 marks (or 25 for SC/ST/PwBD) in the Economic and Social Issues paper, 30 marks in Finance and Management, and 30 marks in English Descriptive Writing. These are not aggregate thresholds — failing any single paper disqualifies a candidate regardless of total score. Descriptive answers are evaluated on content relevance, structure, and expression. Candidates should verify exact 2026 qualifying mark thresholds from the official RBI Grade B 2026 notification upon release. Source: rbi.org.in" },
    { question: "What does the Phase II English Descriptive Writing paper test, and how should aspirants prepare for it in 2026?", answer: "The RBI Grade B 2026 Phase II English Descriptive Writing paper (100 marks, 90 minutes) tests comprehension, précis writing, essay writing, and punctuation. Candidates must write one essay from three given topics and one précis on a passage. This paper is separately evaluated and its score is combined with ESI and Finance & Management for the final merit list. Aspirants should practice writing 300-word essays on banking, economy, and social topics weekly. Precision demands practicing condensing 500-word passages into 200-word précis within 15 minutes. Source: rbi.org.in" },
    { question: "How does the RBI Grade B 2026 Phase II Finance and Management syllabus differ from Phase I General Awareness?", answer: "The Phase II Finance and Management paper (100 marks, 3 hours) is a descriptive exam distinct from Phase I General Awareness. Finance covers financial markets (money market, capital market, bond yields, NPA, SARFAESI), union budget analysis, inflation, banking concepts (CRR, SLR, Repo Rate, MSF), and social sector issues. Management covers leadership, Kotter's 8-step model, Maslow's hierarchy, organizational communication, and teamwork. Unlike Phase I MCQs, this paper requires paragraph-length descriptive answers. Aspirants should refer to the RBI Annual Report 2025 and Economic Survey 2025–26 for updated data. Source: rbi.org.in" }
  ],
  'ibps-po': [
    { question: "When will IBPS release the IBPS PO 2026 official notification, and what is the tentative CRP-PO/MT-XVI calendar aspirants should lock in?", answer: "The CRP-PO/MT-XVI notification on ibps.in is expected in the **first week of July 2026**, with online registration open for roughly three weeks. Prelims are scheduled for the **third or fourth week of August 2026**, Mains for the **fourth week of October 2026**, and Interviews/Verification in **January–February 2027**. Bookmark the ibps.in calendar PDF the day it drops — every previous cycle (XIV, XV) has stuck to this Aug-Oct-Jan window. Set a 12-day pre-Prelims revision sprint targeting the 60-minute, three-section Prelims. Source: ibps.in" },
    { question: "How is the IBPS PO Prelims syllabus distributed across the 100 questions, and which section usually decides qualification?", answer: "The Prelims carries **100 questions in 60 minutes** as three **separately timed 20-minute sections**: English Language (30 Qs, 30 marks), Quantitative Aptitude (35 Qs, 30 marks), and Reasoning Ability (35 Qs, 40 marks). Section marks are unequal, and a wrong answer costs **one-fourth of the marks assigned to that question**. Sectional cutoffs are released separately on ibps.in, but the **Reasoning section has historically been the differentiator** — toppers typically clear it with 22+ attempts. Treat Quant as your accuracy gate; over-attempting it drags the score down via negatives. Source: ibps.in" },
    { question: "What are the four objective sections and the Descriptive Test breakdown in the IBPS PO Mains, and how many marks is each worth?", answer: "Mains is an objective battery of **145 questions worth 200 marks in 160 minutes**, with each section separately timed: Reasoning & Computer Aptitude (40 Qs, 60 marks, 50 min), General/Economy/Banking Awareness (35 Qs, 50 marks, 25 min), English Language (35 Qs, 40 marks, 40 min), and Data Analysis & Interpretation (35 Qs, 50 marks, 45 min). IBPS has revised this split across recent cycles, so verify it in the live CRP notification rather than older prep material. The Descriptive Paper of English — **Essay and Comprehension, 2 questions for 25 marks in 30 minutes** — is scored separately. Clear the sectional cutoffs published in the Mains scorecard on ibps.in, then bank on GA/Banking Awareness, which is the highest-scoring section for regular newspaper-readers. Source: ibps.in" },
    { question: "What is the IBPS PO 2026 application fee for General, OBC, and SC/ST/PwBD categories, and the age window with key relaxations?", answer: "Application fee is **₹850 for General and OBC**, and **₹175 for SC/ST/PwBD/Ex-Servicemen**, payable online between the notification and deadline on ibps.in. Age must be between **20 and 30 years as on 1 July 2026** (born between 2 July 1996 and 1 July 2006). OBC gets 3 years, SC/ST 5 years, and PwBD (OC) up to 15 years of relaxation. A bachelor's degree in any discipline from a recognised university is the only educational requirement — IBPS prescribes **no minimum percentage** for PO eligibility, so any recognised degree qualifies. Keep your degree certificate ready for document verification before paying the fee. Source: ibps.in" },
    { question: "What is the qualifying cut-off strategy aspirants should adopt for IBPS PO Prelims 2026, and where are the previous-year cut-offs published?", answer: "The official category-wise and sectional cut-offs for CRP-PO/MT-XV are uploaded as a PDF on ibps.in under \"Cut-off Marks\" — Prelims 2025 General closed near **62–65/100**, OBC around 58–60, and SC/ST 50–55. For 2026, target **75+ raw attempts with ≥85% accuracy** to stay safely above expected cut-offs, since normalization inflates scores by 2–4 marks. Download the last three years' cut-off PDFs, plot your mock scores against them, and reweight your prep to whichever section trails by more than 6 marks. Source: ibps.in" }
  ],
  'ibps-clerk': [
    { question: "When does IBPS Clerk 2026 registration open, and what is the application fee for SC/ST versus General category candidates?", answer: "The CRP Clerks XV notification is typically released in July, with online registration running for roughly three weeks on ibps.in. Aspirants should expect the application window between late July and mid-August 2026. The fee is ₹175 for SC/ST/PwBD/Ex-Servicemen candidates and ₹850 for UR/EWS/OBC, paid only through net-banking, debit card, or credit card on the IBPS portal. No cash or challan mode is accepted. Save the fee receipt and the generated registration number immediately after payment, because without it, the IBPS call letter download link for Preliminary exams will not activate. Source: ibps.in" },
    { question: "What is the section-wise structure and timing for the IBPS Clerk 2026 Preliminary Examination?", answer: "The Preliminary exam is a single online session of 60 minutes carrying 100 questions for 100 marks, divided into three sections: English Language (30 questions, 20 minutes), Numerical Ability (35 questions, 20 minutes), and Reasoning Ability (35 questions, 20 minutes). Each section has its own timer, and candidates cannot switch back once time expires. One-quarter mark is deducted for every wrong answer, so skip questions rather than guess blindly. Sectional cutoffs apply separately, and only the top scorers per category proceed to the Main examination. Source: ibps.in" },
    { question: "How does the Main Examination pattern differ from the Prelims, and how many total questions are asked?", answer: "The Main exam is a single 160-minute online test of 190 questions for 200 marks across four sections: General/Financial Awareness (50), General English (40), Reasoning Ability and Computer Aptitude (50), and Quantitative Aptitude (50). Each wrong answer carries a 0.25-mark penalty, identical to Prelims. The English section is now objective multiple-choice, not descriptive, following recent IBPS revisions. Candidates get sectional timing of roughly 35–45 minutes per section, and qualifying requires clearing both sectional and overall cutoffs published state-wise. Source: ibps.in" },
    { question: "What is the minimum educational qualification and age limit for IBPS Clerk 2026, and are there category-wise relaxations?", answer: "Applicants must hold a bachelor's degree in any discipline from a recognised university, with at least 60% marks for some participating banks, and basic computer certification or prior training as a mandatory requirement. The minimum age is 20 years and the maximum is 28 years as on the cut-off date mentioned in the 2026 notification, meaning candidates born between the notified dates are eligible. SC/ST get a 5-year relaxation, OBC (non-creamy layer) 3 years, and PwBD candidates 10–15 years depending on category. Source: ibps.in" },
    { question: "Which topics carry the highest weightage in the IBPS Clerk 2026 Quantitative Aptitude and Reasoning syllabi, and how should preparation be prioritised?", answer: "For Quantitative Aptitude, simplification, number series, data interpretation, and quadratic equations together account for nearly 60% of the 50 Main questions, so aspirants should solve at least 30 timed sets weekly. For Reasoning, seating arrangement, puzzles, syllogism, and blood relations dominate both Prelims and Mains; aim for 15 minutes per 35-question set. Computer Aptitude focuses on MS Office shortcuts, networking basics, and cyber security terminology — revise from the IBPS-recommended NCERT computer textbook. Neglecting GA is costly because 50 questions can swing your overall rank dramatically. Source: ibps.in" }
  ],
  'aiims-mbbs': [
    { question: 'Is there still a separate AIIMS MBBS entrance exam in 2026?', answer: 'No separate AIIMS MBBS entrance examination remains in 2026. Since 2020, the former standalone AIIMS MBBS test has been merged with NEET UG alongside JIPMER. Admission to AIIMS New Delhi and other AIIMS institutes is now handled through NEET UG rank and MCC counselling. Students should therefore prepare the current NEET UG syllabus and pattern rather than using a separate AIIMS paper. Download the 2026 NEET UG notice from NTA, build revision around the subjects it names, and keep the same scorecard ready for MCC counselling registration. Older AIIMS practice material can be identified as historical, but it should not dictate your current exam schedule or expected questions. Source: nta.ac.in' },
    { question: 'What was the old AIIMS MBBS exam pattern (pre-2020)?', answer: 'The former AIIMS MBBS paper was a 200-question MCQ computer-based test lasting 3 hours 30 minutes. Its sections were Physics 60, Chemistry 60, Biology 60 split between Botany and Zoology, and General Knowledge or Aptitude 20. That standalone format is no longer used for undergraduate AIIMS admission. For 2026 preparation, follow the current NEET UG syllabus and examination notice instead of allocating practice time by the legacy section count. Download the latest NTA pattern, mark the prescribed Physics, Chemistry and Biology areas, and use the official marking rules and duration when building mock tests. This avoids confusing discontinued AIIMS material with the examination that actually governs admission. Source: nta.ac.in' },
    { question: 'How do I get into AIIMS for MBBS now?', answer: 'Qualify NEET UG with a competitive All India Rank, then participate in MCC counselling and select AIIMS campuses under the relevant quota. AIIMS New Delhi typically needs a very high NEET rank; newer AIIMS campuses are somewhat more accessible but still highly competitive. Track seats and rounds on mcc.nic.in and the current NEET information bulletin — not a separate AIIMS UG entrance portal.' },
  ],
  'ssc-cgl': [
    { question: "When will SSC CGL 2026 notification release and what is the registration window?", answer: "The SSC CGL 2026 official notification is expected in March 2026 on ssc.nic.in. Based on the standard annual schedule, the online application window typically opens for 30 days after the notification date. The registration fee is ₹100 for General/OBC male candidates, while Female, SC, ST, and PwD candidates are exempted from fee payment. Aspirants must complete registration, upload documents, pay fees (if applicable), and select exam centers before the deadline — late submissions are rejected automatically. Keep your Aadhaar and educational certificates ready in scanned PDF format (max 1 MB each). Source: ssc.nic.in" },
    { question: "What is the educational qualification required for SSC CGL 2026 posts?", answer: "Candidates must hold a bachelor's degree in any discipline from a recognized university by the closing date of application (typically the notification's last date). Specific posts like Junior Accountant require B.Com, while Statistical Investigator Grade-IV requires B.Statistics or B.A. in Economics with Mathematics/Statistics. The degree must be completed — final-year students are NOT eligible despite appearing in the examination. Post-specific educational requirements are detailed in the detailed vacancy notification published alongside the main advertisement. Check your specific post's requirement before applying to avoid disqualification at verification stage. Source: ssc.gov.in" },
    { question: "What are the age limits and relaxations for SSC CGL 2026 eligibility?", answer: "The age limit varies by post: 18-27 years for Assistant Section Officer (CSS), 18-30 years for Junior Statistical Officer, and 20-32 years for positions like Inspector (Central Excise). Reserved category candidates receive horizontal relaxation: OBC-NC gets 3 years, SC/ST gets 5 years, PwD gets 10 years (UR), 13 years (OBC), 15 years (SC/ST). Age is calculated as of January 1, 2026, meaning candidates born between January 2, 1991, and January 1, 2008, fall within the 32-year upper limit for UR candidates. Candidates claiming age relaxation must present valid category certificates during document verification. Source: ssc.nic.in" },
    { question: "What is the marking scheme for SSC CGL Tier-I and how many questions are asked?", answer: "SSC CGL Tier-I consists of 100 questions worth 200 marks, to be completed in 60 minutes. Each correct answer earns +2 marks, while each wrong answer deducts -0.50 marks (negative marking applies). The exam covers four sections: General Intelligence & Reasoning (25 questions), General Awareness (25 questions), Quantitative Aptitude (25 questions), and English Comprehension (25 questions). The cumulative qualifying cutoff for UR category in Tier-I is typically 140-150 marks out of 200. PwD candidates get 80 minutes total. Tier-II comprises Paper-I (100 questions, 200 marks, 120 minutes) covering Quantitative Abilities and English, plus Paper-II and Paper-III for specific posts. Source: ssc.gov.in" },
    { question: "What are the physical standards required for SSC CGL 2026 inspectorial posts?", answer: "For Inspector positions (CBEC/CBI/ED), the physical standards are: Male candidates must have at least 157 cm height (152 cm for Scheduled Tribes), chest measurement 81-86 cm (expansion 5 cm). Female candidates must have at least 152 cm height (147 cm for ST). For Delhi Police Constable roles under SSC, height criteria are 170 cm (male) and 157 cm (female) with specific relaxation for border area candidates. These physical measurements are verified at the time of Physical Efficiency Test (PET)/Document Verification stage. Candidates failing to meet the standards are permanently disqualified regardless of written exam performance. There is no re-evaluation of physical standards once declared unfit. Source: ssc.nic.in" },
    { question: 'How many tiers does SSC CGL have and what are they?', answer: 'Since the 2022 cycle SSC CGL has 2 tiers: Tier 1 — online MCQ (100 questions, 200 marks, 60 minutes, screening); Tier 2 — online MCQ Mains, with Paper-I compulsory for all posts (Section I: Mathematical Abilities & Reasoning; Section II: English & General Awareness; Section III: Computer Knowledge — qualifying — and a Data Entry Speed Test) plus Paper-II/III only for Junior Statistical Officer and AAO posts. The earlier descriptive Tier-3 and skill-test Tier-4 were discontinued. Final selection is based on Tier-2 marks. Source: ssc.gov.in' },
  ],
  'tnpsc': [
    { question: 'What is TNPSC and how does it work?', answer: 'TNPSC, the Tamil Nadu Public Service Commission, recruits to civil services and administrative posts of the Tamil Nadu state government, and each service group runs under its own notification. This page covers Group 1 Services, whose 2026 advertisement covers Deputy Collector, Assistant Commissioner (Commercial Taxes), Deputy Registrar of Co-operative Societies, District Registrar and Assistant Commissioner of Labour. Group 4 is the separate engineering and general administration track. No Tamil Nadu domicile or institution condition applies here: Group 1 requires a Bachelor degree in any discipline from a recognised university plus the notified second-class Tamil language test. Source: tnpsc.gov.in' },
    { question: 'What is the TNPSC exam pattern?', answer: 'The TNPSC Group 1 preliminary is a single OMR-based objective paper of 200 questions carrying 300 marks in 3 hours. The split is 175 General Studies questions at Degree Standard level plus 25 Aptitude and Mental Ability questions at SSLC Standard level. No marks are deducted for a wrong answer. The notification does fix three small objective-paper deductions instead: 2 marks for an incorrectly written register number where the OMR sheet is non-personalised, and 0.5 mark each for leaving an answer bubble blank or for not affixing the left thumb impression. You clear the stage on 90 marks for reserved-category candidates or 120 for others. Source: tnpsc.gov.in' },
    { question: 'What is a good TNPSC score and how does selection work?', answer: 'A Group 1 candidate carries no preliminary marks into the final rank, so no single prelim score decides the outcome. Selection runs through four 3-hour descriptive main papers and a 100-mark oral interview, giving a final total of 850. Paper I is a mandatory Tamil eligibility test worth 100 marks with 40 as its qualifying bar, and Papers II to IV are General Studies at Degree Standard, 250 marks each, needing 225 for reserved-category candidates and 300 for others. Papers II to IV are evaluated only once Paper I is qualified. Source: tnpsc.gov.in' },
  ],
  'kpsc': [
    { question: "When was the KPSC KAS 2026 notification issued, and when are the prelims held?", answer: "The Karnataka Public Service Commission issued the Gazetted Probationers (KAS) 2026-27 recruitment notification dated 31 July 2026, reference KPSCKA/EXA1/EXMF/9/2026-EXAM-1/I/251710/2026, and fixed the Preliminary Examination date at 15 November 2026. The Commission notifies each Gazetted Probationers cycle separately, so dates from an earlier GP advertisement do not carry forward and an earlier year's coaching material will mislead you. The 2026-27 notification sets a 1:15 ratio of vacancies to candidates called for mains, and the question paper is set in both Kannada and English. Corrigenda are published separately, so check the Notice board on kpsc.kar.nic.in before fixing a study or travel schedule. Source: KPSC GP 2026-27 final notification, 31 July 2026." },
    { question: "What is the paper-wise structure of the KPSC KAS Prelims?", answer: "The KPSC KAS Preliminary Examination is two papers of objective multiple-choice questions, not one. Each paper carries 100 questions worth 200 marks, so 400 marks in total. Paper I covers General Studies of national and international importance (40 questions, 80 marks) and Humanities (60 questions, 120 marks). Paper II covers General Studies of state importance (40 questions, 80 marks), General Science and Technology with Environment and Ecology (30 questions, 60 marks), and General Mental Ability (30 questions, 60 marks). Every question carries two marks. General Mental Ability is set at X standard or SSLC level; the remaining subjects are at degree level. Source: KPSC GP 2026-27 final notification, 31 July 2026, citing the Karnataka Recruitment of Gazetted Probationers (Appointment by Competitive Examinations) (9th Amendment) Rules, 2011." },
    { question: "What are the educational eligibility criteria and age relaxations for KPSC KAS 2026?", answer: "The age caps, the citizenship and degree requirement, the Kannada language rule and the certificate requirements are all set out in the eligibility section above. The notification decides two things at the application stage rather than at the eligibility stage. Final-year candidates cannot apply unless they produce the degree certificate at document verification. Candidates with backlog certificates pending will face disqualification during the interview round. Source: KPSC GP 2026-27 notification, section 10.1." },
    { question: "How does negative marking work in the KPSC KAS Prelims, and what is the exam duration?", answer: "Negative marking applies to every incorrect answer in the KPSC KAS Prelims. For a question carrying two marks, one-fourth of the marks assigned to that question is deducted as penalty, so a wrong answer costs 0.50 mark, not 0.25. Answering a question more than once is treated as wrong even if one of the answers is correct. Leaving a question blank attracts no penalty, so skipping an uncertain question beats a guess. Each prelims paper is 200 marks over two hours, giving 400 marks in total, and the paper is set in Kannada and English. The 2026-27 recruitment fixes a 1:15 ratio of vacancies to candidates called for mains. Source: KPSC GP 2026-27 final notification, 31 July 2026, citing the 10th Amendment Rules, 2013." },
    { question: "What is the optimal study plan for cracking KPSC Prelims and Mains in 2026?", answer: "A 9–12 month structured preparation plan divided into three phases is recommended for KPSC 2026. Phase 1 (Months 1–3): complete static portion — Karnataka History, Geography, Indian Polity ( Lakshmikant), and General Science NCERTs (Class 6–10). Phase 2 (Months 4–7): integrate current affairs using The Hindu or Indian Express daily, revise static notes fortnightly, and begin answer writing for Mains. Phase 3 (Months 8–12): take full-length mock tests every fortnight, focus on Karnataka-specific questions (KPSC frequently draws from state schemes, budgets, and constitutional amendments). For Mains, allocate 2 hours daily to essay practice and optional subject revision. The commission's official syllabus PDF on kpsc.kar.nic.in is the single most reliable resource — cross-reference every topic against it. Avoid over-relying on coaching materials; KPSC questions are known for their Karnataka-contextual framing, which local sources cover more precisely than pan-India materials. Source: kpsc.kar.nic.in" }
  ],
  'cds': [
    { question: 'What is CDS and how does it work?', answer: 'CDS (Combined Defence Services) is a national-level entrance exam conducted by UPSC twice a year for admission to the Indian Military Academy (IMA), Indian Naval Academy (INA), Air Force Academy (AFA), and Officers Training Academy (OTA). It is one of the most prestigious defence examinations in India — candidates cleared in both the written exam and SSB interview receive a Short Service Commission or Permanent Commission in the Indian Armed Forces. Only unmarried candidates are eligible for IMA, INA, and AFA; OTA accepts married candidates.' },
    { question: 'What is the CDS exam pattern?', answer: 'CDS consists of three papers, each of 2 hours duration: Paper 1 — English (100 marks, grammar, vocabulary, reading comprehension), Paper 2 — General Knowledge (100 marks, current affairs, history, geography, science), and Paper 3 — Elementary Mathematics (100 marks, for IMA/INA/AFA only — not required for OTA). All papers are objective MCQs. The exam is conducted offline (pen-and-paper) at centres across India. For OTA, only English and General Knowledge papers are applicable.' },
    { question: 'How does CDS SSB selection work?', answer: 'Candidates who clear the written exam are called for the 5-day SSB interview at one of the SSB centres (Bhopal, Allahabad, Dehradun, Bangalore, or Lucknow). The SSB consists of two stages: Stage I (OIR — Officer Intelligence Rating — and Picture Perception) and Stage II (Psychological Tests, Group Testing tasks, Personal Interview, and Conference). The SSB interview carries 300 marks for IMA/INA/AFA and 200 marks for OTA. The final merit list is prepared by combining written exam marks and SSB interview marks. Medical fitness is also a requirement.' },
  ],
  'bitsat': [
    { question: 'What is the eligibility for BITSAT?', answer: 'For BITSAT 2026 admission, the stated Class 12 benchmark is at least 75% aggregate across Physics, Chemistry and Mathematics, with at least 60% in each subject separately. This threshold is an admission requirement; merely appearing for BITSAT does not require the student to have already crossed it, so Class 12 candidates currently sitting the board examination may also sit BITSAT. No age limit is stated for BITSAT. Use the institute\'s current admission brochure to confirm how aggregate marks are counted and what proof is required if the board result is pending. Keep your marks statement ready, then compare the result with the relevant BITS programme rule before accepting a seat offer. Source: bits-pilani.ac.in' },
    { question: 'What is the BITSAT exam pattern?', answer: 'BITSAT is a computer-based test of 3 hours with 130 multiple-choice questions divided into 4 sections: Physics (30 questions), Chemistry (30 questions), English Proficiency and Logical Reasoning (30 questions in total, split as 10 English Proficiency and 20 Logical Reasoning), and Mathematics or Biology (40 questions). Each correct answer carries +3 marks and each wrong answer carries negative marking of one mark, giving 390 marks in total; questions left unanswered score zero. The exam is conducted in English only. Plan against your own mock score rather than a published cut-off, because the competitive band for BITS Pilani campus admissions shifts every year with the applicant pool. Source: bitsat.edu.in' },
    { question: 'How does BITSAT counselling work?', answer: 'For the 2026 admission cycle, BITSAT counselling runs through JOSAAC for programmes at BITS Pilani, Hyderabad and Goa. After results are declared, candidates submit their course preferences online, and seat allocation proceeds through multiple rounds using rank, listed preferences and seat availability. Review every available programme before the deadline and create several realistic preference orders. After BITSAT, track allotments through the official JOSAAC process and respond within each round\'s stated window. At BITS, the BTech curriculum also permits branch changes after the first year, subject to the published CGPA rule. Review that rule beforehand, and compare campus and programme preferences using the official BITS counselling instructions rather than relying on an old walkthrough. Source: bits-pilani.ac.in' },
  ],
  'bpsc': [
    { question: "What is the BPSC 2026 syllabus audit and where can aspirants download the official subject-wise PDF for both Prelims and Mains?", answer: "The BPSC 2026 syllabus audit is a systematic comparison of the notified syllabus against current PYQs and expected topics to identify high-weightage areas before the Combined Competitive Examination notification drops (expected in the first quarter of 2026). Aspirants should download the standalone Prelims GS syllabus PDF and the Mains paper-wise syllabus (General Hindi, General Studies Paper I, General Studies Paper II, Essay, and the Optional subject) directly from the Syllabus section rather than relying on third-party compilations. The official portal publishes Hindi and English versions. Cross-check each paper code (e.g., 01-General Studies I) with the 70th CCE notification. Source: bpsc.bih.nic.in" },
    { question: "How many papers does the BPSC Mains 2026 written examination comprise and what is the marks distribution per paper?", answer: "The BPSC Mains 2026 written stage comprises five papers: General Hindi (100 marks, qualifying only — a minimum of 30% is required but the marks are not added to merit), General Studies Paper I (300 marks), General Studies Paper II (300 marks), Essay (300 marks), and one Optional Subject paper (100 marks, now a qualifying objective paper). There is no second optional paper. The merit-counted written total is therefore 900 marks (GS I + GS II + Essay), followed by a Personality Test of 120 marks. Allocate roughly one paper per fortnight in the final 90 days and prioritise the Essay and two GS papers, since they alone decide the merit list. Source: bpsc.bih.nic.in" },
    { question: "What is the marking scheme and negative marking rule for the BPSC Prelims 2026 General Studies paper?", answer: "The BPSC Prelims 2026 General Studies paper is a single objective-type test of 150 multiple-choice questions carrying 1 mark each, totalling 150 marks, to be completed in 120 minutes. One-third of a mark (0.33) is deducted for every incorrect answer, so three wrong answers cancel one correct one; from the 70th cycle BPSC also added a fifth 'unanswered' option and penalises questions left entirely blank. Questions are bilingual (Hindi and English), and only the qualifying score (set category-wise, typically around 40% for UR) counts — the Prelims score is not added to the final merit. Source: bpsc.bih.nic.in" },
    { question: "What is the minimum qualifying mark requirement in the BPSC General Hindi paper and does it affect final ranking?", answer: "Candidates must score a minimum of 30 marks out of 100 in the General Hindi qualifying paper (lower thresholds apply to SC/ST and other notified reserved categories as per the latest BPSC reservation schedule). Failing to clear this threshold results in disqualification from the Personality Test stage, regardless of GS performance. Marks obtained in Hindi are NOT counted in the final merit (which is based on the 900 written marks plus the 120-mark Personality Test), but passing is mandatory. Aspirants should solve at least five previous Hindi papers to identify the Bihar-specific essay and grammar pattern before the 2026 cycle. Source: bpsc.bih.nic.in" },
    { question: "What is the educational eligibility and final-year appearing rule for BPSC 2026 candidates?", answer: "For the BPSC 2026 Combined Competitive Examination, the minimum educational qualification is a bachelor's degree in any discipline from a university recognised by the University Grants Commission or an equivalent statutory body. Final-year students appearing in their qualifying degree examination are also provisionally eligible to apply, provided they produce the passing certificate at the Mains document-verification stage. There is no minimum percentage requirement. Aspirants should keep their degree/marksheet and Aadhaar ready before the online application window opens to avoid last-minute portal rejections. Source: bpsc.bih.nic.in" }
  ],
  'ras': [
    { question: "How does the OTR-based application portal on rpsc.rajasthan.gov.in work for RAS 2026 candidates, and what must be done before paying the fee?", answer: "Create your One Time Registration profile on the OTR portal before any specific exam application, then log in to fill the Raj. State and Subordinate Services Combined Competitive Exam 2026 form linked to Advertisement 02/2026-27. Keep your Aadhaar, photograph, signature, and Class 10/12 roll numbers ready because mismatches cause rejection at document verification. Amend OTR fields only through the portal's संशोधन module, not by emailing RPSC, since manual requests are ignored. Submit the application, pay the fee, and download two copies of the confirmation page — one for your records and one for the interview stage. Source: rpsc.rajasthan.gov.in" },
    { question: "Where on the official RPSC website can a RAS 2026 aspirant download Advertisement 02/2026-27 and any corrigendum that follows it?", answer: "Open rpsc.rajasthan.gov.in and navigate to the Recruitment Advertisement / Corrigendum section, where 02/2026-27 for the Raj. State and Subordinate Services Combined Competitive Exam 2026 is listed with serial number 02 and dated 27/05/2026. Every corrigendum issued after the base notice is appended under the same entry with a fresh date stamp, so check back weekly till the Prelims admit card releases. Download the PDF, read the \"सामान्य निर्देश\" and \"परीक्षा योजना\" pages completely — most rejection reasons originate from skipped clauses. RPSC explicitly warns against social-media forwards and advises relying only on this page. Source: rpsc.rajasthan.gov.in" },
    { question: "What nationality and domicile conditions does RPSC specify for the RAS 2026 recruitment?", answer: "The candidate must be a citizen of India, and for most state-service posts under Advertisement 02/2026-27, must also satisfy Rajasthan's domicile rules — typically 10 years' continuous residence, or a Class 1–8 schooling record from a Rajasthan institution, or a parent serving the State Government. Original domicile certificates in the prescribed format, signed by the competent authority, are uploaded during OTR verification. Candidates claiming SC/ST/OBC/EWS/EBC reservation need certificates issued by the Rajasthan SDO/SDM, not from other states, even when the caste is identical. Read the nationality clause of the PDF notification word-for-word before applying. Source: rpsc.rajasthan.gov.in" },
    { question: "What educational qualification does RPSC demand for RAS 2026, and which final-year candidates are also eligible?", answer: "A bachelor's degree from a university established by law in India, or equivalent recognised by the State Government, is the minimum bar — final-year students of the corresponding degree who will appear in the qualifying examination before Mains are provisionally eligible, subject to producing the pass certificate at interview. Candidates with professional or technical degrees (B.Tech, LL.B., MBBS, B.Ed.) are treated as equivalent graduates. Distance and open-university degrees are accepted only if the issuing institution is recognised by the UGC/DEB on the date the degree was awarded — verify the listing before paying the fee. Source: rpsc.rajasthan.gov.in" },
    { question: "How does RPSC count attempts for the RAS 2026 recruitment, and is there an upper ceiling beyond age?", answer: "The Commission treats each appearance in the Prelims as one attempt, regardless of whether the candidate clears it — therefore, track your appearances carefully across cycles since previous counts cannot be reset. There is no separate numerical cap on attempts; eligibility is governed solely by the age window specified in Advertisement 02/2026-27, with SC/ST and OBC-NCL candidates receiving the standard 5-year relaxation and PwD candidates up to 10 years as per State rules. Refer to the PDF table titled \"आयु सीमा\" for the exact DOB window for general, reserved, and women categories before each cycle. Source: rpsc.rajasthan.gov.in" }
  ],
  'xat': [
    { question: "What is the complete section-wise structure of XAT 2026 and how much time does each section get during the 180-minute test?", answer: "XAT 2026 paper has four sections: Verbal and Logical Ability (VLA), Decision Making (DM), Quantitative Ability & Data Interpretation (QA-DI), and General Knowledge (GK). Total duration is 180 minutes, with no sectional time limit for the first three parts — you decide how to allocate time. GK is separately timed at 10 minutes and is used only for shortlisting at XLRI, not for the final percentile. Each correct answer carries 1 mark, and 0.25 marks are deducted for every wrong attempt across VALR, DM, and QA-DI; only the separately-timed GK section is exempt from negative marking. XAT also deducts 0.10 mark per unattempted question beyond the first 8 left blank, so mass skipping is penalised too. Source: xatonline.in" },
    { question: "When will XAT 2026 be held and what is the registration fee structure for different categories?", answer: "XAT is held on the first Sunday of January each year as a single computer-based test, conducted by XLRI Jamshedpur across approximately 80 test cities in India — the next edition, XAT 2027, follows the same calendar with registration typically open from August to early December 2026. The published registration fee is a flat ₹2,200 (plus ₹200 per XLRI programme applied to); XLRI does not publish category-wise fee tiers for XAT. Complete registration well before the December deadline to avoid late-fee penalties and secure your preferred city. Source: xatonline.in" },
    { question: "What is the minimum eligibility criterion for XAT 2026, and are final-year graduation students allowed to apply?", answer: "Candidates must hold a bachelor's degree of at least three years duration, or an equivalent qualification, from a university recognised by the central or state legislative body in India. Final-year students appearing for their qualifying examination in 2026 are also eligible to apply provisionally, provided they furnish proof of graduation by the date specified in the XLRI admission bulletin. There is no upper age limit for XAT, and no minimum percentage cutoff at the test stage — XLRI applies its own cutoffs later during shortlisting. Source: xatonline.in" },
    { question: "How does the XAT 2026 marking scheme work, including negative marking and partial scoring rules?", answer: "XAT 2026 awards 1 mark for each correct response and deducts 0.25 marks for every incorrect MCQ answer across VLA, DM, and QA-DI. Only the separately-timed GK section is exempt from negative marking — Decision Making is fully negatively marked like the rest of Part 1, so treat DM caselets with the same accuracy discipline as VALR and QA-DI. XAT additionally deducts 0.10 mark per unattempted question beyond the first 8, which rewards a balanced attempt strategy over mass skipping. No sectional cutoffs exist at the test stage; XLRI declares sectional and overall cutoffs separately during shortlisting. Source: xatonline.in" },
    { question: "How many B-schools accept the XAT 2026 score, and which XLRI programs use it for shortlisting?", answer: "The XAT 2026 score is accepted by more than 160 participating B-schools across India for admission to their PGDM, MBA, and equivalent management programs. At XLRI Jamshedpur itself, the score shortlists candidates for the flagship Business Management program (BM) and the Human Resource Management program (HRM) on the Jamshedpur and Delhi-NCR campuses. Other top acceptors include XIMB, IMT Ghaziabad, TAPMI Manipal, and IFMR GSB. Aspirants should verify each institute's sectional cutoff weightage before finalising their target list. Source: xatonline.in" }
  ],
  'snap': [
    { question: "How is the SNAP 2026 question paper structured across its three sections?", answer: "SNAP 2026 comprises 60 questions divided across three sections: General English carries 15 questions, Quantitative Data Interpretation and Data Sufficiency carries 20 questions, and Analytical and Logical Reasoning carries 25 questions. The entire paper must be completed within a 60-minute window. Each section is timed collectively rather than individually, meaning you manage your own pacing across sections. Since all questions carry equal weight, strategize by attempting your strongest section first to secure guaranteed marks before tackling weaker areas. Source: snaptest.org" },
    { question: "What is the marking scheme for SNAP 2026 and does wrong answers penalize candidates?", answer: "SNAP 2026 awards 1 mark for every correct answer with zero negative marking for incorrect attempts. This makes attempting all 60 questions risk-free from a penalty standpoint. However, guessing randomly still dilutes your net score if answers are wrong. Use intelligent elimination: if you can narrow options to two plausible answers, the expected value favors attempting. The scoring model rewards accuracy over volume—prioritize question quality over question quantity during your 60-minute window. Source: snaptest.org" },
    { question: "What are the eligibility criteria to appear for SNAP 2026?", answer: "Candidates must hold a bachelor's degree in any discipline with a minimum of 50 percent aggregate marks from a university recognized by the Association of Indian Universities (AIU). Final-year undergraduate students awaiting their results can also apply provisionally. There is no upper age limit for SNAP eligibility, making it accessible to working professionals and gap-year aspirants alike. Ensure your final marksheet reflects the 50 percent threshold before the counseling process, as institutes verify academic records before seat allocation. Source: snaptest.org" },
    { question: "What is the SNAP 2026 registration fee and what does it cover?", answer: "The SNAP 2026 registration fee is Rs 1950 per attempt. This single-window fee covers the entrance test as well as the Symbiosis International University's counseling process for affiliated institutes including SIBM Pune and SCMHRD. Candidates appearing for SNAP can apply to up to three programs through the same score, maximizing the cost efficiency of this registration. Fee payment is conducted online through the official SNAP portal, with admit cards released approximately two weeks before the test date. Source: snaptest.org" },
    { question: "Which topics carry the highest weightage within each SNAP 2026 section?", answer: "For General English, prioritize reading comprehension passages and vocabulary-based questions as they dominate the 15-question section. Quantitative Data Interpretation emphasizes arithmetic topics including percentages, profit-loss, and time-speed-distance alongside data sufficiency sets. Analytical and Logical Reasoning allocates the heaviest weightage with 25 questions covering seating arrangements, blood relations, coding-decoding, and series completion. Allocate your study hours proportionally: 30 percent to Quantitative, 40 percent to Logical Reasoning, and 30 percent to English. This distribution mirrors SNAP's actual section weighting and maximizes your score per study hour invested. Source: snaptest.org" }
  ],
  'vitee': [
    { question: 'What is the VITEEE exam pattern?', answer: 'VITEEE is 125 multiple-choice questions to be answered in 2 hours 30 minutes on a computer, spread across five sections: Mathematics or Biology (40), Physics (35), Chemistry (35), Aptitude (10) and English (5). The 2026 cycle changed the marking scheme, and that change matters more than the section split: 4 marks for a correct answer and 1 mark deducted for an incorrect one, so a random guess now costs a quarter of a correct response. Leaving a question unattempted costs nothing, which changes the whole risk calculation. The Aptitude section deserves the most revision time under this scheme, because it is the most guessable content and therefore the most expensive to guess at. VIT reports the result as a percentile rather than a raw mark, so compare yourself against the percentile band for your course and campus rather than chasing a fixed number. Source: vitee.vit.ac.in for the section split and duration, and the VITEEE 2026 pattern notice on blogs.vit.ac.in for the +4/-1 marking change.' },
    { question: 'What is the eligibility for VITEEE?', answer: 'For VITEEE 2026, eligibility requires Class 12 completion, or appearance in the current year, with at least 60% aggregate in Physics, Chemistry and Mathematics for PCM, or the corresponding Biology route for eligible PCB programmes. For B.Tech Biotechnology at VIT, the stated eligibility also allows candidates from the PCB stream. There is no age limit for VITEEE, and the exam is open to Indian nationals, Non-Resident Indians and foreign nationals. Before registering, check the programme list in the current VITEEE notice, since degree eligibility is programme-specific. Save your Class 12 marks statement or appearance proof, confirm that Mathematics or Biology matches the selected course, and retain the payment record until the application and admit card stages are complete. Source: vit.ac.in' },
    { question: 'How is VITEEE rank calculated?', answer: 'VITEEE ranks use a normalised percentile score because candidates sit multiple test sessions with different papers. The raw marks do not directly determine rank. Candidates are ordered from rank 1 to approximately 1 lakh under the stated ranking scheme. Rank then feeds into MI-MIVIT counselling for BTech programmes at VIT Vellore, Chennai, Amaravati and Bhopal. After receiving the scorecard, note your normalised score and rank, compare them with current programme-wise offer rules, and begin research for the relevant MI-MIVIT round. Check the VITEEE result notice for the normalisation method and cut-offs applicable to 2026 rather than assuming that a raw-score percentage produces the same rank. Source: vit.ac.in' },
  ],
  'manipal-met': [
    { question: 'What is MET and which universities accept it?', answer: 'MET (Manipal Entrance Test) is conducted by Manipal Academy of Higher Education (MAHE) for admission to its flagship B.Tech programmes at MIT Manipal (the original and most prestigious Manipal institute), as well as Manipal University Jaipur and Manipal College of Pharmaceutical Sciences. MET is the only entrance exam accepted for Manipal\'s own programmes — unlike some universities that accept multiple scores. MET is conducted annually (typically May) in online (CBT) mode at centres across India and internationally. Over 50,000 students appear for MET each year, competing for approximately 2,000 B.Tech seats across all campuses.' },
    { question: 'What is the MET exam pattern?', answer: 'MET consists of 160 multiple-choice questions to be answered in 2 hours 30 minutes (150 minutes) on a computer. The sections are: Physics (50 questions), Chemistry (50 questions), Mathematics (50 questions), and English (10 questions). Each correct answer carries 4 marks; there is no negative marking. The exam is conducted online (CBT) in multiple shifts. Since there is no negative marking and all questions carry equal weight, candidates are encouraged to attempt all questions — even uncertain guesses carry a 25% chance of being correct. MET is generally considered easier than JEE Main in terms of difficulty level.' },
    { question: 'How does MET counselling and admission work?', answer: 'MET counselling is conducted by MAHE through its own centralised process (no JoSAA or state counselling). After MET results are declared, candidates fill their programme and campus preferences online. Seat allocation is based on MET rank, preferences, and availability. MIT Manipal offers B.Tech in all major branches including Computer Science, Electronics, Mechanical, Civil, and others. The fee structure at MIT Manipal is approximately ₹3–4 lakhs per semester (tuition only) — one of the more expensive private engineering colleges in India, but with strong placement records (top recruiters include Google, Microsoft, Amazon, Goldman Sachs). Students who score well in MET get first choice of campus and branch.' },
  ],
  'mht-cet': [
    { question: "Which authority publishes the official MHT-CET 2026 syllabus, and which Class 11–12 syllabus does the paper draw from?", answer: "The State Common Entrance Test Cell, Maharashtra (CET Cell) publishes the official PCM syllabus and model question papers on its portal. The syllabus is anchored to the Maharashtra State Board HSC (Class 11 + Class 12) framework for Physics, Chemistry, and Mathematics — not NCERT alone. Aspirants should download the official PDF from the CET Cell 2026 syllabus page, map each chapter weightage, and cross-check board textbook chapters before locking their four-month plan. Source: cetcell.mahacet.org" },
    { question: "What is the subject-wise chapter distribution and expected weightage for MHT-CET 2026 PCM?", answer: "The paper carries 150 questions: 50 Physics, 50 Chemistry, 50 Mathematics, mapped to Class 11 (≈20%) and Class 12 (≈80%) chapters. Physics weight is heavy on Electrostatics, Optics, Semiconductors, and Modern Physics; Chemistry leans toward Solid State, Solutions, Electrochemistry, p-block, and Organic reaction mechanisms; Mathematics emphasises Calculus (Limits, Differentiation, Integration, Differential Equations), Algebra, Probability, and 3D Geometry. Use CET Cell's official chapter-wise syllabus PDF to build a topic-by-topic tracker. Source: cetcell.mahacet.org" },
    { question: "How many questions, marks, and minutes does the MHT-CET 2026 paper carry, and what is the marking scheme?", answer: "The CBT contains 150 multiple-choice questions worth 200 marks in total: Physics 50 × 1 = 50 marks, Chemistry 50 × 1 = 50 marks, Mathematics 50 × 2 = 100 marks, with NO negative marking. Total duration is 180 minutes, administered as two locked 90-minute groups — Physics+Chemistry first (auto-submits at 90 minutes), then Mathematics for the remaining 90 (PwD candidates using scribes get extra time per official norms). Because Mathematics carries double weightage, allocate roughly 50% of your revision hours to it and master 3D Geometry, Vectors, and Differential Equations — the highest-yield units in the official 2026 blueprint. Source: cetcell.mahacet.org" },
    { question: "What are the eligibility conditions and minimum passing marks for MHT-CET 2026 PCM candidates?", answer: "Candidates must have passed Class 12 (HSC) or equivalent with Physics and Mathematics as compulsory subjects plus one of Chemistry / Biotechnology / Biology / Technical Vocational subject, and must secure at least 45% marks (40% for reserved-category Maharashtra candidates) in PCM aggregate. There is NO upper age limit for 2026. NRI, OCI, and PIO candidates holding equivalent foreign qualifications are also eligible, subject to equivalence certificates. Confirm your category-wise cutoff certificate is ready before the May 2026 counselling registration window opens. Source: cetcell.mahacet.org" },
    { question: "What is the expected MHT-CET 2026 exam calendar, application window, and fee structure?", answer: "The State CET Cell typically releases the 2026 notification in January, opens the registration window from mid-January to mid-February, and conducts the PCB + PCM CBT across April–May 2026 (multiple sessions). The application fee is ₹800 for Open category and ₹600 for SC, ST, OBC, SBC, NT, and EWS candidates belonging to Maharashtra, plus applicable portal charges. Admit cards are issued roughly 7 days before each session. Track dates only on the CET Cell 2026 portal — coaching-site date cards are unreliable. Source: cetcell.mahacet.org" }
  ],
  'ap-eapcet': [
    { question: "How many questions does AP EAPCET 2026 carry per subject, and what is the total mark distribution for the Engineering stream?", answer: "The Engineering stream of AP EAPCET 2026 has three subjects — Mathematics, Physics, and Chemistry — each carrying 80 objective questions for 80 marks, totalling 240 questions worth 240 marks. Each correct response earns 1 mark, and there is no negative marking for incorrect answers. The complete paper must be attempted within 180 minutes in a single online CBT session. Bilingual paper options are English and Telugu only, and aspirants should download the subject-wise syllabus PDF before preparing chapter weightage charts. Source: cets.apsche.ap.gov.in" },
    { question: "What is the exact syllabus basis for AP EAPCET 2026, and how should Class 11 vs Class 12 weightage be split during preparation?", answer: "AP EAPCET 2026 derives its syllabus from the First Year and Second Year Intermediate (10+2) syllabus prescribed by the Board of Intermediate Education, Andhra Pradesh. Roughly 60% weightage comes from the Class 12 portion and 40% from the Class 11 portion across Mathematics, Physics, and Chemistry. Candidates should map each topic in the official syllabus PDF against their intermediate textbook chapters, prioritise high-weightage Class 12 units such as Calculus, Electrostatics, and Organic Chemistry, and reserve revision weeks for Class 11 fundamentals. Source: cets.apsche.ap.gov.in" },
    { question: "Which subjects appear in the Medical (Bi.P.C) stream of AP EAPCET 2026, and how many marks does each carry?", answer: "The Bi.P.C stream of AP EAPCET 2026 comprises four subjects — Botany, Zoology, Physics, and Chemistry — with 40 questions per subject for 40 marks each, aggregating 160 questions for 160 marks. Physics and Chemistry overlap with the Engineering syllabus, while Botany and Zoology are exclusive to Bi.P.C candidates and must be prepared from the intermediate second-year content. Duration remains 180 minutes with no negative marking, so attempting every question is the safe strategy. Source: cets.apsche.ap.gov.in" },
    { question: "What is the eligibility criterion for AP EAPCET 2026 Engineering stream, and what relaxation applies to SC/ST candidates?", answer: "Candidates must have passed or be appearing in the 10+2 examination with Mathematics, Physics, and Chemistry as compulsory subjects from a recognised board, securing at least 45% aggregate marks (40% for reserved SC/ST categories) to sit AP EAPCET 2026. There is no upper age limit prescribed by APSCHE for the engineering stream, and Indian nationals including OCI/PIO cardholders are eligible. Aspirants should verify their category certificate format before filling the application to avoid rejection at counselling. Source: cets.apsche.ap.gov.in" },
    { question: "How long is the AP EAPCET 2026 exam duration, and what strategy should candidates follow given the no-negative-marking rule?", answer: "AP EAPCET 2026 allotments 180 minutes (3 hours) for 240 engineering-stream questions or 160 medical-stream questions, which translates to roughly 45 seconds per question. Since no mark is deducted for wrong answers, attempt every question and avoid leaving blanks. Plan the first 120 minutes for subjects you are most confident in (typically Mathematics for engineers, Zoology/Botany for medical aspirants), then use remaining time for moderate-difficulty items. Skip no more than 30 seconds on unfamiliar problems. Source: cets.apsche.ap.gov.in" }
  ],

  'gujcet': [
    { question: 'What is GUJCET and who is it for?', answer: 'GUJCET (Gujarat Common Entrance Test) is a state-level engineering entrance exam conducted by GSEB (Gujarat Secondary and Higher Secondary Education Board) for admission to B.E./B.Tech programmes in colleges across Gujarat. It is primarily for students who have completed their H.S.C. (Class 12) from the GSEB board — but students from other boards (CBSE, ICSE) are also eligible to appear. GUJCET is typically held in April, and the resulting percentile is combined with your Class 12 theory marks to rank you for Gujarat engineering admissions. JEE Main is not part of that calculation. Source: gujacpc.admissions.nic.in' },
    { question: 'What is the GUJCET exam pattern?', answer: 'GUJCET runs as a combined Physics-Chemistry paper of 80 questions (40 Physics plus 40 Chemistry) for 80 marks in 120 minutes, followed by one separate 40-question paper of 40 marks in 60 minutes in either Biology or Mathematics. Which of the two you sit follows the group you register in: Group A is Physics-Chemistry-Mathematics, Group B is Physics-Chemistry-Biology, and Group AB covers all four subjects. Each question carries 1 mark, so a candidate answers 120 questions for 120 marks across 180 minutes. The booklet deducts 0.25 marks for every wrong answer and 1 mark where two or more of the four options are marked for one question. Source: gseb.org' },
    { question: 'How is GUJCET used for Gujarat engineering admission?', answer: 'Gujarat admissions rank you on a composite merit score calculated as 60% of your Class 12 PCM theory percentile plus 40% of your GUJCET percentile. JEE Main does not enter this formula at all, which surprises candidates who assume a national exam is required for Gujarat engineering. This composite decides your state merit rank for counselling by the Admission Committee for Professional Colleges (ACPC), which allocates seats across government, government-aided and private colleges in Gujarat. Read your own rank and the official seat matrix on the ACPC portal instead of planning against a published rank cut-off, because the qualifying rank moves each year with the applicant pool. Source: gujacpc.admissions.nic.in' },
  ],
  'mhcet': [
    { question: 'What is MHCET and who is it for?', answer: 'MHCET (Maharashtra Common Entrance Test) or MAH-MBA/MMS-CET is conducted by the Maharashtra State Cell for admission to MBA/MMS programmes in management colleges across Maharashtra. It is the state-level entrance exam for Maharashtra\'s top B-schools including JBIMS (Jamnalal Bajaj Institute of Management Studies), SIMSREE (Sydenham Institute of Management Studies Research and Entrepreneurship Education), and PUMBA (Pune University Management Business Academy). MHCET is accepted by over 400 MBA colleges in Maharashtra — primarily for Maharashtra domicile candidates, though some seats are available for All India candidates.' },
    { question: 'What is the MHCET exam pattern?', answer: 'MHCET consists of 200 multiple-choice questions to be answered in 150 minutes (2.5 hours). The sections are: Logical Reasoning (75 questions), Abstract Reasoning (25 questions), Quantitative Aptitude (75 questions), and Verbal Ability/Reading Comprehension (25 questions). There is no negative marking in MHCET. The exam is conducted online (CBT) at designated centres across Maharashtra and other states. The difficulty level is generally lower than CAT — most questions are in the easy to moderate range.' },
    { question: 'What score do I need for MHCET?', answer: 'A score of 99+ percentile in MHCET (approximately 145+ out of 200) is needed for the top colleges like JBIMS and SIMSREE. For other top-tier colleges in Mumbai and Pune, a score of 90+ percentile (approximately 120+) is competitive. MHCET percentile is calculated based on the normalised score across all test takers. Unlike CAT, MHCET cutoffs are expressed in percentiles rather than raw scores. Maharashtra domicile candidates get priority in the centralized admission process (CAP) — approximately 70% of seats are reserved for Maharashtra candidates, 30% for All India candidates.' },
  ],
  'nata': [
    { question: 'What is NATA and who is it for?', answer: 'NATA (National Aptitude Test in Architecture) is the national-level entrance exam for admission to B.Arch (Bachelor of Architecture) programmes in India, conducted by the Council of Architecture (COA). It is mandatory for admission to all architecture programmes in India — without a valid NATA score, candidates cannot secure an architecture seat in any Indian institution (government or private). NATA assesses a candidate\'s aptitude for architecture through drawing, observation, and aesthetic sense tests. Candidates who have passed Class 12 with Mathematics as a compulsory subject are eligible. NATA is conducted twice a year (typically March/April and June/July) at designated test centres across India.' },
    { question: 'What is the NATA exam pattern?', answer: 'NATA consists of two parts: Part A — Mathematics & General Aptitude (100 multiple-choice questions, 90 minutes, conducted online at test centres) covering Mathematics (60 questions from Class 11-12), General Aptitude (40 questions covering visual reasoning, logical reasoning, numerical reasoning, verbal reasoning), and English (40 questions). Part B — Drawing Test (02 questions, 90 minutes, conducted offline on A4 paper at designated centres) testing freehand drawing, memory drawing, perspective drawing, and architectural awareness. Each correct answer in Part A carries 2 marks; there is no negative marking. Part B carries 40 marks per question.' },
    { question: 'What score do I need for NATA admission?', answer: 'NATA scores are reported out of 200 (Part A: 200 marks, Part B: 80 marks, scaled to 200). A NATA score of 100+ out of 200 is generally considered passing and sufficient for admission to most architecture colleges. For top architecture schools like School of Planning and Architecture (SPA) Delhi, IIT Roorkee (Architecture), and JJ College of Architecture, a NATA score of 130+ is typically required. For other NATA-accepting private colleges, a score of 80–100 is usually sufficient. The COA sets the minimum qualifying NATA score each year (typically 30% aggregate) but individual colleges set higher cutoffs based on demand.' },
  ],
  'lpunest': [
    { question: 'What is LPUNEST and which programmes does it cover?', answer: 'LPUNEST (Lovely Professional University National Entrance and Scholarship Test) is the entrance and scholarship exam conducted by Lovely Professional University (LPU) in Punjab — one of India\'s largest private universities with over 30,000 students. LPUNEST is used for admission to a wide range of programmes including B.Tech (all branches), MBA, BBA, Law (LLB/BA LLB), Agriculture, Design, Hotel Management, and many more. LPU is unique in that it conducts its own entrance exam — unlike most universities that rely on national or state-level exams. LPUNEST also serves as a scholarship test — the scholarship amount is determined by the LPUNEST score and Class 12 percentage.' },
    { question: 'What is the LPUNEST exam pattern?', answer: 'LPUNEST is an online (CBT) exam with pattern varying by programme: For B.Tech: 90 questions in 150 minutes covering Physics (30), Chemistry (30), Mathematics (30), and English (10 questions). For MBA: 80 questions in 120 minutes covering Verbal Ability & Reading Comprehension, Quantitative Aptitude, and Logical Reasoning. For Law (LPUNEST + CLAT score): similar management aptitude pattern. There is no negative marking in LPUNEST. The exam is conducted at designated centres across India and also has a remote proctored home-based option. Candidates can take LPUNEST from home with a laptop and webcam.' },
    { question: 'What scholarship can I get through LPUNEST?', answer: 'LPU awards scholarships based on LPUNEST scores and previous academic performance: Full scholarship (100% tuition fee waiver) is for students scoring 90%+ percentile in LPUNEST and 90%+ in Class 12. 50% scholarship is for 80–89% percentile in LPUNEST and 80%+ in Class 12. 30% scholarship is for 70–79% percentile in LPUNEST. Scholarships are renewed every semester based on CGPA — a minimum 8.0 SGPA is needed to maintain scholarships above 30%. LPU\'s total fee for B.Tech is approximately ₹2–3 lakhs per semester after scholarship, making it relatively affordable compared to other private universities. Scholarships make LPU accessible to many students who might not afford full fees.' },
  ],
  'jeeupsee': [
    { question: 'What is JEEUPSEE and who is it for?', answer: 'JEEUPSEE (Uttar Pradesh State Entrance Examination) was the state entrance test AKTU used for admission to B.Tech and related programmes across Uttar Pradesh. Its role has narrowed rather than ended: the official UPTAC 2026-27 Information Brochure does not list UPSEE or JEEUPSEE anywhere. Instead it routes B.Tech through JEE (Main)-2026, CUET UG-2026 or Intermediate (10+2); B.Arch through NATA or JEE (Main) Paper 2; and B.Des through UCEED-2026. That brochure is a counselling document and publishes no UPSEE eligibility or domicile rule, so verify the live route on uptac.samarth.edu.in before planning around it. Source: uptac.admissions.nic.in' },
    { question: 'What is the JEEUPSEE exam pattern?', answer: 'Ask this one carefully: the official UPTAC 2026-27 Information Brochure (AKTU letter AKTU-UTAC0ADM/3/2025-UPTAC-AKTU I/110/2026) contains no UPSEE or JEEUPSEE paper pattern and no marking scheme of any kind, so it publishes nothing about negative marking. Any question count, duration or marks-per-correct figure you meet attributed to UPSEE is unsourced, and published sources disagree with one another. What the brochure does publish is the exam priority for current admissions, and UPSEE is absent from it. Treat older Paper 1 and Paper 2 descriptions as historical, confirm the live route on uptac.samarth.edu.in, and do not assume a negative-marking rule in either direction. Source: uptac.admissions.nic.in' },
    { question: 'How does JEEUPSEE admission work?', answer: 'Seat allocation runs through UPTAC, the Uttar Pradesh Technical Admission Counselling, conducted for institutions affiliated to AKTU Lucknow. Counselling follows the exam priority table in the Information Brochure rather than a UPSEE rank: for B.Tech it accepts JEE (Main)-2026 first, then CUET UG-2026, then Intermediate (10+2); B.Pharm runs on CUET UG-2026, and lateral B.Tech accepts CUET UG-2026, a Diploma in Engineering, a BSc or a D.Voc. The brochure governs first-year and lateral-entry admission and publishes no college-wise rank cutoffs, so treat any specific number quoted for IET Lucknow or another college as unsourced and check the live portal. Source: uptac.samarth.edu.in' },
  ],
  'keam': [
    { question: "Which subjects and topics does the KEAM 2026 engineering syllabus cover, and where can candidates download the official PDF?", answer: "The KEAM 2026 engineering syllabus, released by the Commissioner for Entrance Examinations (CEE) Kerala, draws directly from the Kerala Class 11 and 12 SCERT/NCERT curricula. Paper I combines Physics (mechanics, electrostatics, optics, modern physics, semiconductors) and Chemistry (atomic structure, bonding, thermodynamics, equilibrium, organic reactions). Paper II is Mathematics, spanning algebra, calculus, coordinate geometry, vectors, probability, and three-dimensional geometry. Aspirants preparing for the next cycle should download the chapter-wise PDF from the notifications page and tick off topics weekly to avoid backlog. Source: cee-kerala.org" },
    { question: "What is the exact paper pattern, duration, and marking scheme for KEAM 2026 engineering entrance?", answer: "CEE Kerala has confirmed that Paper I (Physics & Chemistry) and Paper II (Mathematics) are conducted on the same day. Each paper carries 120 multiple-choice questions to be attempted in 150 minutes, giving roughly 75 seconds per question. The total score is 960 marks across both papers. There is no negative marking, so leaving a question unattempted only costs you the +4 you would have gained by guessing intelligently. Practice time-management drills of 120 questions in 150 minutes at least twice a week. Source: cee-kerala.org" },
    { question: "How is the KEAM 2026 rank computed, and how much weightage does the board exam carry?", answer: "The engineering rank list blends two halves. The entrance exam contributes 50% of the index score after normalisation, and the Class 12 (Plus Two) marks in Physics, Chemistry, and Mathematics contribute the other 50%. Because the board component matters equally, scoring 90%+ in Plus Two PCM is as decisive as performing well in the entrance. Candidates should therefore treat the Kerala HSE board exam preparation as a parallel KEAM task from day one, not an afterthought after the entrance. Source: cee-kerala.org" },
    { question: "What are the eligibility criteria and category-wise relaxations for KEAM 2026 engineering admissions?", answer: "Indian citizens of Kerala domicile (or those exempt under the prospectus such as children of Kerala Government employees on duty outside the state) are eligible. General category candidates need a minimum 50% aggregate in Physics, Chemistry, and Mathematics at Plus Two or equivalent. Socially and Educationally Backward Classes (SEBC) of Kerala get a 5% relaxation to 45%, while Scheduled Caste and Scheduled Tribe candidates need only 40%. NRI and management quota applicants follow separate clauses in the prospectus, so read pages covering quota definitions before applying. Source: cee-kerala.org" },
    { question: "When does the KEAM application open each year, what is the fee, and what key documents must be ready?", answer: "The CEE Kerala notification typically lands in January–February each year, with the online application window on the KEAM portal running through February or early March, and the engineering entrance held in late April or May (the 2026 exam ran 17–22 April). The application fee is ₹700 for general candidates, ₹300 for SC/ST, and a nominal ₹150 extra if a candidate also applies for medical/architecture streams. Keep ready: Class 10 certificate (for DOB and nativity proof), Plus Two mark list, caste/non-creamy-layer certificate, income certificate for fee concession, a recent passport-size photograph, and a working mobile number for OTP verification. Source: cee-kerala.org" }
  ],
  'kcet': [
    { question: "Which subjects does the KCET 2026 syllabus cover and where can I download the official PDF for the 1st and 2nd PUC topics?", answer: "The KCET 2026 syllabus is prescribed by the Department of Pre-University Education, Karnataka and covers four subjects only — Physics, Chemistry, Mathematics, and Biology — drawn from the 1st and 2nd PUC (Class 11 and 12) curricula. There is no General Knowledge or aptitude paper. The official subject-wise PDF covering all four subjects is hosted on the KEA notifications section; candidates should download the latest version dated for the 2026 cycle and cross-check it chapter-by-chapter against their PUC textbook before starting prep. Source: cetonline.karnataka.gov.in" },
    { question: "How are the 240 questions distributed across papers, and what is the marking scheme for KCET 2026?", answer: "The KCET 2026 test carries 60 questions each in Physics, Chemistry, and the two opted subjects from Mathematics/Biology — a maximum of 240 questions in total, all compulsory. Every question carries 1 mark, there is no negative marking for wrong or unattempted answers, and each subject paper is allotted 80 minutes, so you should practise timed OMR drills. The exam is held offline using OMR sheets across Karnataka centres notified by KEA. Source: keaonline.karnataka.gov.in" },
    { question: "What is the weightage split between Class 11 and Class 12 topics in the KCET 2026 Physics and Chemistry syllabus?", answer: "The KCET 2026 Physics and Chemistry syllabi are mapped chapter-wise to 1st PUC and 2nd PUC units of the Karnataka PUE board, and KEA typically draws roughly 40% of questions from Class 11 portions and 60% from Class 12, with minor year-to-year variation. Mathematics follows a similar Class 11–12 split, while Biology is split into two units covering Botany and Zoology across both PUC years. Candidates should download the subject-wise PDF and tabulate chapter weightage from the last five KEA question-paper analyses. Source: kea.kar.nic.in" },
    { question: "Can I write the KCET 2026 question paper in Kannada, and how do I select the medium of instruction?", answer: "Yes, KCET 2026 is bilingual — the question paper is provided in English and Kannada, and candidates choose their medium at the time of filling the online application on the KEA portal. Once submitted, the medium option is generally not changed, so decide carefully based on your PUC medium and comfort with technical terminology in Physics, Chemistry, Mathematics, and Biology. Carry the same-language PUC admit concepts into mock tests. Source: cetonline.karnataka.gov.in" },
    { question: "Is there any change in the KCET 2026 syllabus compared to the 2025 cycle, and how should I audit my preparation against it?", answer: "KEA has not announced a structural change to the KCET 2026 syllabus beyond the standard PUE 1st and 2nd PUC framework — the four-subject, 240-question, no-negative-marking pattern continues. To audit your prep, download the 2026 PDF, mark chapters already covered in your PUC coaching, and prioritise high-weightage Class 12 units in Physics (e.g., Electrostatics, Optics, Modern Physics) and Chemistry (e.g., Solutions, Electrochemistry, Chemical Kinetics) first, then plug Class 11 gaps in the final 60 days. Source: keaonline.karnataka.gov.in" }
  ],
  'buet-adm': [
    { question: 'What is BUET and how does its admission work?', answer: 'BUET (Bangladesh University of Engineering and Technology) is Bangladesh\'s premier and most prestigious engineering university, consistently ranked #1 in Bangladesh for engineering education. BUET admits students through a centralised university admission test conducted annually after HSC. Students from the Science background in HSC (or equivalent) are eligible. BUET offers undergraduate programmes in Civil, Electrical, Mechanical, Computer Science, Architecture, and several other engineering disciplines. BUET is highly competitive, and the single national test is taken by a large applicant pool competing for a limited number of seats in each unit.' },
    { question: 'What is the BUET admission test pattern?', answer: 'The BUET admission test puts 100 multiple-choice questions in front of you for a 3-hour paper. The questions come from three subjects: Physics (approximately 35 questions), Chemistry (approximately 35 questions), and Mathematics (approximately 30 questions) — all covering the HSC/equivalent syllabus. Each wrong answer carries negative marking (-0.25 per wrong answer). The total marks for the exam vary by year but typically range between 100–120. The exam is conducted in a single sitting on the same day across BUET\'s campus in Dhaka. After the written test, a separate viva voce may be conducted for Architecture applicants.' },
    { question: 'What rank do I need for BUET admission?', answer: 'BUET does not publish a fixed cutoff rank, and any single number quoted online is a guess — the closing rank for Computer Science & Engineering and Electrical & Electronic Engineering moves each year with the applicant pool and the quota split. What is published is the combined merit score: your SSC/HSC GPA (or equivalent, carrying substantial weight) combined with the BUET admission test score. A combined rank is then prepared and used for department allocation during counselling. Students from all over Bangladesh compete — domicile does not provide an advantage.' },
  ],
  'wbjee': [
    { question: 'What is WBJEE and who is it for?', answer: 'WBJEE (West Bengal Joint Entrance Examination) is a state-level engineering entrance exam conducted by the West Bengal Joint Entrance Examinations Board (WBJEEB) for admission to undergraduate engineering, pharmacy, and architecture programmes in colleges across West Bengal. It is open to students who have completed their Class 12 from any recognised board (WBCHSE, CBSE, ICSE) — West Bengal domicile is preferred for government college seats but not mandatory. WBJEE is the primary entrance exam for institutions like Jadavpur University, IIEST Shibpur, and all government and private engineering colleges in West Bengal. Source: wbjeeb.nic.in' },
    { question: 'What is the WBJEE exam pattern?', answer: 'WBJEE consists of two papers: Paper 1 (Mathematics, 75 questions, 2 hours) and Paper 2 (Physics 40 + Chemistry 40 = 80 questions, 2 hours) — 155 questions and 200 marks in total. All questions are multiple-choice with four options across three categories: Category 1 (single correct, 1 mark, −¼ for a wrong answer), Category 2 (single correct, 2 marks, −½ for a wrong answer), and Category 3 (one or more correct, 2 marks, partial marking and no negative marking). The exam is conducted offline (pen-and-paper) in designated centres across West Bengal and other states. Source: wbjeeb.nic.in' },
    { question: 'How does WBJEE admission work?', answer: 'WBJEE scores feed the centralised counselling process (WEBCOUNS) in West Bengal, and your merit rank is derived from the normalised WBJEE score. Colleges publish their own branch-wise closing ranks each year, and those numbers move with the candidate pool, so treat any rank figure you read in an article as last year\'s data. Check your rank against the official closing-rank list published by WBJEEB and each college before you build a preference list, because a branch that closed at one rank for Computer Science can sit at a very different rank for a less popular branch. WEBCOUNS runs in multiple rounds with a fresh rank list after each. Source: wbjeeb.nic.in' },
  ],
  'acsee': [
    { question: 'What is ACSEE and who is it for?', answer: 'ACSEE (Advanced Certificate of Secondary Education Examination) is Tanzania\'s advanced-level secondary examination, run by the National Examinations Council of Tanzania (NECTA). It is not the school-leaving exam — that is the CSEE, taken after Form IV; ACSEE sits on top of it. According to NECTA, it is open to candidates who have completed two years of advanced level secondary education and who hold at least three credits in their CSEE, and it is administered in the first week of May every year. NECTA describes its purpose as assessing learners\' knowledge and ability to pursue further education such as diploma and degree courses. Source: necta.go.tz/pages/acsee' },
    { question: 'What are the ACSEE streams and subjects?', answer: 'NECTA examines General Studies as a compulsory subject for every candidate, plus a subject combination matched to the candidate\'s field. The natural science combinations are PCM (Physics, Chemistry, Mathematics), PCB (Physics, Chemistry, Biology), PGM (Physics, Geography, Mathematics), EGM (Economics, Geography, Mathematics), CBG (Chemistry, Biology, Geography), CBA (Chemistry, Biology, Agriculture) and CBN (Chemistry, Biology, Food and Human Nutrition). The Arts combinations are HGL (History, Geography, English Language), HGK (History, Geography, Kiswahili), HKL (History, Kiswahili, English Language), KLF (Kiswahili, English Language, French), ECA (Economics, Commerce and Accountancy) and HGE (History, Geography and Economics). Each subject carries its own published examination format covering the paper structure, rubric and content. Note that a "Commerce stream" is not one of NECTA\'s published groupings — accountancy sits inside the ECA Arts combination, and Commerce on its own is not listed. Source: necta.go.tz/pages/acsee' },
    { question: 'How are ACSEE results used for university admission in Tanzania?', answer: 'Tanzania\'s higher-education admission is regulated by the Tanzania Commission for Universities (TCU), not by NECTA — NECTA sets and marks the examination, while TCU governs admission to diploma and degree programmes. The ACSEE grade a given programme asks for is therefore set by that programme and by TCU\'s current guidelines, so read the programme prospectus for the cycle you are applying to instead of assuming a general rule. On the examination side NECTA fixes one thing you can plan around: ACSEE runs in the first week of May every year, and every subject has a published examination format describing its paper structure, rubric and content. Source: necta.go.tz/pages/acsee; tcu.go.tz for admission regulation' },
  ],
  'nda': [
    { question: 'What is the eligibility for NDA?', answer: 'Candidates must have completed Class 12 (or be appearing) with Physics, Chemistry, and Mathematics for the IMA/INA/Air Force wings. For the Naval Academy, Engineering branch is mandatory. Candidates must be between 16.5 and 19.5 years of age as of the first day of the month in which the course begins. Only unmarried male and female candidates are eligible. Citizenship: Indian citizens only. Source: upsc.gov.in' },
    { question: 'What is the NDA exam pattern?', answer: 'NDA consists of two written papers: Paper 1 (Mathematics, 300 marks, 2.5 hours) covering Algebra, Matrices, Trigonometry, Analytical Geometry, Differential Calculus, Integral Calculus, Differential Equations, Vector Algebra, Probability, Statistics; and Paper 2 (General Ability Test, 600 marks, 2.5 hours) divided into English (200 marks) and General Knowledge (400 marks) covering Physics, Chemistry, History, Geography, and Current Affairs. Both papers are objective MCQs. The exam is conducted twice a year (NDA I and NDA II) by UPSC. Source: upsc.gov.in' },
    { question: 'What does the NDA SSB interview involve?', answer: 'The Services Selection Board (SSB) interview is a 5-day procedure split into two stages: Stage I (Day 1 — Officer Intelligence Rating and Picture Perception) and Stage II (Days 2-5 — Psychology Tests, Group Testing Officer tasks, Personal Interview, and Conference). Candidates are assessed on officer-like qualities: Leadership, Diligence, Cooperation, Endurance, and Initiative. The SSB interview carries 900 marks combined with the written exam for the final merit list.' },
  ],
  'legon-adm': [
    { question: 'What is Legon ADM and how does university admission work in Ghana?', answer: 'Legon ADM (Admissions Test) refers to the University of Ghana (UG) admissions process for undergraduate programmes at Legon, Accra — Ghana\'s premier university. The University of Ghana uses a combination of West African Senior School Certificate Examination (WASSCE) results and the Legon ADM test for certain programmes. The Legon ADM test is typically required for competitive programmes where WASSCE alone is insufficient for selection. The test is conducted by the University of Ghana\'s IT Services and admissions office. For most programmes, applicants need 6 credits (A1–C6) in their WASSCE including English Language, and additional programme-specific requirements.' },
    { question: 'What programmes require the Legon ADM test?', answer: 'The Legon ADM test is required for the most competitive programmes at the University of Ghana including: Law (LLB), Medicine and Surgery (MBChB), Engineering (BSc Engineering), Business Administration (BBA), and Architecture. For these programmes, a strong WASSCE result alone is not sufficient — candidates must also pass the university\'s own admissions test. The test content varies by programme: Law requires an entrance test in Legal Reasoning and English; Medicine may require an interview; Engineering requires Mathematics and Science reasoning tests. Candidates should check the University of Ghana admissions portal for the specific test format for their programme.' },
    { question: 'How can international students apply to University of Ghana Legon?', answer: 'International students (non-Ghanaian WASSCE holders) apply to the University of Ghana through the same admissions portal as Ghanaian students but may have a separate admissions process. Applicants with foreign qualifications (e.g., GCSE/IGCSE, American High School Diploma, IB) must have their certificates evaluated by the Ghana Education Trust Fund (GETFund) or the National Accreditation Board. International students also need to demonstrate English language proficiency. For Medicine, Law, and other competitive programmes, the Legon ADM test or interview is also required. The University of Ghana has dedicated international student support through the Office of International Education.' },
  ],
  'mu-oet': [
    { question: 'What is MU-OET and which programmes does it cover?', answer: 'MU-OET (Manipal University Online Entrance Test) is the umbrella entrance exam for Manipal Academy of Higher Education (MAHE), which includes Manipal University in Karnataka and its campuses in Jaipur, Dubai, and other locations. MU-OET is used for admission to a wide range of programmes including B.Tech (all branches), MBBS (through NEET, not MU-OET), BDS, B.Pharm, M.Tech, MBA, and other postgraduate programmes. Manipal is one of India\'s largest private universities with a strong reputation in engineering, medicine, and management education. MU-OET is typically conducted online between February and May each year.' },
    { question: 'What is the MU-OET exam pattern for B.Tech?', answer: 'MU-OET for B.Tech consists of 200 multiple-choice questions to be answered in 2 hours 30 minutes. The sections are: Physics (50 questions), Chemistry (50 questions), Mathematics (100 questions). Each correct answer carries 1 mark. There is no negative marking in MU-OET. The exam is conducted online (CBT) at designated test centres and can also be taken from home (online proctored mode) in some years. Questions are based on the CBSE Class 11-12 syllabus. Candidates who have appeared for JEE Main or have a good JEE score may get direct shortlisting for Manipal\'s B.Tech programmes.' },
    { question: 'How does Manipal B.Tech admission work and what score do I need?', answer: 'Manipal B.Tech admission uses MU-OET score for the initial shortlisting, but candidates can also apply with JEE Main scores. A MU-OET score of 140+ out of 200 is generally competitive for popular branches like Computer Science, Information Technology, and Electronics at Manipal\'s main campus (Karnataka). For the Jaipur campus, cutoffs are slightly lower. The Manipal counselling process (MU-OET counselling) allocates seats based on score and preference. The tuition fees for B.Tech at Manipal is approximately ₹3–4 lakhs per year — significantly higher than government engineering colleges but lower than some private peers. Manipal also offers scholarship seats based on MU-OET rank.' },
  ],
  'neet-pg': [
    { question: "Which regulatory body issues the official NEET-PG 2026 syllabus, and where can the PDF be downloaded from?", answer: "The NEET-PG 2026 syllabus is prescribed under the Graduate Medical Education Regulations (GMER) notified by the National Medical Commission and is operationalised by NBEMS. Candidates should download the subject-wise topic list from the \"NEET-PG 2026 Information Bulletin\" section on the NBEMS portal. The bulletin breaks the syllabus into Pre-Clinical, Para-Clinical, and Clinical phases aligned with the MBBS curriculum prescribed by NMC. Revisions, if any, are uploaded only as corrigenda on the same property page, so avoid third-party PDFs circulating on Telegram. Source: natboard.edu.in" },
    { question: "How many questions are asked in NEET-PG 2026, and what is the exact marking scheme?", answer: "The NEET-PG 2026 question paper contains 200 Multiple Choice Questions, each carrying a single correct response out of four options. Every correct answer awards 4 marks, totalling a maximum of 800 marks. Each incorrect response carries a 1-mark negative penalty, and unattempted questions carry zero marks. There is no fractional scoring, and no grace marks are granted for multiple correct options. Strategy implication: aim for 160+ net correct to remain safely above the 50th-percentile cutoff for the General category. Source: natboard.edu.in" },
    { question: "What is the duration and mode of the NEET-PG 2026 examination?", answer: "NEET-PG 2026 is conducted as a single-session Computer Based Test with a fixed duration of 3 hours 30 minutes (210 minutes). NBEMS does not permit sectional breaks or revisiting a previously-submitted section, although candidates can review and change responses within the active window. The test is held in two shifts across pan-India centres mapped to the candidate's chosen city. Carry the printed admit card, a valid photo ID, and the MCI/NMC-issued registration certificate to the venue. Source: natboard.edu.in" },
    { question: "What MBBS-level eligibility documents must be ready before applying for NEET-PG 2026?", answer: "Every applicant must hold an MBBS degree or a provisional MBBS pass certificate from an NMC-recognised institution by the cut-off date notified in the 2026 bulletin. A permanent or provisional registration certificate issued by NMC or a State Medical Council is mandatory. Candidates must also upload the internship completion certificate confirming that the 12-month rotatory internship finishes on or before 31 July 2026. Foreign medical graduates additionally need the FMGE pass certificate and eligibility certificate from NMC. Source: natboard.edu.in" },
    { question: "When is NEET-PG 2026 likely to be held, and how should the syllabus audit be split across months?", answer: "Based on the historical NBEMS calendar, NEET-PG 2026 is expected on 12 July 2026, with the application window opening in the second week of April 2026. Audit the syllabus by allocating 30 days each to Medicine, Surgery, and OBG/Gynae, and 20 days each to Paediatrics, PSM, and the short subjects (ENT, Ophthalmology, Anatomy, Physiology, Biochemistry). Reserve the final 45 days strictly for revision, grand tests, and previous-year paper analysis as per NBEMS pattern. Source: natboard.edu.in" }
  ],
  'sbi-clerk': [
    { question: "What is the exact sectional split and time allocation for SBI Clerk 2026 Preliminary and Main Examinations?", answer: "The Preliminary Examination carries 100 questions for 100 marks across three sections — English Language (30 Qs), Numerical Ability (35 Qs) and Reasoning Ability (35 Qs) — completed in a composite 1 hour. The Main Examination is 200 marks across 190 questions in General/Financial Awareness (50), English Language (40), Quantitative Aptitude (50) and Reasoning Ability & Computer Aptitude (50), and each of those four tests carries its own timer — 35, 35, 45 and 45 minutes — which add up to the 2 hours 40 minutes total. SBI states in its own pattern table that each test has separate timing, so run Mains mocks against a per-section cut-off rather than one composite clock, and take your Prelims section cut-offs from the admit card. Source: sbi.bank.in" },
    { question: "How much is deducted for a wrong answer in SBI Clerk 2026, and is the negative marking identical in both tiers?", answer: "The deduction is one-fourth of the mark assigned to the question, in both the Preliminary and Main Examinations. Most items carry 1 mark, so a wrong answer costs 0.25. The 2-mark items sit in Reasoning Ability & Computer Aptitude, which carries 60 marks across 50 questions, so a wrong one there costs 0.50 — General/Financial Awareness is 50 marks across 50 questions, which makes every item in it 1-mark. Unattempted questions carry zero penalty. Set an accuracy threshold before each mock: roughly 75–80% for Prelims, and higher for Mains, where one Reasoning & Computer Aptitude error costs twice a Prelims error. Source: sbi.bank.in" },
    { question: "What is the age window for SBI Clerk 2026, and which categories receive the maximum relaxation?", answer: "The prescribed age range is 20 to 28 years as on the cut-off date stated in the notification, with a minimum Graduation in any discipline from a recognised university required on the same date. SC/ST candidates receive a 5-year upper-age relaxation, OBC (Non-Creamy Layer) 3 years, and PwBD (SC/ST) get 15 years, (OBC) 13 years, (General/EWS) 10 years. Ex-servicemen and Commissioned Officers fall under the 5-year slab per Government of India rules. Compute your eligibility before paying the fee. Source: sbi.co.in" },
    { question: "What application fee and intimation charge should SBI Clerk 2026 candidates pay by category?", answer: "The application fee plus intimation charge is ₹750 for General, OBC and EWS candidates, while SC, ST, PwBD and ex-servicemen (XS/DXS) candidates pay nil, per the fee table in the JA 2026 detailed advertisement. Read the figure off the advertisement for the cycle you are actually applying to: SBI has published different fee tables for different recruitment cycles, and a number carried over from an earlier advertisement is a common way to get this wrong. Payment must be made online via debit card, credit card, net banking, IMPS or prepaid wallet/voucher generated through the SBI portal on or before the notified last date. Bank transaction charges are borne by the candidate. Download the e-receipt immediately after each successful transaction and retain the fee payment acknowledgement for future correspondence. Source: sbi.bank.in" },
    { question: "When does the SBI Clerk 2026 official notification typically release, and what vacancies scale is expected?", answer: "SBI usually publishes the Junior Associates (Clerk) advertisement in the December–January window for that calendar year's recruitment, with online registration open for roughly three weeks on https://sbi.bank.in/web/careers. The 2024 cycle had 8,773 regular and 5,804 backlog vacancies. Aspirants should track the \"Current Openings\" tab weekly, keep scanned photograph, signature, left-thumb impression and hand-written declaration ready in the prescribed dimensions, and complete the Single Registration on the careers portal before the deadline. Source: sbi.bank.in" }
  ],
  'sbi-po': [
    { question: 'What is SBI PO and how does admission work?', answer: 'SBI PO (Probationary Officer) is a prestigious recruitment exam conducted by the State Bank of India for appointment as Probationary Officers (Assistant Manager) in SBI branches across India. SBI PO is considered one of the most sought-after banking jobs in India due to the attractive salary, allowances, and rapid career progression. After selection, POs undergo a probation period of 2 years during which they receive structured training across various banking operations. The exam is conducted annually by SBI through its official website sbi.co.in.' },
    { question: 'What is the SBI PO exam pattern?', answer: 'SBI PO has three stages: Preliminary (Phase 1), Main (Phase 2), and Interview/Group Discussion (Phase 3). The Preliminary exam has 100 questions (English Language: 30, Numerical Ability: 35, Reasoning Ability: 35) to be completed in 1 hour. The Main exam has 155 objective questions across four sections: Reasoning & Computer Aptitude (45 questions), Data Analysis & Interpretation (35), General/Economy/Banking Awareness (40), and English Language (35). Those four sections carry 200 marks, and a Descriptive Test (Letter Writing & Essay) adds 50 marks. The final merit list is based on Main marks plus Interview marks (weightage 75:25). Source: sbi.co.in' },
    { question: 'What is the SBI PO salary and growth path?', answer: 'SBI PO receives a starting basic pay of ₹41,960 (in ₹41,960–1,340–51,670–1,460–62,330–1,840–73,870–2,050–85,580) plus allowances (DA, HRA, Transport Allowance, etc.), totaling approximately ₹58,000–₹65,000 per month in hand at metro centres. After probation, POs are confirmed as Assistant Managers (Scale-I). Career progression: PO → Assistant Manager → Branch Manager → Deputy Manager → Chief Manager → Assistant General Manager → Deputy General Manager → General Manager. Top performers can reach the level of Chairman/Managing Director.' },
  ],
  'mht-cet-law': [
    { question: "What are the exact sections and their topic distribution in the MHT CET Law 2026 syllabus?", answer: "The MHT CET Law 2026 syllabus carries 120 questions worth 1 mark each, with the State CET Cell publishing the section counts. The 3-year LLB paper runs Legal Aptitude and Legal Reasoning 24 questions, General Knowledge with Current Affairs 32, Logical and Analytical Reasoning 24, and English 40. The 5-year LLB paper rebalances those same four blocks and adds Basic Mathematics 8: Legal Aptitude 32, General Knowledge 24, Logical Reasoning 32, English 24. English is the single largest block on the 3-year paper and mathematics appears only on the 5-year one, so candidates moving between the two programmes should not reuse a single section plan. Source: cetcell.mahacet.org" },
    { question: "How does the negative marking scheme affect scoring in MHT CET Law 2026?", answer: "MHT CET Law carries no negative marking. Each correct answer is worth 1 mark, while a wrong or unanswered question simply scores zero, so nothing is deducted from your total. The State CET Cell's public notice of 28 January 2025 amended the marking scheme for the LLB 3-year and LLB 5-year papers from the 2025-26 academic year, setting them at 120 marks instead of 150 while leaving the 120-minute duration unchanged. Because a blind guess costs you nothing in marks, the discipline that pays is pacing: read each option once, flag anything uncertain, and move on instead of spending the clock on elimination. Source: cetcell.mahacet.org" },
    { question: "What specific topics within Logical and Analytical Reasoning should candidates prioritize for MHT CET Law 2026?", answer: "Based on the official MHT CET Law 2026 syllabus, the Logical and Analytical Reasoning section emphasizes six core topic clusters. Candidates should prioritize blood relations and family tree problems (3-4 questions expected), coding-decoding patterns including letter-number hybrid formats (3-4 questions), and syllogism statements with all/certain/none quantifiers (4-5 questions). Additional focus areas include direction and distance problems, seating arrangement puzzles (linear and circular), and analogy-based reasoning. The State CET Cell sets this section at 24 questions on the 3-year paper and 32 on the 5-year paper, so calibrate against papers from the matching programme: anything written before 2025 ran to 150 marks, and its section ratios will not match the current paper. Source: cetcell.mahacet.org" },
    { question: "Which Legal Aptitude topics carry the highest weightage in the MHT CET Law 2026 examination?", answer: "The Legal Aptitude section of MHT CET Law 2026 tests candidates through two sub-components: legal GK and legal reasoning. Legal GK covers the Indian Constitution (Fundamental Rights, Directive Principles) and landmark Supreme Court judgments. Legal reasoning includes tort law basics (negligence, strict liability), contract law fundamentals, and criminal law concepts (Indian Penal Code provisions). The State CET Cell sets the combined block at 24 questions on the 3-year paper and 32 on the 5-year paper, and publishes no split between the GK and reasoning halves, so treat any unofficial question-count breakdown as guidance rather than the official allocation. Practice applying legal principles to factual scenarios instead of recalling bare provisions. Source: cetcell.mahacet.org" },
    { question: "What systematic approach should candidates use to audit their MHT CET Law 2026 syllabus preparation?", answer: "An effective syllabus audit for MHT CET Law 2026 requires a three-phase diagnostic approach. Phase 1 (Days 1-7): Attempt one full-length mock test under timed conditions to identify baseline performance across all four sections. Phase 2 (Days 8-21): Categorize each question into mastered (correct without hesitation), borderline (correct after deliberation), and weak (incorrect or skipped) buckets. Phase 3 (Days 22-30): Allocate 60% of study time to weak sections, 30% to borderline topics, and 10% to reinforcement of mastered areas. The State CET Cell public notice of 28 January 2025, effective from 2025-26, leaves the syllabus, component weightage and the 120-minute duration unchanged, so you can plan against the current paper without waiting on a revision. Keep a daily tracking sheet of hours per section against measurable progress. Source: cetcell.mahacet.org" }
  ],
  'up-psc': [
    { question: "How many stages does the UPPSC 2026 Combined State/Upper Subordinate Services exam contain, and what is the nature of each stage?", answer: "The UPPSC 2026 examination is conducted in three stages: Preliminary (screening), Main (written), and Interview (personality test). The Prelims consists of two compulsory objective-type papers of 200 marks each, held on a single day. The Main examination uses conventional (descriptive) answer type, where answers are evaluated for content accuracy, depth, and presentation. The Interview stage carries 100 marks and tests communication skills, leadership traits, and overall personality. Only candidates clearing each stage in sequence are included in the final merit list, which is prepared by aggregating Main and Interview scores. Source: uppsc.up.nic.in" },
    { question: "What topics does UPPSC Prelims General Studies Paper I cover in 2026, and which areas carry the highest weightage?", answer: "UPPSC Prelims General Studies Paper I covers Indian History including ancient, medieval, and modern periods, Indian Polity covering the Constitution and governance structure, Geography of India and the world including physical and economic geography, and General Science encompassing physics, chemistry, biology, and environmental science. According to the 2026 syllabus notified on uppsc.up.nic.in, this paper tests conceptual understanding and factual recall. A common trap is confusing medieval history dates with modern events — aspirants should use separate revision timelines for each sub-topic. The syllabus does not include current affairs as a separate paper in Prelims, though static knowledge is frequently tested through contemporary contexts. Source: uppsc.up.nic.in" },
    { question: "What is the application fee for UPPSC 2026 for General, OBC, SC, and ST categories, and what is the age relaxation for OBC candidates?", answer: "The application fee for General category candidates is Rs. 80/- for online submission through the official portal. OBC and SC candidates typically enjoy reduced fees, while ST candidates and persons with disabilities are exempted from fee payment under government welfare provisions. The upper age limit for General category is 21 to 42 years, with OBC candidates receiving a 3-year relaxation and SC/ST candidates receiving a 5-year relaxation from the upper age ceiling. PwD candidates from any category receive up to 10 years relaxation. All fee payments must be completed before the deadline specified in the 2026 notification, and no offline fee submissions are accepted. Source: uppsc.up.nic.in" },
    { question: "What is the negative marking scheme in UPPSC Prelims 2026, and what qualifying score is needed to clear each paper?", answer: "For every wrong answer in UPPSC Prelims 2026, 0.33 marks are deducted as negative marking, calculated on a total of 200 marks per paper. Candidates must score a minimum of 33% in each paper independently to qualify for the Mains examination. Since both papers are compulsory and carry equal weight, a candidate scoring 40% in Paper I but only 28% in Paper II will be disqualified despite an aggregate above the cut-off. The Prelims is purely a screening stage and its marks are not added to the final merit. Aspirants should avoid attempting questions where they cannot eliminate at least two options, as random guessing yields an expected negative score. Source: uppsc.up.nic.in" },
    { question: "What is the exam calendar timeline for UPPSC 2026 Prelims and Main, and when is the official notification expected?", answer: "UPPSC releases its annual examination calendar on the official website at uppsc.up.nic.in with tentative schedules for each stage. The 2026 Prelims is typically held between August and October, with the official online application window opening in January or February of the examination year. The Main examination follows approximately 3-4 months after the Prelims result declaration, usually scheduled between December and March. Candidates must regularly check uppsc.up.nic.in/Default.aspx for exact date announcements, as postponements have occurred due to administrative or pandemic-related disruptions. No other platform is authorised to release the official schedule, so aspirants should bookmark the homepage and activate SMS/email alerts through the portal to avoid missing critical deadlines. Source: uppsc.up.nic.in" }
  ],
  'jupeb': [
    { question: 'What is JUPEB and how does it work?', answer: 'JUPEB (Joint Universities Preliminary Examinations Board) is a Nigerian examination body that conducts the JUPEB programme — a 1-year intensive pre-university programme that prepares students for university admission. JUPEB is accepted as an alternative to JAMB for direct entry admission into Nigerian universities (200+ universities accept JUPEB results). Students choose three subject combinations from Arts, Sciences, or Commercial subjects and study them at a JUPEB accredited centre for one academic year. After passing the JUPEB examinations, students gain direct entry (200 level) into Nigerian universities, skipping the first year.' },
    { question: 'What are the JUPEB subject combinations?', answer: 'JUPEB candidates choose a three-subject combination relevant to their intended university programme. Popular combinations include: Sciences (Physics/Chemistry/Mathematics, Physics/Chemistry/Biology, Chemistry/Biology/Mathematics), Commercial (Economics/Government/Accounting, Economics/Government/Mathematics, Commerce/Accounting/Economics), and Arts (Government/History/Literature, Government/Economics/Literature). The choice of combination determines which university courses a student is eligible for. Students must verify their combination is accepted by their target university and intended course of study before enrolling in a JUPEB programme.' },
  ],
  'nce-cours': [
    { question: "What is NCE, which body awards it, and what is it used for?", answer: "The Nigeria Certificate in Education (NCE) is the minimum teaching qualification for the Nigerian secondary classroom. It is awarded by accredited Colleges of Education and regulated by the National Commission for Colleges of Education (NCCE). It is primarily a teaching credential, but it also carries weight as an alternative route into university education programmes, so candidates weigh it against a full B.Ed. before enrolling. Source: ncce.gov.ng" },
    { question: "Who is eligible to apply for the NCE programme, and how is admission actually conducted?", answer: "Admission is handled through the Joint Admissions and Matriculation Board (JAMB) for federal, state and private Colleges of Education alike, in line with NCCE minimum standards, so candidates apply to JAMB rather than to an individual College. The academic floor is five credit passes at O-Level from WAEC, NECO or NABTEB, with English Language required and Mathematics plus the intended teaching subject typically demanded by the particular programme. Each College still sets its own combination and cut-off for its own session, so treat the national standard as the floor rather than as an offer. Source: ncce.gov.ng" },
    { question: "How is the NCE qualifying examination structured, and who sets the papers?", answer: "There is no single national NCE paper. Each accredited College of Education examines its own students through its own exam office, so the number of papers and their weight follow the course combination the student actually registered for rather than a fixed national pattern. Expect written course papers taken across the programme together with a teaching-practice component assessed as a school-based internship by college tutors. The practical consequence is that two candidates on different teaching subjects can face different paper sets, and anyone who changes College or subject mid-programme should confirm their own paper list with their exam office. Source: ncce.gov.ng" },
    { question: "What changes under the five-year NCE-to-degree programme from the 2026/2027 session?", answer: "The NCCE approved a Continuous Five-Year NCE-Degree Programme and directed Colleges of Education to implement it from the 2026/2027 academic session. It replaces the old split route, where a candidate finished a three-year NCE and then applied elsewhere for direct entry, with one continuous award inside a single institution: three years of the NCE followed by two further years of a degree component, graduating the student with both the NCE and a B.Ed. The separate four-year degree admission route at those Colleges was wound down at the same time, which is why anyone currently comparing NCE against a university B.Ed. should ask the College how its session is structured. Source: ncce.gov.ng" },
    { question: "Does an NCE certificate get you into a university B.Ed., and at which level?", answer: "Often, but not uniformly. NCE is widely accepted as the qualifying credential for direct entry into Bachelor of Education programmes at 200 or 300 level through JAMB Direct Entry, which is higher than the ordinary 100-level entry that O-Level and UTME buy you. It is the admitting university, not NCCE, that decides whether NCE counts at all and at which level, so read the direct-entry section of your specific university's admission brochure for the session rather than treating the level as automatic. Source: jamb.gov.ng and ncce.gov.ng" },
  ],
  'putme': [
    { question: 'What is PUTME and how does it work?', answer: 'PUTME (Post-UTME Screening Examination) is the screening examination conducted by individual state universities in Nigeria after JAMB. After scoring in JAMB, candidates who meet the cut-off mark for their chosen university must sit the university\'s PUTME to be considered for admission. Each state university sets its own PUTME exam pattern, date, and cutoff. Unlike JAMB which is national, PUTME is university-specific — candidates must apply to each university\'s PUTME separately after receiving their JAMB results. Polytechnics and colleges of education may have their own post-UTME equivalent.' },
  ],
  'toafa': [
    { question: 'What is TOAFA and which universities accept it?', answer: 'TOAFA (Test of Academic Fitness Award) is an examination conducted by Nigerian universities as part of their screening process for admission, particularly for candidates seeking direct entry or supplementary admission. TOAFA is used by some universities as an alternative or complement to JAMB and post-UTME scores when evaluating candidates. It tests general academic readiness, reasoning ability, and subject-specific knowledge at the secondary school level. The specific pattern and syllabus vary by university. Candidates should check their target university\'s admission handbook for whether TOAFA is accepted for their intended programme.' },
  ],
  'kpkpse': [
    { question: 'What is KP PMS and which posts does it recruit?', answer: 'The Khyber Pakhtunkhwa Public Service Commission runs the Provincial Management Service, advertised as PMS Officers in BPS-17, to recruit officers into the provincial civil service. Successful PMS officers are posted as Deputy Commissioner, Assistant Commissioner and to other secretariat and field administration posts, and selected candidates train at the Civil Services Academy before deployment. The commission itself is a constitutional body established under Article 242 of the 1973 Constitution and functioning under the Khyber Pakhtunkhwa PSC Ordinance 1978. Source: kppsc.gov.pk' },
    { question: 'How many stages does the KP PMS selection have, and what happens at each one?', answer: 'KP PMS runs as a staged recruitment: a PMS Screening Test first, then the written examination built from compulsory and optional papers, then psychological evaluation, and finally the viva voce for candidates who qualify at each earlier stage. The published KPPSC syllabus is explicit that the examination includes compulsory and optional subjects, with optional subjects carrying 600 marks in all and not more than 200 marks from a single group. That makes optional-paper selection part of the application itself, so a poor choice at submission time costs you a stage, not just a preference. Source: kppsc.gov.pk' },
    { question: 'What is the passing threshold for the PMS Screening Test?', answer: 'The commission raised the PMS Screening Test passing threshold from 40 percent to 50 percent with effect from 2 July 2025, and 50 percent is the figure still published on the official site. Clearing that cut-off only carries you into the written stage; it is not appointment. Plan against 50 percent as the floor and then clear it with margin, because ranking for civil service posts is decided in the written papers rather than at the screening gate. Source: kppsc.gov.pk' },
    { question: 'What is the latest official news on the PMS Officer examination?', answer: 'KPPSC publishes every cycle change as a public notice, so the authoritative answer is the IMPORTANT ALERTS block on kppsc.gov.pk rather than any coaching summary. On 12 October 2026 the commission posted a notice postponing the PMS Officers (BPS-17) written examination, which had been scheduled to run from 14 October 2026 to 31 October 2026. The whole window is postponed and the commission has announced no revised date, so treat the written stage as unscheduled until a fresh notice appears. For the previous cycle it had published the written examination result for the PMS Officer and AETO posts under Advertisement No. 02/2025 on 4 September 2026, then moved to document checking for the candidates who failed that written. Dates shift, so verify the live notice before booking travel or fixing a mock schedule. Source: kppsc.gov.pk' },
    { question: 'What eligibility and marking rules apply, and what should I confirm before registering?', answer: 'KPPSC notices require candidates to be domiciled in Khyber Pakhtunkhwa and to hold at least a second-division bachelor degree, with a general age limit of 21 to 30 years as on the advertisement cutoff date and statutory relaxation for backward-region candidates and in-service government employees. The screening stage is objective while the written stage mixes compulsory and optional papers, which means the deduction applied to a wrong MCQ answer, the application fee and the exact exam date are all cycle-specific and belong to the live advertisement. Nothing written here outranks that notice, so read it on kppsc.gov.pk before you apply. Source: kppsc.gov.pk' },
  ],
  'nlt': [
    { question: 'What is NLT and how is it used?', answer: 'NLT (National Level Test) is a standardized testing framework used by various Indian and international institutions for screening candidates in specific domains. In the Pakistani context, NLT may refer to the National Level Test for Engineering or Business programmes conducted by various testing bodies as part of their admission process. Candidates should check the specific board or institution using the NLT designation to understand the exact pattern, syllabus, and relevance to their intended programme of study.' },
  ],
  'sppsc': [
    { question: "What is the official syllabus structure for SPSC combined competitive examinations in 2026, and where can the PDF be downloaded?", answer: "The SPSC Combined Competitive Examination (CCE) begins with a combined objective screening test — a single MCQ paper (not several separate 100-MCQ papers) covering English, General Knowledge with Pakistan and Sindh affairs, Islamic Studies/Ethics, and general science and current affairs — where each question carries one mark. Candidates who clear the screening sit the descriptive Main Examination, which has compulsory and optional papers as listed in the official syllabus schedule. Because the exact subject weightage is revised between cycles, download the consolidated syllabus PDF under the Syllabus tab at spsc.gos.pk and follow that rather than any third-party summary. Source: spsc.gos.pk" },
    { question: "What is the marking scheme and qualifying percentage for SPSC written examinations in 2026?", answer: "For the 2026 CCE cycle the combined MCQ screening test carries one mark per question with no negative marking, and candidates must clear the qualifying cut-off (around 33%) to be called for the descriptive Main examination. The Main examination is a written descriptive stage followed by a viva voce / interview, and final merit is computed from the written and interview scores combined. The exact number of Main papers, their marks, and the interview weightage differ by the post and recruitment, so always confirm them against the current advertisement and syllabus schedule published on spsc.gos.pk before planning your attempt. Source: spsc.gos.pk" },
    { question: "What is the age limit and domicile requirement for SPSC posts advertised in 2026?", answer: "General-age candidates applying to SPSC posts in 2026 must be between 21 and 30 years on the closing date, computed against the date advertised in the notification. Sindh domiciled applicants receive 3-year general relaxation, raising the upper ceiling to 33 years, with additional 5-year relaxation for female, minority, and special-person categories per SPSC recruitment rules. Possession of a valid Sindh PRC (Permanent Residence Certificate) is mandatory at document-verification stage, and candidates of Pakistani origin holding Sindhi-speaking eligibility may apply under the local-quota seats. Source: spsc.gos.pk" },
    { question: "Which SPSC 2026 advertisement should candidates monitor for syllabus revisions and corrigenda?", answer: "Aspirants should bookmark the \"ADVERTISEMENTS\" and \"Notifications\" sections of the official portal, where SPSC publishes consolidated corrigenda whenever a subject weightage, paper pattern, or optional group is amended. Always reconcile any downloaded syllabus PDF with the latest corrigendum number before finalising an optional-subject combination, and confirm marks, paper counts and interview weightage against the specific post advertisement you are applying for. Treat unofficial coaching summaries with caution — only the notification and syllabus on spsc.gos.pk are authoritative. Source: spsc.gos.pk" },
    { question: "How should a Sindh-aspirant structure a 6-month study plan for SPSC 2026 using the official syllabus?", answer: "Divide the six-month window into three blocks aligned with the published syllabus: months 1–2 cover General Knowledge & Pakistan Studies (150 MCQs/day target, focus on post-2018 constitutional amendments and Sindh-specific history), months 3–4 tackle General Science, Mathematics, and Current Affairs (with daily Dawn and Jang editorial reading logged in a register), and months 5–6 rotate through English Composition précis, essay, and Islamiat/Ethics, ending with three full-length MCQ mocks scored against the 33% paper-wise cutoff. Reserve the final fortnight for viva preparation using gazetted interview syllabi. Source: spsc.gos.pk" }
  ],
  'mcat': [
    { question: "What is the official syllabus structure for the MDCAT 2026 test, and how is the subject-wise weightage distributed across Biology, Chemistry, Physics, and English?", answer: "The PM&DC uniform curriculum publishes the split outright: Biology carries 45% of the paper at 81 questions, Chemistry 25% at 45, Physics 20% at 36, English 5% at 9 and Logical Reasoning 5% at 9, totalling 180. The five sections map to the FSc Pre-Medical syllabus, with Biology drawing on both zoology and botany and Logical Reasoning on general aptitude. Plan revision time against those proportions rather than an assumed split — Biology alone is nearly half the paper. For MDCAT-2026 the PM&DC confirmed the 2025 curriculum applies. Source: pmdc.pk" },
    { question: "What is the MDCAT 2026 registration window, fee structure, and the documents required at the time of online application through PMC?", answer: "Registration for MDCAT 2026 opens via the PMC online portal with a typical fee of PKR 6,000 for local candidates and PKR 18,000 for overseas Pakistani students, payable through 1Bill, JazzCash, or bank challan. Applicants must upload a recent photograph, CNIC/B-Form, domicile certificate, and HSSC Part-I or Part-II marks sheet. The application window generally remains open for three to four weeks during July–August 2026. Submit early to avoid portal congestion during the final 48 hours. Source: pmc.gov.pk" },
    { question: "What is the marking scheme, negative marking rule, and total duration for the MDCAT 2026 paper-based test?", answer: "There is no negative marking: a wrong or unattempted question scores zero rather than deducting marks, so a guess can never take you below zero. The paper is 180 multiple-choice questions sat as a paper-based test in 3 hours, so budget about a minute a question across the full 180. What is worth planning is pacing and accuracy, not a deduction rule — there is none. Sit full-length papers on paper under timed conditions, because the real paper is not a computer-based test. Source: pmdc.pk" },
    { question: "What is the minimum passing percentage for MDCAT 2026, and how are merit and aggregate calculated for admission to MBBS and BDS programmes?", answer: "The PM&DC uniform curriculum sets minimum pass marks of 55% for admission to a medical college and 50% for a dental college. Those are the regulatory floors, not the cut-off that gets you a seat. The merit cut-off is set higher and separately by the admitting university for each province — UHS for Punjab, DUHS for Sindh, KMU for Khyber Pakhtunkhwa, SZABMU for Baluchistan, BUMHS for Gilgit-Baltistan — and usually applies to a combined merit aggregate rather than the MDCAT score alone. Read your own university's rules before estimating competitiveness. Source: pmdc.pk" },
    { question: "Which provinces and overseas centres will host MDCAT 2026, and how many times can a candidate attempt the test under PMC regulations?", answer: "MDCAT 2026 will be held in a single window across all four provinces, Gilgit-Baltistan, AJK, and Islamabad, plus overseas centres in Riyadh, Dubai, Abu Dhabi, Doha, and potentially Ankara and Kuala Lumpur. Under current PMC rules, a candidate may attempt MDCAT only once per admission cycle, and the score remains valid for one academic year. Verify your nearest centre list on the PMC website and book your preferred city before slots fill, typically 10 days after registration opens. Source: pmc.gov.pk" }
  ],
  'ppsc': [
    { question: "What is the PPSC entrance exam?", answer: "For a 2026 recruitment cycle, the Punjab Public Service Commission Combined Competitive Examination is Punjab's state-level route to recruitment for Group-A and Group-B government posts. Its assessment covers areas such as General Knowledge, English and Reasoning, plus Optional papers, and the selection process includes a written test followed by an interview. Treat this as a broad recruitment description, because posts and categories may advertise different combinations of prelims, mains, optional subjects and interview weight. Read the current PPSC advertisement before choosing an optional or planning equal time across subjects. Make a paper-by-paper timetable from the prescribed scheme, collect the required documents early, and use each official stage notice to confirm dates and eligibility. Source: ppsc.gop.pk" },
    { question: "Who is eligible to apply for the PPSC entrance exam?", answer: "For a 2026 recruitment cycle, PPSC eligibility is defined by the advertisement for the post and recruitment category, not by a permanent summary on an exam page. The stated baseline is a bachelor's degree from a recognised university and an age between 21 and 37 years. Reserved-category applicants receive the relaxations allowed by Punjab government rules. The original eligibility summary also requires Indian citizenship and a clean criminal record, with no pending case that disqualifies an applicant from government service. Before applying, compare your degree, birth date, citizenship and legal status against the official notification. Keep supporting certificates ready and ask PPSC to resolve any category-specific condition rather than assuming another year's relaxation applies to the current recruitment. Source: ppsc.gop.pk" },
    { question: "How can I register for the PPSC entrance exam?", answer: "Register for a 2026 PPSC entrance examination through the official Punjab PSC website rather than a third-party form. First create or access the applicant account, complete every field in the notice, and upload clear scans of your photograph, signature and identity proof in the prescribed format. Pay the stated application fee online by net banking, credit or debit card, or e-challan, then submit the form before the notified deadline. The portal generates a unique registration number after successful submission; print or save that record immediately. Check the fee receipt, category details and uploaded files, and keep the deadline visible because incomplete or unpaid applications may not enter the next selection stage. Source: ppsc.gop.pk" },
    { question: "What is the exam pattern and marking scheme for the PPSC entrance exam?", answer: "For the 2026 PPSC cycle, the entrance process has three described components. The Preliminary test is objective and contains 100 questions worth 2 marks each, for a total of 200 marks. The Main written examination uses descriptive answers across papers carrying 150–200 marks each. A 100-mark interview follows, and the composite score determines merit. Prepare for this structure by treating the objective prelim as a timed practice exercise, outlining Main answers in full sentences, and checking whether interview weight is relevant to your advertised post. Confirm paper sequence and duration in the current PPSC advertisement, because the same stage may apply different combinations of papers, and use only the official scheme when calculating preparation priorities. Source: ppsc.gop.pk" },
    { question: "What are the important dates for the PPSC entrance exam?", answer: "Use the Punjab PSC calendar to track the 2026 PPSC entrance cycle instead of relying on an unofficial month list. The usual sequence places the official notification in March, online registration in April, fee payment in May, the Preliminary test in June, the Main exam in August–September, and the interview in November–December. Treat those months as planning estimates because PPSC can change the notified dates. Save the advertisement, note its correction links, and begin document preparation before registration opens. Check the official site at the start of each stage for the exact closing time, exam city and fee-payment rule, then update your exam and interview schedule from the latest notice. Source: ppsc.gop.pk" }
  ],
  'ts-eamcet': [
    { question: 'What is TS-EAMCET and who is it for?', answer: 'TS-EAMCET (Telangana State Engineering, Agriculture and Medical Common Entrance Test) is conducted by the Telangana State Council of Higher Education (TSCHE) for admission to undergraduate professional programmes in Telangana state. It is a mandatory exam for admission to B.Tech, B.Pharm, B.Sc (Agriculture), and other professional courses in government and private colleges across Telangana. TS-EAMCET is specifically for students who have completed their Intermediate (Class 12) education in Telangana or Andhra Pradesh — it is the Telangana state-level equivalent of AP-EAMCET, with which it was combined before Telangana\'s formation in 2014. Only students belonging to Telangana are eligible for the convenor quota (70% of seats); the remaining 30% falls under management quota.' },
    { question: 'What is the TS-EAMCET exam pattern?', answer: 'TS-EAMCET asks 160 multiple-choice questions, and candidates get 3 hours (180 minutes) to work through them. The exam is conducted separately for two streams: Engineering (E) stream: Physics (40 questions), Chemistry (40 questions), Mathematics (80 questions). Agriculture & Medical (AM) stream: Physics (40 questions), Chemistry (40 questions), Botany (40 questions), Zoology (40 questions). Scoring gives +1 for each correct answer, with no deduction for an incorrect one. The Telangana council fixes its own exam centres and sets out how the paper is administered inside the EAMCET notification, so read that notice at eapcet.tgche.ac.in before assuming a computer-based paper. The syllabus is based on the Telangana Board Class 11-12 curriculum. Source: eapcet.tgche.ac.in' },
    { question: 'How does TS-EAMCET counselling and admission work?', answer: 'TS-EAMCET scores flow through TSCHE counselling, where the rank list is derived from the score and seats are filled in two categories: Category A, the 70% convenor quota allocated by the council based on rank and preference, and Category B, the 30% management quota filled by the institutions themselves, alongside a 15% supernumerary quota in B.E./B.Tech. colleges. Category B and supernumerary quota rules are published by the Telangana Council of Higher Education, and the counselling schedule comes out in the detailed admission notification. Seats still vacant after the regular rounds are filled through college-level spot admissions. Colleges commonly reached through TS EAMCET include JNTU Hyderabad, Osmania University College of Engineering, University College of Engineering (Autonomous), and VNR Vignana Jyothi Institute of Engineering. No body publishes a fixed rank-to-branch table, so treat any specific rank band circulating on coaching sites as unofficial: build your target from the opening and closing ranks published for that college and branch in the previous cycle. Source: tgche.ac.in for the Category B and supernumerary quota guidelines, and tgeapcetd.nic.in for the counselling notification.' },
  ],
  'accagl': [
    { question: "How is the ACCA qualification structured across the three levels for the 2026 exam year, and how many papers does a student need to clear before becoming eligible for membership?", answer: "The 2026 ACCA qualification is divided into three sequential levels: Applied Knowledge (3 papers — BT, MA, FA), Applied Skills (6 papers — LW, PM, TX, FR, AA, FM), and Strategic Professional (2 Essentials: SBL and SBR, plus 2 Options chosen from AFM, APM, ATX, AAA). That brings the total to a maximum of 13 papers. Membership additionally requires completing the Ethics and Professional Skills module and the Practical Experience Requirement (PER) of 36 months' relevant work. Plan your order so Applied Skills is cleared before attempting SBL. Source: accaglobal.com" },
    { question: "What are the confirmed ACCA exam sitting windows and computer-based exam availability for Applied Knowledge, Applied Skills, and Strategic Professional papers in 2026?", answer: "Applied Knowledge and Applied Skills papers run on-demand computer-based exams (CBEs) at any of ACCA's 400+ approved centres, with four fixed result-release windows in March, June, September, and December 2026. Strategic Professional Essentials (SBL, SBR) and the four Options (AFM, APM, ATX, AAA) are CBEs but only available in two sittings — June 2026 and December 2026. Book at least six weeks ahead to secure your preferred centre and slot. Source: accaglobal.com" },
    { question: "What is the standard ACCA exam entry fee for each paper tier in the 2025/2026 schedule, and how does the early-bird discount change the amount payable?", answer: "For exams sitting in the 2025/2026 session, ACCA's published standard fee is GBP 92 per Applied Knowledge and Applied Skills paper, and GBP 127 per Strategic Professional paper (both Essentials and Options). ACCA operates an early-bird rebate: if you book by the published early deadline (roughly six weeks before the session), Applied Knowledge/Skills drops to GBP 76 and Strategic Professional to GBP 110. Membership subscription is billed separately. Source: accaglobal.com" },
    { question: "Which ACCA Strategic Professional Option papers have revised syllabuses for the 2026 exam year, and what should a candidate re-attempting these papers study differently?", answer: "The four Option papers — AFM (Advanced Financial Management), APM (Advanced Performance Management), ATX (Advanced Taxation), and AAA (Advanced Audit and Assurance) — carry updated syllabuses effective from the 2026 exam year. Changes typically refresh technical content, ethics weighting, and case-study style to mirror current IFAC, IFRS, and IAESB standards. Re-sitters should download the latest syllabus study guide from ACCA Connect, compare it against their 2025 notes, and re-prioritise any new learning outcomes before sitting in June or December 2026. Source: accaglobal.com" },
    { question: "What is the uniform pass mark across ACCA exams, how is it scaled for CBEs, and what score should a borderline candidate realistically target to be confident of clearing?", answer: "Every ACCA paper — BT through AAA — uses a 50% pass mark, regardless of whether it is a multiple-choice Applied Knowledge CBE, a scenario-based Applied Skills CBE, or a constructive-response Strategic Professional exam. For CBEs, the 50% is applied directly to the scaled score; for written Strategic Professional papers, examiners mark to a 100-point rubric then convert to the same 50% threshold. Target 55–60% in mock exams to leave a safe buffer for exam-day variance. Source: accaglobal.com" }
  ],
  'law-apt': [
    { question: "What papers does the Sri Lanka Law College entrance examination actually comprise?", answer: "The SLLC General Entrance Examination comprises papers testing General Intelligence (IQ), General Knowledge, and Language skills — there is no separate 'Legal Aptitude' paper in the SLLC scheme. The exact paper-wise structure and mark split are published in the gazette notice for each cycle on sllc.ac.lk; prepare from that notice and past papers rather than third-party syllabi, which frequently describe papers that do not exist. Source: sllc.ac.lk" },
    { question: "When is the SLLC entrance notification expected, and how do candidates apply?", answer: "The official notification for each cycle is gazetted and mirrored on the sllc.ac.lk examinations page, with the online application window running for roughly four to six weeks thereafter. The application fee for the cycle is stated in the gazette notice — verify it there before paying, as figures circulating on coaching sites are often outdated. Applications are submitted through the official portal linked from doenets.lk, late submissions are not accepted, and scanned A/L certificate and NIC copies should be prepared in advance. Source: doenets.lk" },
    { question: "What are the confirmed eligibility criteria and age-related rules for appearing in the Law Aptitude 2026?", answer: "Candidates must have sat the G.C.E. A/L examination in any stream or hold an equivalent qualification recognised by the University Grants Commission of Sri Lanka. A minimum of three passes at A/L is required, and results may be pending at application stage provided the candidate has completed the examination. There is no upper age limit prescribed for the 2026 cycle, but applicants must be Sri Lankan citizens or permanent residents. Reserved-seat applicants must attach category certificates during submission. Source: sllc.ac.lk" },
    { question: "What pass criteria apply in the SLLC entrance examination?", answer: "For 2026, SLLC sets the qualifying rules for its entrance examination in the official gazette notice. Admission ranking depends on aggregate performance across the papers, so a strong result in one section may not compensate for failing the cycle's stated minimum in another. Do not copy per-paper thresholds from an old coaching page or from a different year's notice. Download the gazette for the year you are sitting, extract every subject-level requirement, and mark the total-score condition separately. Use those confirmed limits to set sectional mock-test targets, then retest weak areas until your planned scores exceed the published requirement with margin. Recheck the gazette again if SLLC issues an amendment before registration closes or the test begins. Source: sllc.ac.lk" },
    { question: "Has the SLLC entrance syllabus changed recently, and what should aspirants revise?", answer: "SLLC announces any structural changes in the gazette notification for the relevant intake — no 'Legal Aptitude expansion' has been announced, and the exam remains a General Intelligence (IQ), General Knowledge, and Language screening. Download the latest notice from sllc.ac.lk, align your study plan to the papers it actually lists, and practise IQ and language questions from past papers, which reward speed and accuracy over legal knowledge. Source: sllc.ac.lk" }
  ],
  'law-ent-tz': [
    { question: "Is there a national law entrance examination for LLB admission in Tanzania?", answer: "No. Undergraduate LLB admission in Tanzania is grade-based, not exam-based — the Tanzania Commission for Universities (TCU) admission criteria rank applicants on their ACSEE (A-level) principal passes, and applications are lodged directly with the universities or through the central admission system. No separate law entrance paper is sat anywhere in the cycle. Preparation therefore means maximising ACSEE performance and meeting the specific university's programme requirements. Source: tcu.go.tz" },
    { question: "Which grades does TCU require for LLB admission in Tanzania?", answer: "TCU's undergraduate benchmark is two principal passes at ACSEE totalling at least 4.0 points, computed on the official scale A=5, B=4, C=3, D=2, E=1 — take care, some coaching sites quote this scale inverted. A CSEE credit profile that includes English strengthens the application, and individual universities (UDSM, Mzumbe, OUT and others) may set higher programme-specific requirements for LLB. Verify your result slip on the NECTA portal before applying. Source: tcu.go.tz" },
    { question: "When and how do applicants apply for LLB programmes in Tanzania?", answer: "University application windows typically open around May–July for the academic year starting later in the year, with applications submitted directly to the institutions or through the central admission channel TCU coordinates. Application fees are set per university — confirm the amount and the mobile-money or bank payment channel in the university's own admission notice, not third-party sites. Late or incomplete applications (especially wrong NECTA index numbers) are the most common rejection cause, so double-check entries before submitting. Source: tcu.go.tz" },
    { question: "Is there a marking scheme or pass mark to prepare for in Tanzanian LLB admission?", answer: "No — since there is no entrance paper, there is no marking scheme or pass mark. Selection is computed from ACSEE grades under TCU's points system, so every hour of preparation belongs to your A-level principal subjects. Once admitted, first-year LLB coursework introduces constitutional law, criminal law, contract, and legal method, and early familiarity with those areas is useful orientation rather than an admission requirement. Source: tcu.go.tz" },
    { question: "Which Tanzanian statutes are useful early reading for an incoming LLB student?", answer: "For students preparing to start an LLB, early familiarity with the Penal Code Cap. 16 and Criminal Procedure Act (criminal law), and the Land Act Cap. 113 with the Village Land Act Cap. 114 (land law), gives a head start on first-year coursework — but none of these are tested in any pre-admission examination, because Tanzanian LLB admission is grade-based. Treat statute reading as orientation, not entrance prep. Source: tcu.go.tz" }
  ],
  'law-ent-uga': [
    { question: "What does the LDC pre-entry examination actually cover for admission at ldc.ac.ug?", answer: "The Law Development Centre (LDC) pre-entry examination screens applicants for the postgraduate Bar Course — the Diploma in Legal Practice at LDC Kampala — it is not an undergraduate law-school entrance. The paper tests core legal knowledge from the LLB curriculum (constitutional law, contract, criminal law, legal method), comprehension, and legal reasoning. LDC publishes the exact format with each intake's call for applications on ldc.ac.ug, so work from the current notice rather than older or third-party syllabi. Source: ldc.ac.ug" },
    { question: "Who is eligible to sit the LDC pre-entry examination?", answer: "An LLB degree from a recognised university is the core prerequisite — the LDC pre-entry exam admits to the postgraduate Diploma in Legal Practice (Bar Course), so school-level certificates alone do not qualify you. Ugandan and non-Ugandan LLB holders may apply, uploading their degree transcript during online registration. Verify the full document checklist in the current call for applications on ldc.ac.ug before paying any fee. Source: ldc.ac.ug" },
    { question: "What is the marking scheme and pass mark for the LDC pre-entry examination?", answer: "The paper is scored out of 100 with a 50% pass mark, and the Law Development Centre (LDC — the statutory body that runs Uganda's Bar Course, not a district council) may apply a higher effective cut-off depending on available Bar Course places in a given intake. There is no negative marking, so attempt every question, and manage time to cover the full paper. The 2025 reinstated pre-entry sitting recorded a pass rate of roughly 69%, so the exam is selective but passable with solid LLB fundamentals. Source: ldc.ac.ug" },
    { question: "When does LDC pre-entry registration open, and what should applicants budget for?", answer: "LDC advertises the pre-entry exam in a call for applications on ldc.ac.ug — for the 2026 intake, applications ran from September 2025, the exam was sat in late 2025, and the admitted cohort began in January 2026. Expect the next cycle to follow the same September-to-December rhythm, and confirm the application fee and the mobile-money/bank payment channel in the current official notice rather than secondary sites. Complete payment well before the deadline to clear bank reconciliation delays. Source: ldc.ac.ug" },
    { question: "Which materials should an LDC pre-entry candidate revise?", answer: "Revise your LLB core materials — Uganda's 1995 Constitution, contract and criminal law fundamentals, and legal method — since the pre-entry tests what a law graduate is expected to retain. Past pre-entry papers, where published on ldc.ac.ug, are the best format guide, and the reinstated sittings from 2025 onward are the closest pattern match. Pair this with current legal affairs from the New Vision and Daily Monitor archives for the preceding six months. Source: ldc.ac.ug" }
  ],
  'aau': [
    { question: "What does the AAU 2025/2026 academic calendar actually tell an undergraduate about when semester exams fall?", answer: "The Addis Ababa University academic calendar for the 2025/2026 academic year lists the first semester running from September 2025 through January 2026, with the final examination window scheduled during the last three to four weeks of January 2026. The second semester begins in February 2026 and concludes with end-of-semester examinations in late June 2026. Summer programs and distance education follow separate compressed schedules, but undergraduate students on the regular track should mark the January and June examination periods as immovable deadlines. Always re-check the SIS portal two weeks before exams for any date revisions issued by the Office of the Registrar. Source: aau.edu.et" },
    { question: "How is the AAU undergraduate syllabus organized, and where can a student download the official course catalog for their department?", answer: "AAU syllabi are structured department by department, with every course assigned a unique course code, credit-hour weight, and prerequisite chain approved by the Academic Commission. Each department publishes a course catalog that lists compulsory, elective, and common-course requirements, and undergraduate degrees typically require completion of between 120 and 180 credit hours depending on the program. To audit your syllabus, log into the AAU SIS portal, open the \"Curriculum\" tab for your department, and download the PDF catalog tied to your admission cohort year, not the latest version online. Source: aau.edu.et" },
    { question: "What grading system does AAU use for 2025/2026 semester examinations, and what is the minimum pass mark?", answer: "AAU applies the Ethiopian Higher Education Proclamation No. 1152/2019 grading scale, which converts raw marks into letter grades from A+ through F. A passing grade requires at least a C, equivalent to 50% or higher in most faculties, though some departments set internal thresholds above 50% for professional courses. Grades are accompanied by grade-point values on a 4.0 scale used to calculate semester and cumulative GPAs. Students who fail must register for the next available offering as a repeat course, which is recorded separately on transcripts. Source: moe.gov.et" },
    { question: "Where and when does AAU publish semester examination results for the 2025/2026 cycle?", answer: "End-of-semester results are released through the AAU Student Information System portal, typically within three to four weeks after the final examination paper is completed, meaning January 2026 semester-one results are expected by late February 2026. The Office of the Registrar signs off on the published grade lists before they go live, and incomplete or withheld grades appear with an \"I\" or \"NG\" code until cleared. Students who spot an error in marks have a 10-working-day window to submit a grade-correction request through their department head. Source: aau.edu.et" },
    { question: "Which Ministry of Education policies should an AAU 2026 candidate know before sitting semester exams?", answer: "The Ministry of Education sets the umbrella rules every Ethiopian public university, including AAU, must follow, and three documents matter most during exam season: the Higher Education Proclamation No. 1152/2019 covering degree classifications and assessment standards, the Senate Legislation governing examination misconduct penalties, and the annual admission and registration directive published each June. Reviewing the MoE admissions page before registration ensures you meet any new credit-load limits, which for the 2025/2026 cycle cap undergraduates at 21 credit hours per semester. Source: moe.gov.et" }
  ],
  'uppm': [
    { question: "What is the official UniMAP admission portal URL and which programmes are open for UPPM intake?", answer: "The UniMAP Undergraduate Admission portal is hosted at admission.unimap.edu.my and is the only sanctioned channel for direct UniMAP applications. UniMAP advertises Bachelor of Engineering programmes across Mechatronics, Electrical, Mechanical, Manufacturing, Chemical, and Civil specialisations, plus a Bachelor of Computer Engineering (Artificial Intelligence) track. Application windows typically run from February to early April each year, with the September intake closing registration roughly 6 weeks before orientation. Always cross-check the programme quota column and the current processing-fee amount on the portal itself, as both vary year to year. Source: admission.unimap.edu.my" },
    { question: "How does UPUOnline via upu.mohe.gov.my differ from the direct UniMAP portal for applicants?", answer: "UPUOnline is the Ministry of Higher Education centralised gateway that routes Malaysian applicants to public university Bachelor programmes, including UniMAP's engineering offerings, while admission.unimap.edu.my handles direct and international applications. Malaysian applicants with STPM/Matriculation/Foundation results must first complete the UPUOnline profile — access is via a UPU PIN costing about RM10.60 — and rank their UniMAP choices. UniMAP then releases interview or merit shortlists roughly 6–8 weeks after UPUOnline closes. Missing the UPUOnline deadline removes you from the UniMAP merit pool for that intake. Source: upu.mohe.gov.my" },
    { question: "What are the minimum entry qualifications for UniMAP engineering programmes?", answer: "UniMAP requires a minimum CGPA of 3.00 in STPM (Science stream) with passes in Mathematics and one Physical Science at grade B- or higher, or an equivalent Foundation/Matriculation CGPA. For Diploma holders, a strong CGPA with credits in Mathematics and Physics at SPM level is required, and international applicants must submit an IELTS 5.5 or TOEFL iBT 46 result dated within 24 months. UniMAP does not publish official programme cut-off points — treat any precise 'closing merit score' figures from third-party sites as unverified, and list a second-choice programme as a hedge. Source: unimap.edu.my" },
    { question: "When does the application window open, and what fees actually apply?", answer: "For the 2025/2026 intake, UPUOnline registration ran February to end-April 2025, and the 2026/2027 cycle is expected to mirror the same February–April pattern — confirm on upu.mohe.gov.my by mid-January. UPUOnline access is via a UPU PIN costing about RM10.60 from BSN, and UPU is a Malaysians-only channel — international applicants apply directly to UniMAP, whose direct-application fee is listed on admission.unimap.edu.my. Fees are non-refundable once the merit list is published, so withdraw or switch programmes before submission if your plans change. Source: upu.mohe.gov.my" },
    { question: "What supporting documents must be prepared before starting the UPPM 2026 UniMAP online application?", answer: "Prepare scanned colour copies (PDF, under 5MB each) of your MyKad, SPM certificate with all subject grades, STPM/Matriculation/Foundation transcript, a recent passport-sized photo, and co-curricular transcripts for the merit-score calculation. International applicants additionally need a certified English-translation of academic records and a valid IELTS/TOEFL score report. Upload via admission.unimap.edu.my during the open window; incomplete submissions are auto-rejected within 48 hours. Keep soft copies of every receipt and confirmation slip until registration week in September 2026. Source: admission.unimap.edu.my" }
  ],
  'lsat-ca': [
    { question: "How many times can a Canadian applicant sit the LSAT, and does a cancelled score count against the limit?", answer: "LSAC permits five LSAT administrations within the current reportable score period, which began in July 2021, and anything sat before September 2019 is excluded from that count. The counting rule is not what candidates expect: a score you cancel does count as one of your five, whereas an absence or a withdrawal does not. That distinction makes withdrawing rather than cancelling the rational move when weather, illness or scheduling ruins a sitting, because a withdrawal returns the attempt to you and a cancellation spends it. A second bar sits on top of the numeric cap. Once you record a 180 you are barred from retaking for the current and five past testing years, which is exactly the span LSAC reports scores to law schools. Source: lsac.org" },
    { question: "Is the LSAT moving back to in-person testing, and what happens to remote sitters?", answer: "From the August 2026 administration, LSAC is moving almost all United States and international test takers back to in-person delivery at a digital testing centre. Remote testing survives only as an exception, granted for narrow grounds such as certain medical accommodations or extreme distance from a centre, and the page carries a further condition: a candidate granted a Remote Testing Exception must run their smartphone as a second camera throughout the session. If you were planning around live remote proctoring as the default, that plan no longer matches the published policy. Both modalities still run through LawHub, so the practice interface is the same whichever seat you get. Source: lsac.org" },
    { question: "Why has my score not been released even though I finished the multiple-choice paper?", answer: "For a first-time test taker the hold is the writing sample, not the score. LSAT Argumentative Writing is a separate, unscored, on-demand exam proctored online through software running on your own computer, and it is included in your registration fee rather than charged again. It only opens in your LSAC account eight days before your administration date, so a candidate who registers late has a narrow window. Your score releases at 9 a.m. ET on the published release date for that sitting, but only once a writing sample is approved on file and no holds sit on your account. Candidates who took the earlier LSAT Writing during the current reportable period keep that sample and need not retake it. Source: lsac.org" },
    { question: "Can I sit LSAT Argumentative Writing at a test centre, and what are the rules that catch candidates out?", answer: "No — only the multiple-choice portion can be taken at a test centre. Argumentative Writing stays in on-demand, remotely proctored format, available twenty-four hours a day, every day of the year, so you choose the slot. Three practical rules matter more than the format. Scratch paper is not permitted, so rehearse typing a complete argument without paper. The proctor reads instructions aloud unless you hold an approved accommodation. Remote candidates may not wear headphones, earbuds or anything similar apart from a soft, non-electronic, generic foam earplug, whereas in-centre candidates may use only the headphones assigned to them at the station. The sample must be processed and approved before it reaches your file, which is why LSAC advises completing it as early as possible. Source: lsac.org" },
    { question: "What ID and identification rules apply at a Canadian LSAT testing centre?", answer: "You must present a physical, valid international passport, or a physical, valid government-issued photo ID issued by the United States, a US territory, or Canada. A photograph or photocopy of the document does not satisfy this. The document may be current or expired within three months of your test date. The rule that fails candidates is the name match: the first and last name printed on your ID must correspond exactly to the legal first and last name on your LSAC account, so a name change has to be made on the Profile page in your account before test day rather than explained at the desk. Source: lsac.org" }
  ],
  'dat': [
    { question: "How many times can you take the DAT, and what happens after three attempts?", answer: "Attempts are capped, and a permission gate appears before the cap. The ADA requires you to wait 60 days between testing attempts, with a maximum of four administrations permitted during any 12-month period. Candidates with three or more attempts must apply for permission to test again, supplying evidence of an application to dental school within the previous 18 months, such as a submitted ADEA AADSAS application, a letter of rejection, or a letter on school letterhead from an admissions officer or health-profession advisor. Those requests go in writing to DATexam@ADA.org. After a fifth attempt you may retest only once per 12-month period. The ADA states these retest policies are not subject to appeal. Source: ada.org" },
    { question: "The DAT score scale changed — what is reported now, and how do you read an old score?", answer: "Since 1 March 2025 the ADA reports DAT results on a three-digit scale running from 200 to 600 in 10-point increments, replacing the previous reporting scale of 1 to 30. The ADA publishes a concordance table so an older score can be converted before you compare two attempts: an Academic Average of 18 on the old scale is approximately 390 on the new one, and a Quantitative Reasoning score of 15 is approximately 340. A percentile-rank table accompanies it, based on a national normative sample of more than 30,000 DAT attempts over a two-year period. Without converting first, a raw jump from an old score to a new one tells you nothing about whether you actually improved. Source: ada.org" },
    { question: "What does the DAT cost, and which extra fees catch candidates by surprise?", answer: "The ADA lists a 2026 examination fee of $580, covering administration and score reporting to the schools and programs you selected at the time of application. The optional extras are charged separately: a score report requested after the application window costs $55 per report, an optional score audit costs $105 and must be requested within 30 days of your testing appointment, and an eligibility extension costs $150, buys 45 additional days and is available once per submitted application. Fees are non-refundable and non-transferable, and the ADA states an assigned appointment that is not taken still forfeits the fee, so an unready sitting is expensive. Source: ada.org" },
    { question: "Which scores does the DAT actually report, and how is the five-hour session divided?", answer: "A result carries an Academic Average plus section subscores: Survey of Natural Sciences, with Biology, General Chemistry and Organic Chemistry reported individually, alongside Perceptual Ability, Quantitative Reasoning and Reading Comprehension. The ADA sets no passing score, so each dental program applies its own threshold to those subscores. Timing works out at 90 minutes for the Natural Sciences, 60 for Perceptual Ability, an optional 30-minute break, 60 for Reading Comprehension and 45 for Quantitative Reasoning, framed by an optional 15-minute tutorial at the start and an optional 15-minute survey at the end, for five hours and fifteen minutes in total. Report to the centre at least 30 minutes before your appointment. Source: ada.org" },
    { question: "What has to be in order before the day of the DAT itself?", answer: "Three things catch candidates out, and two of them are administrative rather than academic: the name-match rule and the booking lead time, both set out in the eligibility section above. Read them before you pay a Prometric fee, because each one costs the appointment itself rather than the booking slot. The third is geographic: the test is not offered in the province of Quebec, so a Quebec-based candidate has to plan to travel or look at the Canadian DAT instead. Source: ada.org" }
  ],
  'sgpat': [
    { question: "What subjects and weightage should an SGPAT 2026 aspirant expect in the SCFHS accreditation exam syllabus?", answer: "The SGPAT blueprint is structured around clinical competency domains mapped to the SCFHS professional classification for allied health pharmacists. Expect heavy emphasis on pharmaceutics, pharmacology, medicinal chemistry, pharmacognosy, clinical pharmacy, hospital pharmacy practice, drug regulatory affairs, and pharmaceutical calculations, with sub-weighting on pharmacotherapy case management. The blueprint PDF on the etec portal lists topic percentages and recommended references. Download the latest specification document, tally marks per domain, and prioritise high-weight clinical sections first. Source: etec.gov.sa" },
    { question: "When does the SGPAT 2026 registration window open, and what is the confirmed exam fee in SAR?", answer: "The 2026 testing cycle is published on the etec Exam Calendar page, with registration typically opening 8–10 weeks before each sitting and closing roughly 14 days prior. The booking portal displays the current fee in SAR before payment confirmation, and the amount must be settled via approved Saudi payment methods (Mada, Apple Pay, credit card) to lock a seat. Sittings run multiple times per quarter. Check the calendar monthly, set a reminder two weeks before close, and keep your MumarisPlus profile verified to avoid rejection. Source: etec.gov.sa" },
    { question: "What is the computer-based test format, duration, question count, and pass mark for SGPAT 2026?", answer: "SGPAT is delivered as a single-sitting, computer-based test at etec-approved centres inside Saudi Arabia. The current specification lists approximately 150–200 multiple-choice questions across clinical and basic pharmaceutical sciences, with a total seat time of roughly 3 hours including a short tutorial and optional break. Scoring uses a scaled score, and the pass mark is fixed by SCFHS rather than by relative ranking. Read the official specification PDF for the exact item count and scaled-score threshold before scheduling. Source: etec.gov.sa" },
    { question: "What eligibility documents and primary qualification criteria does SCFHS require before booking SGPAT 2026?", answer: "Candidates must hold a recognised primary pharmacy qualification — BPharm or equivalent — from an institution accredited in its country of origin, and the qualification must be verifiable through SCFHS. Required uploads on the etec portal include the degree certificate, transcript, internship completion, professional classification request, national ID or Iqama, and a passport-style photo. DataFlow or PSV reports may be requested for non-Saudi graduates. Start MumarisPlus document submission 60–90 days early to prevent eligibility delays. Source: etec.gov.sa" },
    { question: "What is the retake policy, waiting period, and validity of an SGPAT pass result for SCFHS classification?", answer: "SGPAT follows a fixed attempt cap per testing year and enforces a mandatory waiting period — typically 90 days — between unsuccessful sittings, after which a new booking and fee are required. Each pass result remains valid for a defined window tied to the SCFHS MumarisPlus eligibility letter used for professional classification and renewal. After validity expiry, re-attempt may be required. Track your eligibility-letter expiry date inside MumarisPlus and schedule any retake well before classification lapses. Source: etec.gov.sa" }
  ],
};

// Sister and sibling exam aliases for unified FAQ coverage
// UPPSC RO/ARO is NOT a shorter version of UPPSC PCS. Both are run by the
// Uttar Pradesh Public Service Commission and both abbreviate to "UPPSC", so
// search hands you the PCS page by default. Aliasing this key to 'up-psc' gave
// RO/ARO applicants a PCS answer set: a third stage and a 100-mark personality
// test that RO/ARO does not have, Prelims at 400 marks across two papers when
// RO/ARO Prelims is a single screening paper, an upper age limit of 42 when
// RO/ARO's is 40, and an application fee RO/ARO never quoted. Every one of
// those numbers is wrong for this page, and the query this page actually
// receives is "uppsc ro aro exam pattern". Written from this site's own RO/ARO
// data file and the Commission's published notices at uppsc.up.nic.in.
EXAM_FAQS['uppsc'] = [
  { question: "What is the UPPSC RO/ARO exam pattern, and how many stages does it have?", answer: "RO/ARO runs two eliminatory stages, not the three-stage PCS structure. The Preliminary Examination is a single objective MCQ screening paper covering General Studies, Hindi and Reasoning/Intelligence. Candidates who clear Prelims sit the Mains Examination, which is conventional written type with papers in General Hindi, General Studies I, General Studies II and an optional subject. Final selection rests on Mains performance. There is no personality-test or interview stage in the RO/ARO structure — if a page you are reading gives you a 100-mark interview as the final stage, you are reading about UPPSC PCS, a different examination from the same commission. For a clerical Review Officer or Assistant Review Officer post this matters: you are preparing for a screening-plus-written test with a stated merit list, not for the civil services pipeline. Source: uppsc.up.nic.in" },
  { question: "Is UPPSC RO/ARO the same exam as UPPSC PCS? Why do RO/ARO pages keep showing PCS details?", answer: "No, and the mix-up is easy to fall into because both are run by the Uttar Pradesh Public Service Commission and both shorten to UPPSC. PCS is the Provincial Civil Services or Combined State/Upper Subordinate Services exam, the recruitment route to district administrative and police posts, and it is built as Prelims, Mains and Interview. RO/ARO is the Review Officer and Assistant Review Officer examination, a clerical-level recruitment into the state secretariat and government departments, and it is built as Prelims and Mains with no interview. The two share a regulator, a portal and a subject list, which is exactly why search and AI summaries mix them: a question about 'UPPSC preparation' has no single answer until you name the post you are applying for. Fix the post first, then the pattern. If your target is a Review Officer or Assistant Review Officer vacancy, everything on this page applies to you and nothing about PCS stages does. Source: uppsc.up.nic.in" },
  { question: "What does the RO/ARO Prelims paper contain, and why do sources disagree about its total marks?", answer: "The syllabus is stable even where the total is not. Prelims draws on General Studies covering history, geography, Indian polity, economy, general science, environment and current affairs, on Hindi covering grammar, vocabulary and comprehension, and on reasoning and intelligence. The total has been described inconsistently across sources and across recruitment cycles: this site's own RO/ARO data file records the paper at 300 marks, while other published descriptions give 200 marks in total, or a split of 140 marks of General Studies alongside 60 of General Hindi. A pattern that moves between notifications means the number you plan against must come from the notification for the cycle you are actually sitting. The subject distribution is the thing to prepare, because it holds either way. Check the current information bulletin and advertisement on uppsc.up.nic.in before you fix a target score or build a timing plan around a total. Source: uppsc.up.nic.in" },
  { question: "What eligibility and age limit apply to RO/ARO, and how do they differ from PCS?", answer: "Candidates must be Indian citizens aged between 21 and 40 years in the general category, with a relaxation of 5 years for SC/ST candidates and 3 years for OBC candidates; the current notification governs, because limits have been revised between advertisements. A bachelor's degree from a recognised university is required. Two requirements are specific to the role and are the ones candidates most often overlook: proficiency in Hindi in both reading and writing is mandatory, and computer knowledge is essential for the work itself rather than merely for the exam. Candidates are also expected to be of good character and sound health, and domicile of Uttar Pradesh is preferred for certain reserved positions. Note the ceiling: PCS is commonly described with an upper limit of 42, while RO/ARO's is 40. Applying PCS figures to an RO/ARO application can put an eligible candidate over the age limit without warning. Source: uppsc.up.nic.in" },
  { question: "What happens after the RO/ARO Mains — is there an interview, and what is the typing test?", answer: "Selection completes on Mains performance, so there is no interview stage to prepare for. What does sit beyond the written papers is a typing and shorthand test for certain positions, which is a hiring test rather than a marks-addition stage, and it catches out candidates who never expected a second skill check after the Mains. Some notices attach it to a specific post category, so read whether the test applies to the vacancy you are applying for instead of assuming it applies to everyone. Mains itself is conventional type rather than MCQ, with papers in General Hindi, General Studies I and General Studies II plus an optional subject, and the paper-wise marks are set in the bulletin for the cycle. Keep the admit card and the marksheet until the final list is published, because posts in the state secretariat are frequently advertised in more than one notification and a candidate who misses a later advertisement cannot re-enter that cycle. Source: uppsc.up.nic.in" }
];
// Nepal's CMAT is NOT a country-variant of India's NTA CMAT. They share a name
// and nothing else. NTA runs the Indian paper (100 questions, 400 marks, 180
// minutes, +4/-1, bulletin on cmat.nta.nic.in, Indian-citizenship eligibility
// frame). Aliasing this key to 'cmat' told Nepali applicants that NTA sets the
// marking scheme and activates the bulletin, and served a 180-minute paper for
// an exam our own data file describes as 100 marks in 90 minutes. Nepal's CMAT
// is run by the Tribhuvan University Faculty of Management. Written from TU FOM's
// published model-question pattern and the university's admission notices.
EXAM_FAQS['cmat-nepal'] = [
  { question: "Who runs CMAT in Nepal, and how do I know which CMAT I am actually sitting?", answer: "Nepal's CMAT is run by the Faculty of Management at Tribhuvan University, and the university's own site is tudoms.org. Do not assume every Nepali management entrance is this one: the country runs three separate papers, and they are not interchangeable. Kathmandu University runs KUMAT, Pokhara University runs PUMAT for its fee-paying management admissions, and the Tribhuvan University Faculty of Management runs CMAT. Pokhara does not accept CMAT, so if Pokhara University or one of its partner institutions is your target, you are preparing for PUMAT, not CMAT. Confirm which test your target institution actually accepts before you pay a form fee, because preparing the wrong paper costs you a full cycle." },
  { question: "What is the CMAT Nepal paper actually made of?", answer: "The paper is 100 questions across five sections of 20 questions each — Verbal Ability, Quantitative Ability, Logical Reasoning, General Awareness, and Business and Economics — for 100 marks in 90 minutes. That is 100 marks, not 400, and 90 minutes, not 180. Because the five sections are equal at 20 items each and the clock is tight for the Quantitative and Logical sections, unattempted questions are the cheapest place to lose time. Work to the published section order on the TU Faculty of Management model question paper rather than to a coaching institute's reordered version. Confirm the current wording on tudoms.org before you lock a timetable." },
  { question: "What eligibility and application process apply, and what does the form cost?", answer: "The entrance asks for a bachelor's degree in any discipline from a recognised university; for its masters-level programmes the Faculty of Management has asked for a minimum CGPA of 2.0 or a second division, though the exact threshold is set per programme and per admission notice, so read the current notice rather than trusting a carried-over figure. Applications are submitted through the university's own portal at tudoms.org rather than through an NTA-style portal, and the master's-level form fee has been NPR 2,500, paid through the Dean's office account using ConnectIPS online payment. The bachelor's-level CMAT is charged separately and has been cheaper, so do not quote the master's fee to a friend sitting the other paper. Keep the payment receipt and your completed form until the merit list is published." },
  { question: "When is the exam held, and how do Nepali colleges use the score?", answer: "The Faculty of Management publishes the admission notice, the application window and the exam date on tudoms.org, and those dates move each cycle — a previous cycle ran its application across a window in the Nepali calendar with the exam scheduled separately, so treat any date you read on a coaching site as unverified until you have seen it on tudoms.org. Nepali colleges then run their own admissions on the CMAT result: institutions affiliated to Tribhuvan University, including the College of Development Management, publish their own combined entrance and admission notices on their own domains. That is why the CMAT is one paper with many downstream uses, and why you should check a specific college's notice instead of assuming one date covers every programme in the country." },
  { question: "Why do Nepali applicants keep getting India's NTA CMAT details — how do I avoid that mix-up?", answer: "It is an easy mistake to make, because NTA's CMAT in India genuinely exists, genuinely uses the same name, and genuinely has 100 questions — so a search for 'CMAT' hands you the Indian paper by default. From there every number is wrong for Nepal: NTA's paper is 400 marks in 180 minutes with +4 for a correct answer and −1 for a wrong one, its bulletin lives on cmat.nta.nic.in, its fee is in rupees, and its eligibility discussion is framed around Indian citizenship. Nepal's CMAT is 100 marks in 90 minutes, run by the Tribhuvan University Faculty of Management, with its fee in NPR. Treat any NTA URL, rupee fee or 180-minute timing as evidence that you have landed on the wrong country's paper. Also confirm the marking scheme on the current notice rather than assuming either version carries negative marking." }
];
// The generic 'gaokao' block covers both History and Physics streams, and told a
// science-stream (likao) candidate to consider History. This page is the science
// track only, so it gets its own block; no marks are quoted that the official
// provincial notices do not fix, because they differ by province.
EXAM_FAQS['gaokao-cn'] = [
  { question: "Which subjects make up the Gaokao science stream?", answer: "Under the 3+1+2 model, every candidate sits Chinese, Mathematics and one foreign language. The science stream takes Physics as the single first-choice subject, then chooses two more from Chemistry, Biology, Politics and Geography. Most engineering, medicine and natural-science candidates pick Chemistry and Biology, which is the combination this page's study plan covers. Source: neea.edu.cn" },
  { question: "How should a science-stream candidate split revision between Physics, Chemistry and Biology?", answer: "Weight revision by how your target programme scores you, not by an even split. Physics is mandatory and graded on raw marks, while Chemistry and Biology are usually converted to a ranked score in reformed provinces, so a steady error-log routine on all three matters more than cramming one. Use the Physics, Chemistry and Biology topic notes on StudyRoadmap to sequence topics, then check your province's scoring rules. Source: neea.edu.cn" },
  { question: "Where do I confirm this year's science-stream rules and dates?", answer: "Marks per paper, exam dates and subject-combination rules are set by each provincial examination authority, and the national framework comes from the Ministry of Education and NEEA at neea.edu.cn. Check your own province's notice before fixing a plan, because reformed and non-reformed provinces differ. Source: neea.edu.cn" },
];
